            // Update existing entry
            statsArray[i] = newStats;
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // If not found, add as a new entry
    size++;
    statsArray = realloc(statsArray, size * sizeof(UEStats));
    statsArray[size - 1] = newStats;

    pthread_mutex_unlock(&lock);
}

// Function to remove an existing UEStats entry
void removeEntry(int UE_ID) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < size; ++i) {
        if (statsArray[i].UE_ID == UE_ID) {
