['This task is a bit complex and involves several steps. It's also important to note that C does not have a built-in library function for DNS resolution, so we will be using `gethostbyname` from the `netdb.h` library. Also, this solution assumes that you are running on a POSIX compliant system (Linux, Mac OS etc).

Here is the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <unistd.h>
#include <sys/resource.h>

u_char* dns_resolution(const char* hostname, int *error) {
    struct hostent *host;
    if((host = gethostbyname(hostname)) == NULL){
        herror("gethostbyname");
        *error = 1;
        return NULL;
    }

    u_char* addr = malloc(sizeof(u_char) * 4); // Assuming IPV4 address
    if (addr == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        *error = 2;
        return NULL;
    }

    memcpy(addr, host->h_addr, 4);
    *error = 0;
    return addr;
}

int process_line(char* line) {
    char* token = strtok(line, ",");
    int count = 0;
    double sum = 0.0;

    while (token != NULL) {
        char *endptr;
        double val = strtod(token, &endptr);

        if (*endptr == '\0') { // If the string is numeric 
            count++;
            sum += val;
        }

        token = strtok(NULL, ",");
    }

    printf("Average: %lf\n", (count > 0) ? (sum / count) : 0.0);
    return 0;
}

int main() {
    // Limiting process's capabilities to prevent resource exhaustion
    struct rlimit limit;
    getrlimit(RLIMIT_NOFILE, &limit);
    limit.rlim_cur = 1024; // Set the soft limit to 1024
    setrlimit(RLIMIT_NOFILE, &limit);

    int error;
    u_char* addr = dns_resolution("www.example.com", &error);
    if (addr != NULL) {
        FILE *file = fopen("large_text_file.txt", "r"); // Assuming a large text file

        char *line = NULL;
        size_t len = 0;
        ssize_t read;

        if (file == NULL) {
            perror("fopen");
            return 1;
        }

        while ((read = getline(&line, &len, file)) != -1) {
            process_line(line);
        }

        free(addr);
        fclose(file);
    }

    return error;
}
```

This is a simplified version of what you're asking for. It doesn't handle memory exhaustion errors, it uses hardcoded file name and hostname, it does not limit the process's capabilities in a way that's portable across all POSIX compliant systems, etc. But this should give you a starting point on how to accomplish your task.
']

