```c
#include <stdarg.h>
#include <pthread.h>
#include <unistd.h>  // For usleep() if needed
#include <time.h>    // For clock_gettime() and CLOCK_MONOTONIC

// Define your log levels here. Could be enums, #defines or anything else.
#define DEBUG 0
#define INFO 1
#define WARNING 2
#define ERROR 3
#define CRITICAL 4

static int currentLogLevel = INFO;  // Default to INFO level
pthread_mutex_t mutexLock = PTHREAD_MUTEX_INITIALIZER;

void logMsg(int level, const char *format, ...) {
    if (level < currentLogLevel) return;

    pthread_mutex_lock(&mutexLock);  // Lock mutex before logging to ensure thread safety

    va_list args;
    va_start(args, format);
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    switch (level) {
        case DEBUG:
            printf("[DEBUG] %ld.%09ld ", ts.tv_sec, ts.tv_nsec);
            break;
        case INFO:
            printf("[INFO]  %ld.%09ld ", ts.tv_sec, ts.tv_nsec);
            break;
        case WARNING:
            printf("[WARNING]  %ld.%09ld ", ts.tv_sec, ts.tv_nsec);
            break;
        case ERROR:
            printf("[ERROR]  %ld.%09ld ", ts.tv_sec, ts.tv_nsec);
            break;
        case CRITICAL:
            printf("[CRITICAL]  %ld.%09ld ", ts.tv_sec, ts.tv_nsec);
            break;
    }

    vprintf(format, args);
    va_end(args);

    pthread_mutex_unlock(&mutexLock);  // Unlock mutex after logging to ensure thread safety
}
```

