    Algorithm algorithm;
    void *state;
};

void initializeCompressor(struct Compressor *compressor) {
    compressor->algorithm = DEFLATE;  // Default to DEFLATE.
}

size_t compressData(const unsigned char *src, size_t srcLen, unsigned char *dst, size_t dstLen, struct Compressor *compressor) {
    int zlibLevel = 9;  // Custom level for ZLIB or DEFLATE.
    int bzip2BlockSize = 9;  // Custom block size for BZIP2.

    if (compressor->algorithm == ZLIB) {
        compress2(compressor->state, dst, &dstLen, src, srcLen, zlibLevel);
    } else if (compressor->algorithm == DEFLATE) {
        compress2(compressor->state, dst, &dstLen, src, srcLen, Z_DEFAULT_COMPRESSION);
    } else if (compressor->algorithm == BZIP2) {
        BZ2_bzBuffToBuffCompress(dst, &dstLen, src, srcLen, bzip2BlockSize, 0, 30);
    } else if (compressor->algorithm == LZFSE) {
        lzfse_encode_buffer(src, srcLen, dst, &dstLen, NULL);
    } else {
        printf("Unsupported compression algorithm.\n");
        return 0;
    }

    return dstLen;
}

void cleanupCompressor(struct Compressor *compressor) {
    if (compressor->algorithm == ZLIB || compressor->algorithm == DEFLATE) {
        deflateEnd(compressor->state);
    } else if (compressor->algorithm == BZIP2) {
        BZ2_bzDeallocate(&compressor->state);
    } else if (compressor->algorithm == LZFSE) {
        // Not applicable.
    }
}
