     time(&now);
     fprintf(logFile,"%s: %ld", encrypt? "Encryption Started": "Decryption Started", now);

     /* Initialise the encryption operation */
     if(1 != EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)key, (unsigned char*)iv, encrypt)) {
         handleErrors();
     }

     /* Provide the message to be encrypted/decrypted */
     unsigned char inbuf[4096];  //Buffer for input data
     int inlen;  
     unsigned char outbuf[4096 + EVP_MAX_BLOCK_LENGTH]; //Buffer for output data and max block length

     while(1){
         // Read from file
         inlen = fread(inbuf, 1, sizeof inbuf, in);

         if (ferror(in)) {
             /* Error reading from input stream */
             perror("Error reading from input stream\n");
             return 0;
         } else if (inlen == 0 && feof(in)){
             // End of file reached
             break;
         }

         int outlen = 0;  
         /* Encrypt/Decrypt */
         if(!EVP_CipherUpdate(ctx, outbuf, &outlen, inbuf, inlen)) {     
               handleErrors();
         }

         // Write to output file 
         fwrite(outbuf, 1, outlen, out);
     }

     /* Finalise the encryption/decryption */
     if(!EVP_CipherFinal_ex(ctx, outbuf, &outlen)) {     
          handleErrors();
     }

     // Write to output file 
     fwrite(outbuf, 1, outlen, out);

     EVP_CIPHER_CTX_free(ctx);
     time(&now);
     fprintf(logFile,"%s: %ld", encrypt? "Encryption Ended": "Decryption Ended", now);

     return 1;   // Successful execution
}
```
This is a simplified version of the code, you might need to adjust it according to your specific requirements like dealing with large input streams, handling errors properly and optimizing performance. This function can be used in an existing application framework for encryption/decryption operations by passing file pointers and operation type (1 for encrypt, 0 for decrypt). The log details will be stored into a text file named "log.txt".
']

['To complete this task in C would be quite extensive and beyond a simple text response. However, I can provide an outline for how you might approach writing this code including using thread-safe containers such as std::map from the STL. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <assert.h>
#include <string.h>
#include <map>
#include <vector>

typedef struct {
    sem_t *sem;
    int value;
} SemInfo;

std::map<const char*, SemInfo, cmp_str> semMap; // Thread-safe map of semaphores
pthread_mutex_t semMutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety
FILE* logFile; // Log file to record operations.

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(logFile, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void safe_sem_init(sem_t *sem, int shared, unsigned int value) {
    if (sem_init(sem, shared, value) == -1) {
        fprintf(logFile, "Semaphore initialization failure\n");
        exit(EXIT_FAILURE);
    }
}

void create_or_update_sem(const char* name, int value) {
    pthread_mutex_lock(&semMutex);

    SemInfo info;
    auto iter = semMap.find(name);
    if (iter != semMap.end()) { // Semaphore already exists
        fprintf(logFile, "Updating existing semaphore %s\n", name);

        info = iter->second;
        for (int i = 0; i < value; ++i) {
            if (sem_post(info.sem) == -1) { // Overflow
                fprintf(logFile, "Semaphore overflow\n");
                exit(EXIT_FAILURE);
            }
        }
        ++info.value += value;
    } else { // Create new semaphore
        fprintf(logFile, "Creating new semaphore %s\n", name);

        info.sem = safe_malloc(sizeof(sem_t));
        safe_sem_init(info.sem, 0, value);
        info.value = value;
    }

    semMap[name] = info;
    pthread_mutex_unlock(&semMutex);
}

void delete_sem(const char* name) {
    pthread_mutex_lock(&semMutex);

    auto iter = semMap.find(name);
    if (iter == semMap.end()) {
        fprintf(logFile, "Semaphore %s does not exist\n", name);

    } else { // Semaphore exists; delete it
        fprintf(logFile, "Deleting semaphore %s\n", name);

        sem_destroy(iter->second.sem);
        free(iter->second.sem);
        semMap.erase(name);
    }

    pthread_mutex_unlock(&semMutex);
}

// More similar functions for retrieving values, decrementing and incrementing could be written. 
```

This is a simple example that uses the STL map to handle semaphores with their names as keys. A more efficient design might use an unordered_map (hash table), but this would involve allocating more memory for the hash table, which may make it slower on smaller systems or in environments where memory usage matters more than execution speed.

Please remember that C doesn't have built-in garbage collection to clean up resources when an object is no longer referenced. This must be managed manually by the programmer, as shown above with `sem_destroy` and `free`.

The logging mechanism in this example is rudimentary and only logs operations, but it can be improved significantly for a more detailed log. 

To balance efficiency and usability, consider the nature of your application: if performance is crucial, you might want to prioritize minimizing memory usage at the cost of increased lookup time. If simplicity is more important, then an inefficient design that makes operations quicker could be a better trade-off. Similarly, logging verbosity versus performance impact will also depend on how detailed or frequent your logs need to be.
']

