void updateIntegerCollection(std::unordered_map<std::string, std::vector<int>>& map, const std::string& key) {
    // Lock the mutex before accessing the unordered map
    std::lock_guard<std::mutex> lock(mtx);

    try {
        // Insert a new integer at the beginning of the vector associated with the given key
        map[key].insert(map[key].begin(), 10);
    } catch (const std::exception& e) {
        // Catch any exception that may occur during insertion, such as out-of-memory
        std::cerr << "Exception caught: " << e.what() << '\n';
    }
}
