import cachetools

# Set up Flask and rate limiting middleware
app = Flask(__name__)
limiter = Limiter(app, default_limits=["100 per day", "50/hour"])
logging.basicConfig(filename='webAPI.log', level=logging.INFO)
cache = cachetools.LRUCache(maxsize=100)

# Define a retry decorator with exponential backoff
def retry_on_failure(retries=5, delay=1, backoff=2):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for i in range(retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    time.sleep(delay)
                    delay *= backoff
                    logging.warning(f"Attempt {i+1} failed with error {e}. Retrying...")
            # If all attempts fail, log the failure and raise an exception
            logging.error("All retries failed.")
            raise e
        return wrapper
    return decorator

