['Here's how you might implement this in Rust using a few crates such as `xml` for parsing XML documents, `std::fs` and `std::env` for managing file system and environment variables respectively. 

```rust
use std::{collections::HashMap, fs, io, path::PathBuf};
use xml::reader::XmlEvent;
use xml::attribute::Attribute as XmlAttr;
use xml::writer::EmitterConfig;

/// A struct to hold the parsed XML document.
pub struct ParsedDocument {
    root_name: String,
    attrs: HashMap<String, Vec<XmlAttr>>,
}

impl ParsedDocument {
    /// Parse an XML file into a `ParsedDocument`.
    fn parse(path: &str) -> Result<Self, io::Error> {
        let mut reader = xml::reader::EventReader::open(PathBuf::from(path))?;

        // TODO: Add error handling
        let root_name = loop {
            match reader.next() {
                Ok(XmlEvent::StartElement { name, attributes, .. }) => break (name, attributes),
                _ => continue,
            }
        };

        Ok(Self {
            root_name: root_name.0.to_string(),
            attrs: HashMap::from_iter(root_name.1.into_iter().map(|a| (a.name.to_string(), a))),
        })
    }
}

pub fn process_xml(path: &str, dir_name: &str) -> Result<Vec<ParsedDocument>, io::Error> {
    let _ = fs::create_dir_all(&dir_name);
    std::env::set_var("XML_DIR", dir_name);
    process_xml_inner(path)
}

fn process_xml_inner(path: &str) -> Result<Vec<ParsedDocument>, io::Error> {
    let mut documents = Vec::new();
    for entry in fs::read_dir(path)? {
        // TODO: Add error handling
        let entry = entry?;
        if entry.file_type()?.is_file() {
            match ParsedDocument::parse(&entry.path()) {
                Ok(doc) => documents.push(doc),
                Err(_) => continue,
            }
        }
    }
    Ok(documents)
}
```
