class StreamManager {
    constructor() {
        this.buffer = [];
        this.isPaused = false;
    }

    async fetchData() {
        try {
            //Replace with your third-party API endpoint
            const response = await fetch('https://api.example.com/data');
            const data = await response.json();

            this.buffer.push(...data);

