                await this.pauseStream();
            } else {
                this.resumeStream();
            }
        } catch (error) {
            console.log(`Error fetching data: ${error}`);
        }
    }

    pauseStream() {
        if (!this.isPaused) {
            this.isPaused = true;
            this.sendNotification('paused'); //Replace with your message broker details
            return sleep(Math.random() * 1000); //Simulate variable network conditions
        }
    }

    resumeStream() {
        if (this.isPaused) {
            this.isPaused = false;
            this.sendNotification('resumed'); //Replace with your message broker details
        }
    }

    sendNotification(status) {
        amqp.connect('amqp://localhost')
            .then((conn) => conn.createChannel())
            .then((ch) => ch.assertQueue('stream_notifications')
                .then(() => ch.sendToQueue('stream_notifications', 
                    Buffer.from(`Stream has been ${status}`))))
            .catch((err) => console.warn(err));
    }

    async start() {
        while (true) { //Replace with your condition for ending the program
            await this.fetchData();
        }
    }
}

const manager = new StreamManager();
manager.start();
``` 

