['The given task requires a lot of details and implementations that could be quite complex, so here is a simplified Java code snippet using Java 8 parallel streams to process CSV file efficiently. This does not cover all the details mentioned but it should give you an idea about how one can approach this problem.

```java
import java.io.BufferedReader;
import java.io.FileReader;
import java.util.*;
import java.util.stream.Collectors;

class Transaction {
    String id;
    String userId;
    String date;
    double amount;
}

public class Main {
    public static void main(String[] args) {
        List<Transaction> transactions = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader("transactions.csv"))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] values = line.split(",");
                Transaction transaction = new Transaction();
                // Assume that all data is correct and no missing/inconsistent data here for simplicity
                transaction.id = values[0];
                transaction.userId = values[1];
                transaction.date = values[2];
                transaction.amount = Double.parseDouble(values[3]);
                transactions.add(transaction);
            }
        } catch (Exception e) {
            System.out.println("Error: " + e.getMessage());
        }

        long startTime = System.currentTimeMillis();

        Map<String, List<Transaction>> userTransactions = transactions.parallelStream().collect(Collectors.groupingByConcurrent(t -> t.userId));

        for (Map.Entry<String, List<Transaction>> entry : userTransactions.entrySet()) {
            String userId = entry.getKey();
            List<Transaction> transactionsForUser = entry.getValue();

            double averageAmount = transactionsForUser.stream().collect(Collectors.averagingDouble(t -> t.amount));
            // Outlier logic goes here...

            System.out.println("Average transaction amount for user " + userId + ": " + averageAmount);
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Processing time: " + (endTime - startTime) + "ms");
    }
