    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 10); // timeout after 10 seconds

    $attempts = 0;
    $maxAttempts = 3; // maximum number of attempts for a request before it fails
    do {
        $response = curl_exec($ch);
        if (curl_errno($ch)) {
            error_log('Request Error: ' . curl_error($ch));
            $attempts++;
            sleep(1); // wait for 1 second before retrying
        } else {
            break;
        }
    } while ($attempts < $maxAttempts);

    if (curl_errno($ch)) {
        error_log('Request Error after ' . $maxAttempts . ' attempts: ' . curl_error($ch));
        $response = false; // Return a failure message if all attempts fail
    } else {
        $data = json_decode($response, true);

        // Here you would implement the caching logic
        cacheWeatherData($location, $data);

        return 'Success';
    }

    curl_close($ch);
}
