**JavaScript Code**
```javascript
const fs = require('fs');
const path = require('path');

function readConfig(callback) {
  const configFilePath = path.resolve(__dirname, 'path/to/your/config.json');

  fs.readFile(configFilePath, 'utf8', (err, data) => {
    if (err) {
      console.error('Error reading configuration file: ', err);
      return callback(new Error("Unable to open or read configuration file."));
    }

    let parsedConfig;

    try {
      parsedConfig = JSON.parse(data);
    } catch (e) {
      console.error('Error parsing configuration file: ', e);
      return callback(new Error("Configuration file is not valid JSON."));
    }

    callback(null, parsedConfig);
  });
}
```

