const { pipeline } = require('stream');
const got = require('got');
const { promisify } = require('util');

// Promisify the stream pipeline function for better error handling
const streamPipeline = promisify(pipeline);

async function generatePEMCertificateFromStream(oauthRequest) {
  const { privateKeyUrl, certificateUrl, retries, pauseAndResume } = oauthRequest;

  let privateKeyData = '';
  let certificateData = '';

  // Fetch private key data
  for (let i = 0; i < retries; i++) {
    try {
      privateKeyData = await got(privateKeyUrl, { retry: 0 }).text();
      break;
    } catch (error) {
      if (i === retries - 1) throw error; // Rethrow the error after the last attempt
      await new Promise((resolve) => setTimeout(resolve, i * 1000)); // Wait before next retry
    }
  }

  // Fetch certificate data
  for (let i = 0; i < retries; i++) {
    try {
      certificateData = await got(certificateUrl, { retry: 0 }).text();
      break;
    } catch (error) {
      if (i === retries - 1) throw error; // Rethrow the error after the last attempt
      await new Promise((resolve) => setTimeout(resolve, i * 1000)); // Wait before next retry
    }
  }

  // Combine into a PEM formatted string
  const pemCertificate = `${privateKeyData}\n${certificateData}`;

  if (pauseAndResume) {
    // Implement pause and resume logic here, depending on your specific requirements
  }

  return pemCertificate;
}
