<?php
function updateUserPassword($userId, $oldPassword, $newPassword, $resetToken) {
  // Authenticate user with external service
  $externalAuth = new ExternalAuthenticationService();
  if (!$externalAuth->authenticateUser($userId, $oldPassword)) {
    throw new Exception('Invalid old password');
  }

  // Apply rate limiting
  $rateLimiter = new RateLimitService();
  if ($rateLimiter->isRateLimited($userId)) {
    throw new Exception('Too many requests, please try again later.');
  }

  // Start transaction
  Db::startTransaction();

  try {
    // Lock user record for update (to prevent race conditions)
    $locked = Db::lockUserForUpdate($userId);
    if (!$locked) {
      throw new Exception('Failed to acquire lock');
    }

    // Update password in all databases and external services
    foreach (ExternalDatabaseService::getAllDatabases() as $db) {
      $db->updateUserPassword($userId, $newPassword);
    }

    // Log password update attempt
    $logging = new LoggingService();
    $logging->logUpdateAttempt($userId, true);

  } catch (Exception $e) {
    Db::rollbackTransaction();
    $logging->logUpdateAttempt($userId, false);
    throw $e;

  } finally {
    // Release lock and commit transaction
    Db::unlockUserAndCommitTransaction();
  }

  // Notify user of password update status (callback)
  $notify = new NotificationService();
  $notify->sendPasswordUpdateStatus($userId, true);
}
?>
