    FSAState *newList = malloc(sizeof(FSAState) * maxSize);  // Allocate memory for new state list
    if (!newList) return NULL;  // Check if allocation succeeded

    int i = 0, j = 0;
    while (i < numStates && j < maxSize) {
        if (fsa[j].state == lastState || is_in_array(states, numStates, fsa[j].state)) {
            newList[i++] = fsa[j];  // Copy states to the new list
        }
        ++j;  // Move to the next state in FSA
    }

    if (i < maxSize && j < numStates) {
        free(newList);  // If we reached a limit, release memory and return NULL
        return NULL;
    }

    return newList;  // Return the newly created state list
}
```

