["To solve this problem in C requires understanding a number of complexities, such as asynchronous networking, concurrent processing, and efficient data storage/retrieval from an external data store. Below, I've outlined a basic structure for the function, which includes key elements requested including sliding window, anomaly detection with varying thresholds, integration with external database, logging mechanism, and thread safety.

```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>
#define WINDOW_SIZE 500

typedef struct {
    double values[WINDOW_SIZE];
    time_t timestamps[WINDOW_SIZE];
    int head;
} SlidingWindow;

pthread_mutex_t windowMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t dbMutex = PTHREAD_MUTEX_INITIALIZER;
int anomalyCount = 0;
double totalAnomalyMagnitude = 0.0;
time_t lastLogTime = 0;

void updateWindow(SlidingWindow* window, double value) {
    pthread_mutex_lock(&windowMutex);
    window->values[window->head] = value;
    time(&window->timestamps[window->head]);
    window->head = (window->head + 1) % WINDOW_SIZE;
    pthread_mutex_unlock(&windowMutex);
}

double getAverage(SlidingWindow* window, time_t now) {
    double sum = 0.0;
    int count = 0;
    for (int i = 0; i < WINDOW_SIZE; ++i) {
        if (difftime(now, window->timestamps[i]) < 60 * 60) { // consider data within last hour only
            sum += window->values[i];
            ++count;
        }
    }
    return count == 0 ? 0.0 : sum / count;
}

void detectAnomaly(double value, time_t timestamp, double average) {
    if (value > average * 1.5) { // if value is more than 50% above average, consider as anomaly
        pthread_mutex_lock(&dbMutex);
        ++anomalyCount;
        totalAnomalyMagnitude += value;
        if (difftime(timestamp, lastLogTime) > 60 * 10 || anomalyCount % 10 == 0) { // log every 10 anomalies or once per minute
            logToExternalDb(value, timestamp);
            lastLogTime = timestamp;
        }
        pthread_mutex_unlock(&dbMutex);
    }
}

void processSensorData(double value) {
    static SlidingWindow window = { .head = 0 };

    time_t now;
    time(&now);

    updateWindow(&window, value);

    double average = getAverage(&window, now);

    detectAnomaly(value, now, average);
}
```
Please note that this is a high-level skeleton and requires a lot of adjustments to fit into your specific environment like error handling, connection to the external data store, data sanitization etc. In real world usage, you might want to look at languages/libraries more suited for these tasks like Python with its asyncio library for networking, numpy for numerical operations and SQL libraries for database integration.
