['```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading;
using System.Globalization;

public class DynamicValueGenerator
{
    private readonly object _lock = new object();
    private SortedList<float, Tuple<float, float>> ranges = new SortedList<float, Tuple<float, float>>();

    public void AddRange(float minVal, float maxVal)
    {
        lock (_lock)
        {
            if (minVal >= maxVal || OverlapsExistingRanges(minVal, maxVal)) throw new ArgumentException("Invalid Range");

            ranges.Add(minVal, Tuple.Create(minVal, maxVal));
        }
    }

    public void RemoveRange(float minVal)
    {
        lock (_lock)
        {
            if (!ranges.ContainsKey(minVal)) throw new ArgumentException("No such Range");

            ranges.Remove(minVal);
        }
    }

    public float GetRandomFloat()
    {
        Tuple<float, float> range;

        lock (_lock)
        {
            if (ranges.Count == 0) throw new InvalidOperationException("No ranges");

            var rnd = new Random();
            int index = rnd.Next(ranges.Count);
            range = ranges.Values[index];
        }

        return ((float)rnd.NextDouble() * (range.Item2 - range.Item1)) + range.Item1;
    }

    public int GetRandomInt()
    {
        Tuple<float, float> range;

        lock (_lock)
        {
            if (ranges.Count == 0) throw new InvalidOperationException("No ranges");

            var rnd = new Random();
            int index = rnd.Next(ranges.Count);
            range = ranges.Values[index];
        }

        return (int)(((float)rnd.NextDouble() * (range.Item2 - range.Item1)) + range.Item1);
    }

    public override string ToString()
    {
        var sb = new StringBuilder();
        lock (_lock)
        {
            foreach(var kv in ranges)
            {
                sb.AppendLine($"{kv.Value.Item1} - {kv.Value.Item2}");
            }
        }

        return sb.ToString();
    }

    private bool OverlapsExistingRanges(float minVal, float maxVal)
    {
        if (ranges.Count > 0 && ranges.Any(x => x.Value.Item1 < maxVal && x.Value.Item2 > minVal)) return true;

        return false;
    } 
}
```
