#define MAX_FILENAME_LEN 255

char *generateFilename(const char *filename, const char *extension) {
    size_t len = strlen(filename);
    if (len > MAX_FILENAME_LEN) return NULL;

    int baseNameLen = 0;
    for (; filename[baseNameLen] != '\0' && filename[baseNameLen] != '.'; ++baseNameLen);

    char *newFilename = (char*)malloc(MAX_FILENAME_LEN + 1);
    if (!newFilename) return NULL; // check malloc success

    int i = 0;
    for (; i < baseNameLen && i < MAX_FILENAME_LEN; ++i) {
        newFilename[i] = filename[i];
    }

    if (i + strlen(extension) > MAX_FILENAME_LEN) return NULL; // check length

    for (int j = 0; j < strlen(extension); ++j, ++i) {
        newFilename[i] = extension[j];
    }

    if (i + len > MAX_FILENAME_LEN) return NULL; // check length

    for (; i < MAX_FILENAME_LEN; ++i) {
        newFilename[i] = '0' + baseNameLen % 10;
        baseNameLen /= 10;
    }

    newFilename[MAX_FILENAME_LEN] = '\0'; // add null terminator

    return newFilename;
}
```

