typedef struct command_info {
    char* cmd;
    int status; // 0: not started, 1: running, 2: completed, -1: failed
} CommandInfo;

// Global variables and mutex for thread-safe access
CommandInfo commands[100];
int total_commands = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pid_t pids[10];
volatile sig_atomic_t terminate = 0;

// Function to execute commands asynchronously, with system load management
void* executeCommands(void* arg) {
    int i;
    pid_t pid;
    struct rusage usage;
    while (total_commands > 0 && !terminate) {
        for (i = 0; i < 10; ++i) {
            if ((getloadavg(&usage, 1)[0] * 100 / sysconf(_SC_NPROCESSORS_ONLN)) > 70) {
                // Reduce concurrency level by one process per minute
                sleep(60);
            } else {
                // Execute command asynchronously with standard input, output and error redirected to /dev/null
                if ((pid = fork()) == 0) { 
                    freopen("/dev/null", "w", stderr); // redirect std err
                    freopen("/dev/null", "r", stdin);  // redirect std in
                    freopen("/dev/null", "a", stdout); // redirect std out
                    system(commands[i].cmd);
                    exit(0);
                } else if (pid < 0) {
                    perror("fork");
                    commands[i].status = -1;
                } else {
                    pids[i] = pid;
                    commands[i].status = 2; // Mark as running or completed
                } 
            }
        }
    }
}

// Signal handler to terminate all child processes and their respective resources
void handle_signal(int signo) {
    int status, i;
    if (signo == SIGINT || signo == SIGTERM || signo == SIGHUP) {
        terminate = 1; // Set flag to 1 to signal termination
        for (i = 0; i < 10; ++i) {
            kill(pids[i], signo); // Send signal to child processes
            waitpid(pids[i], &status, WNOHANG); // Wait for the process to terminate
        }
    }
}

// Function to manage command execution status and total executed commands
void logStatus() {
    int success = 0;
    pthread_mutex_lock(&lock); // Lock mutex to access shared variables

    for (int i = 0; i < total_commands; ++i) {
        if(commands[i].status == 2) {
            printf("Command %s executed successfully\n", commands[i].cmd);
            ++success;
        } else if(commands[i].status == -1) {
            printf("Failed to execute command: %s\n", commands[i].cmd);
        }
    }

    printf("Total executed commands: %d, successful: %d\n", total_commands, success);
    pthread_mutex_unlock(&lock); // Unlock mutex after accessing shared variables
}

// Function to pause and resume command execution
void manageExecution() {
    // Code to pause or resume the execution of child processes would go here.
    // This could be implemented by signal handling (e.g., SIGSTOP/SIGCONT) or some other mechanism.
}
``` 
