char * decryptPassword(char* encoded, char* key, char* IV) {
    AES_KEY aesKey;
    unsigned char *decrypted = malloc(strlen(encoded)/2); 

    if (AES_set_decrypt_key((unsigned char*)key, 128, &aesKey) < 0) {
        return NULL; // Error decoding key
    }

    for(int i = 0; i < strlen(encoded); i+= AES_BLOCK_SIZE){
        AES_cbc_encrypt((unsigned char*) encoded + i, decrypted + i, 16, &aesKey, (unsigned char*)IV, AES_DECRYPT);
    }

    return (char *)decrypted;
}

int processPassword(PasswordStruct *passStruct) {
    // Validate the encoded password format
    if (!passStruct->password || strlen(passStruct->password) == 0 || !isBase64EncodedString(passStruct->password)) {
        logError(ERROR_INVALID_PASSWORD, passStruct->logger); 
        return ERROR_INVALID_PASSWORD;
    }

    // Check DB connection
