['```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

public class ConfigurationEntryManager : IConfigurationEntryManager
{
    private readonly ConcurrentDictionary<string, string> entries = new ConcurrentDictionary<string, string>();

    public void AddEntry(string entry)
    {
        if (entry == null || entry.Length == 0) throw new ArgumentNullException("entry");
        var hash = ComputeHash(entry);
        entries[entry] = hash;
    }

    public string GetHashByEntry(string entry)
    {
        return entries.TryGetValue(entry, out var hash) ? hash : null;
    }

    public bool ExistsInCollection(string entry)
    {
        return entries.ContainsKey(entry);
    }

    private string ComputeHash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] bytes = Encoding.UTF8.GetBytes(input);
            return Convert.ToBase64String(sha256.ComputeHash(bytes));
        }
    }
}

public interface IConfigurationEntryManager
{
    void AddEntry(string entry);
    string GetHashByEntry(string entry);
    bool ExistsInCollection(string entry);
}
```

For the external logging service, it depends on your specific use case but you can consider using a framework like Serilog or NLog and injecting ILogger into your ConfigurationEntryManager class. To handle invalid data, add exception handling in the AddEntry method for cases where the entry is null or empty. To account for potential discrepancies from external sources or transient network issues, you should add error handling code to wrap potentially throwing operations like reading/writing to a database or sending/receiving over the network and handle these exceptions gracefully.

