void* manageMemoryAndInit(long* offsets, size_t numOffsets, int* keys, size_t numKeys, record** records, size_t numRecords) {
    // Memory allocation and initialization for offsets, keys, records arrays.
    long* offsetArray = malloc(numOffsets * sizeof(*offsetArray));
    if (!offsetArray) return NULL;

    int* keyArray = malloc(numKeys * sizeof(*keyArray));
    if (!keyArray) {
        free(offsetArray);
        return NULL;
    }

    record** recordArray = malloc(numRecords * sizeof(*recordArray));
    if (!recordArray) {
        free(offsetArray);
        free(keyArray);
        return NULL;
    }

    // Copy data to the new arrays.
    for (size_t i = 0; i < numOffsets; ++i) offsetArray[i] = offsets[i];
    for (size_t i = 0; i < numKeys; ++i) keyArray[i] = keys[i];

    // Thread-safe operation.
    pthread_mutex_lock(&mutex);
    *records = recordArray;
    pthread_mutex_unlock(&mutex);

