void log_request(const std::string& status) {
    auto now = std::chrono::system_clock::now();
    auto in_time_t = std::chrono::system_clock::to_time_t(now);
    auto timestamp = std::put_time(std::localtime(&in_time_t), "%Y-%m-%d %X");

