    }

    client
}];

pub struct CachedResponse {
    pub url: Url,
    pub response: Value,
}

static mut RESPONSE_CACHE: HashMap<Url, CachedResponse> = HashMap::new();

fn fetch_and_parse(url: &str) -> Result<Value, Error> {
    let url = Url::parse(url).unwrap();

    unsafe {
        if RESPONSE_CACHE.contains_key(&url) {
            return Ok(RESPONSE_CACHE[&url].response.clone());
        }
    }

    let response = HTTP_CLIENT.get(url).send().unwrap();

    let json: Value = serde_json::from_str(&response.text().unwrap()).unwrap();

    unsafe {
        RESPONSE_CACHE.insert(url, CachedResponse{ url: url, response: json });
    }

    Ok(json)
}
```
