['Here is a high level overview of how you could approach this problem in C:

```c
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>

#define MAX_TASKS 10
#define RETRY_LIMIT 3

typedef struct Task {
    pid_t pid;
    char* cmd;
    int retries;
    int priority;
} Task;

int task_comparator(const void *a, const void *b) {
    return ((Task*)b)->priority - ((Task*)a)->priority;  // Higher priority first
}

void handle_sigint(int signum) {
    while (waitpid(-1, NULL, WNOHANG) > 0);  // Wait for all child processes to terminate
    exit(signum);
}

int execute_tasks(Task* tasks, int taskCount) {
    qsort(tasks, taskCount, sizeof(Task), task_comparator);  // Prioritize higher priority tasks first

    signal(SIGINT, handle_sigint);  // Set up SIGINT handler

    for (int i = 0; i < taskCount && i < MAX_TASKS; ++i) {
        pid_t child = fork();
        if (child < 0) {
            fprintf(stderr, "Fork failed: %s\n", strerror(errno));
            return 0;
        } else if (child == 0) {  // Child process
            freopen("/dev/null", "r", stdin);  // Redirect input to /dev/null
            freopen("/dev/null", "w", stdout);  // Redirect output and error to /dev/null

            execl("/bin/sh", "sh", "-c", tasks[i].cmd, (char *) NULL);  // Execute task command
            fprintf(stderr, "Exec failed: %s\n", strerror(errno));
            exit(-1);
        } else {
            tasks[i].pid = child;
            printf("Launched task with pid %d and priority %d\n", child, tasks[i].priority);
        }
    }

    int status;
    while (wait(&status) > 0) {  // Wait for all child processes to finish
        if (!WIFEXITED(status)) continue;  // If the process didn't exit normally, skip it

        pid_t pid = WEXITSTATUS(status);
        Task* task = NULL;
        for (int i = 0; i < taskCount; ++i) {  // Find corresponding task
            if (tasks[i].pid == pid) {
                task = &tasks[i];
                break;
            }
        }

        if (!task) continue;  // Task not found, skip it

        if (WEXITSTATUS(status)) {
            printf("Task with pid %d failed\n", pid);

            if (++task->retries > RETRY_LIMIT) {
                printf("Retry limit reached for task with pid %d, giving up\n", pid);
                continue;
            }

            // Retry task
            tasks[i].pid = fork();
            if (tasks[i].pid < 0) {
                fprintf(stderr, "Fork failed: %s\n", strerror(errno));
                return 0;
            } else if (tasks[i].pid == 0) {  // Child process
                freopen("/dev/null", "r", stdin);  // Redirect input to /dev/null
                freopen("/dev/null", "w", stdout);  // Redirect output and error to /dev/null

                execl("/bin/sh", "sh", "-c", tasks[i].cmd, (char *) NULL);  // Execute task command
                fprintf(stderr, "Exec failed: %s\n", strerror(errno));
                exit(-1);
            } else {
                printf("Retried task with pid %d and priority %d\n", tasks[i].pid, tasks[i].priority);
            }
        } else {
            printf("Task with pid %d completed successfully\n", pid);
        }
    }

    return 1;
}
```
