    }
}

void runBackgroundProcess(char* cmd, Callback callback) {
    int pid = fork();
    if (pid == 0) {
        // Child process: execute command.
        system(cmd);
        exit(EXIT_SUCCESS);
    } else if (pid < 0) {
        // Fork failed. Handle Error.
    } else {
        Process* p = malloc(sizeof(Process));
        if(!p) goto error;
        p->pid = pid;
        p->cmd = cmd;
        process = p;
        callback((void*)process);
    }
error:
