['Here is an example of how you can implement this task in C using the concept of dynamic memory allocation, union data type and struct record:

```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <limits.h>

typedef struct {
    long value;  // For integer values
    char *str;   // For string values
} union_data;

typedef struct {
    union_data data;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
} return_values;

return_values generate(size_t num_offsets, size_t num_records) {

    // Allocate memory dynamically for the arrays.
    long *offsets = malloc(num_offsets * sizeof(*offsets)); 
    int *keys = calloc(num_offsets, sizeof(*keys));  
    record *records = malloc(num_records * sizeof(*records));

    // Check if allocation was successful
    if (!offsets || !keys || !records) { 
        fprintf(stderr, "Memory allocation failed.\n");
        exit(-1);
    }

    // Initialize offsets and keys arrays with sequential integers.
    for (size_t i = 0; i < num_offsets; ++i) {

        if(num_offsets <= INT_MAX){ 
            offsets[i] = i;
            keys[i] = i;
        }else{
            fprintf(stderr, "Overflow detected. Handle this error gracefully.\n");
            exit(-1);
        }        
    }

    // Randomly assign either an integer value or a string value to the records array.
    const int STR_MAX = 50;  // Maximum length of generated strings
    size_t total_str_len = 0;
    srand(time(NULL));  
    for (size_t i = 0; i < num_records; ++i) {
        if ((double) rand() / RAND_MAX < 0.5) {  // Assign integer value with equal probability.
            records[i].data.value = rand();  

        } else {  
            int str_len = 1 + rand() % STR_MAX;
            char *str = malloc(str_len + 1); 

            // Check if allocation was successful and total string length is not exceeding 1 MB.
            if (!str || (total_str_len += str_len) > 1024*1024) {  
                fprintf(stderr, "Memory allocation failed or maximum limit for strings reached.\n");
                exit(-1);
            }

            // Generate a random string of length 'str_len'.
            for (int j = 0; j < str_len; ++j) {
                str[j] = 'a' + rand() % 26;  
            }
            str[str_len] = '\0';  // Null-terminate the string.

            records[i].data.str = str;
        }
    }

    return (return_values){ .offsets = offsets, .keys = keys, .records = records };
}
```
This implementation dynamically allocates memory for arrays `offsets` and `keys` using `malloc` and `calloc` respectively. For the array of `struct record`, it randomly assigns either an integer value or a string value with equal probability. It also implements mechanisms to handle memory allocation errors and large `num_offsets` values gracefully.
']

