void initializeRecords(int n) {
    for (int i = 0; i < n; ++i) {
        Record* r = malloc(sizeof(Record));
        if (!r) {
            // Handle error here, e.g., return or exit program
        }

        time(&(r->timestamp)); // Get current time
        pthread_mutex_init(&(r->lock), NULL); 

        records[i] = r;
    }
}

void updateRecord(int index, int key, unsigned char statusFlag) {
    Record* r = records[index];

    // Use mutex lock to ensure thread safety
    pthread_mutex_lock(&(r->lock)); 

    r->key = key;
    r->statusFlag = statusFlag;
    time(&(r->metadata.lastModified)); 

    pthread_mutex_unlock(&(r->lock)); 
}
```
This code shows a basic implementation of a multi-threaded environment to manage a collection of records in C. It creates an array with space for up to one million `Record` objects, each containing an offset, key, timestamp, status flag, and metadata structure, with the latter containing a last modification timestamp. 

