        exit(EXIT_FAILURE);
    }

    // Parse the log entry here...

    return entry;
}

void process_logs() {
    signal(SIGINT, handler);

    while (!stop) {
        LogEntry* new_entry = read_log_entry();
        ++entry_count;

        // Resize the array
        log_entries = realloc(log_entries, entry_count * sizeof(LogEntry));
        if (log_entries == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        // Add the new entry to our array of log entries
        log_entries[entry_count - 1] = *new_entry;
    }
}
```
