#include <memory>
#include <atomic>

class DataAggregator {
private:
    std::map<std::string, std::shared_ptr<std::vector<int>>> data;
    mutable std::shared_timed_mutex mtx;

public:
    // Add a new dataset with an unique identifier.
    void addDataset(const std::string& id) {
        std::unique_lock<std::shared_timed_mutex> lock(mtx);
        data[id] = std::make_shared<std::vector<int>>();
    }

    // Append a new integer value to an existing dataset.
    void appendValueToDataset(const std::string& id, int val) {
        std::unique_lock<std::shared_timed_mutex> lock(mtx);
        if (data.count(id)) {
            data[id]->push_back(val);
        } else {
            throw std::runtime_error("Dataset not found.");
        }
    }

    // Retrieve a dataset based on its identifier.
    std::vector<int> getDataset(const std::string& id) const {
        std::shared_lock<std::shared_timed_mutex> lock(mtx);
        if (data.count(id)) {
            return *data[id];
        } else {
            throw std::runtime_error("Dataset not found.");
        }
    }
};
```
