```java
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.apache.commons.codec.binary.Base64;
import org.apache.commons.codec.digest.DigestUtils;

public enum OutputFormat {
    HEX, BASE64, BYTEARRAY;
}

public class StringConcatenator {
    private static final int MAX_LENGTH = 1024 * 1024; // Default max length
    private static final Object lock = new Object();

    public void setMaxLength(int max) {
        synchronized (lock) {
            if (max > 0 && max < MAX_LENGTH) {
                MAX_LENGTH = max;
            } else {
                throw new IllegalArgumentException("Invalid max length: " + max);
            }
        }
    }

    public String concatAndHash(OutputFormat format, String... strings) throws Exception {
        synchronized (lock) {
            int totalLength = 0;
            for (String s : strings) {
                if (s == null || "".equals(s)) {
                    throw new IllegalArgumentException("Input string can't be empty or null");
                }

                totalLength += s.getBytes().length;
                if (totalLength > MAX_LENGTH) {
                    throw new Exception("Total length exceeds max allowed: " + MAX_LENGTH);
                }
            }

            StringBuilder sb = new StringBuilder();
            for (String s : strings) {
                sb.append(s);
            }

            return formatOutput(format, DigestUtils.md5Hex(sb.toString().getBytes()));
        }
    }

    private String formatOutput(OutputFormat format, byte[] hashBytes) {
        switch (format) {
            case HEX: 
                return new String(hashBytes);

            case BASE64:
                return Base64.encodeBase64String(hashBytes);

            case BYTEARRAY: 
                return Arrays.toString(hashBytes);
        }

        throw new IllegalArgumentException("Invalid output format");
    }
}
```

