                                          List<String> contents, ExternalLoggingServiceAPI api) {
        if (ids.size() > MAX_LOG_ENTRIES || timestamps.size() != ids.size() || 
            contents.size() != ids.size()) {
            throw new IllegalArgumentException("Invalid log entry size");
        }

        Map<String, Object> response = new HashMap<>();
        int successCount = 0;

        for (int i = 0; i < ids.size(); i++) {
            String id = ids.get(i);
            Instant timestamp = timestamps.get(i);
            String content = contents.get(i);

            if (!isValidId(id) || !isValidTimestamp(timestamp) || 
                !isValidContent(content)) {
                LOG.warn("Invalid log entry at position " + i);
                continue;
            }

            int retryCount = 0;
            while (retryCount < 3) {
                try {
                    if (api.logEntry(id, timestamp, content)) {
                        successCount++;
                    } else {
                        LOG.error("Failed to log entry " + id);
                    }
                    break;
                } catch (Exception e) {
                    retryCount++;
                    LOG.warn("Transient failure when logging entry " + id, e);
                }
            }

            if (retryCount == 3) {
                LOG.error("Failed to log entry " + id + " after 3 retries");
            }
        }

        response.put("success", successCount == ids.size());
        response.put("timestamp", Instant.now());
        return response;
    }

