// Generate a random string with the given character set and length
function generateRandomString(length, charset) {
    let result = '';
    const charactersLength = charset.length;
    for (let i = 0; i < length; i++) {
        result += charset.charAt(Math.floor(Math.random() * charactersLength));
    }
    return result;
}

// Process a single file asynchronously
async function processSingleFileAsync(filePath, transformFunction) {
    try {
        const data = await readFileAsync(filePath);
        return transformFunction(data.toString());
    } catch (err) {
        console.error('Error processing file:', err);
    }
}

// Process multiple files asynchronously
async function processDirectoryContents(directoryPath, apiURL, transformFunction) {
    try {
        const directoryContent = await fs.promises.readdir(directoryPath);

        let resultString = '';

        for (const fileName of directoryContent) {
            // Get metadata about the file from an external API
            const response = await axios.get(`${apiURL}/${fileName}`);

            if (!response || !response.data) {
                console.error('Error retrieving metadata for:', fileName);
                continue; // Skip to the next iteration
            }

            const filePath = path.join(directoryPath, fileName);
            const processedContent = await processSingleFileAsync(filePath, transformFunction);

            if (!processedContent) {
                console.error('Error processing content for:', fileName);
                continue; // Skip to the next iteration
            }

            resultString += `${processedContent} ${generateRandomString(10, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')}`;
        }

        return resultString;
    } catch (err) {
        console.error('Error processing directory contents:', err);
    }
}
