['Below is an example PHP script that should meet your requirements. However, please note that creating a full-featured solution like this would be quite extensive for Stack Overflow's format constraints. This script assumes you have `DotEnv` library to parse .env file, and `Monolog` for logging:

```php
<?php
require 'vendor/autoload.php';
use Dotenv\Dotenv;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

class Config {
    protected $logger;
    protected $settings = [];

    public function __construct($path, Logger $logger) {
        $this->logger = $logger;
        $dotenv = Dotenv::createImmutable($path);
        $this->parseEnvFile();
    }

    protected function parseEnvFile() {
        try {
            $dotenv->load();
            $this->settings = $_ENV; // assuming .env contains all the config settings.
            foreach ($this->settings as $key => $value) {
                $override = getopt('', [$key.':']);
                if (!empty($override)) {
                    $this->logger->info("Overriding setting: $key");
                    $this->settings[$key] = $override[$key];
                }
            }
        } catch (Exception $e) {
            $this->logger->error('Error parsing .env file', ['exception' => $e]);
        }
    }

    public function get($setting) {
        return isset($this->settings[$setting]) ? $this->settings[$setting] : null;
    }
}
```
You should use the Config class like this:
