let rateLimitExceededCount = 0;

class Reducer {
  constructor(maxConcurrent = 5) {
    this.MAX_CONCURRENT = maxConcurrent;
    this.apiRequestsInProgress = 0;
    this.rateLimitExceededCount = 0;
    // Simulate a rate limit of 1 request per second
    this.requestDelayMs = 1000 / 1; 
    // API response cache for idempotency
    this.apiResponseCache = {}; 
  }

  async reduce(array, initialValue, callback) {
    let result = initialValue;
    for (let i = 0; i < array.length; i++) {
      const number = array[i];

      // Check if the number is already in cache to avoid calling API multiple times
      if (!this.apiResponseCache[number]) {
        await this._callApi(number); 
      }
      let metadata = this.apiResponseCache[number].metadata;

      try {
        result = await callback(result, number, metadata);
      } catch (err) {
        console.log('Error in callback:', err);
        throw new Error('Reduction failed due to error in callback');
      }
    }

    return Promise.resolve(result);
  }

  async _callApi(number) {
    // Check if we have reached the max concurrent requests limit
    while (this.apiRequestsInProgress >= this.MAX_CONCURRENT) {
      await new Promise((resolve) => setTimeout(resolve, 100));
    }

    let delayMs = this.rateLimitExceededCount > 0 ? this.requestDelayMs * Math.pow(2, this.rateLimitExceededCount) : 0;

    await new Promise((resolve) => setTimeout(resolve, delayMs));

    try {
      // Simulate API call with random metadata
      let response = {metadata: Math.random()};
      this.apiResponseCache[number] = response;
      this.rateLimitExceededCount = 0; 
    } catch (err) {
      if(this.rateLimitExceededCount < 5){
        console.log('Rate limit exceeded, retrying in', delayMs, 'ms');
        ++this.rateLimitExceededCount;
        return this._callApi(number);
      } else{
        throw new Error('Failed to call API after 5 retries due to rate limiting');
      }
    } finally {
      --this.apiRequestsInProgress;
    }
  }
}
