    public async Task<OpenSSL> GetLatestOpenSSL()
    {
        string latestVersion;
        try
        {
            var responseBody = await client.GetStringAsync("https://config-service/latest");
            dynamic configuration = JsonConvert.DeserializeObject(responseBody);
            latestVersion = Convert.ToString(configuration["version"]);
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Failed to retrieve the latest OpenSSL version.");
            throw; // Rethrow exception after logging it
        }

        if (!cache.TryGetValue(latestVersion, out var openSsl))
        {
            try
            {
                var responseBody = await client.GetStringAsync("https://config-service/OpenSSL/" + latestVersion);
                dynamic configuration = JsonConvert.DeserializeObject(responseBody);

                // Map the OpenSSL configuration into an object and add it to cache
                openSsl = new OpenSSL();
                openSsl.Version = latestVersion;
                openSsl.Path = Convert.ToString(configuration["path"]);
                cache[latestVersion] = openSsl;
