import java.io.*;
import java.nio.file.*;
import java.util.*;
// ... other necessary imports

public class TextFileProcessor {
    private final Path directory;
    // ... other necessary fields

    public TextFileProcessor(Path directory) {
        this.directory = directory;
        // initialize other necessary fields
    }

    public void processFiles() {
        try (Stream<Path> stream = Files.list(directory)) {
            stream
                .filter(Files::isRegularFile)
                .filter(path -> !path.getFileName().toString().startsWith("."))
                .map(this::toTempFile)
                .forEach(tempFile -> executeUtilityAndUpdate(tempFile));
        } catch (IOException e) {
            // handle exception
        }
    }

    private TempFile toTempFile(Path path) {
        String contentHash = getContentHash(path);
        Path tempPath = directory.resolve("." + contentHash);

        if (!Files.exists(tempPath)) {
            return new TempFile(path, tempPath);
        } else {
            // handle collision by creating a different hash or similar
            throw new RuntimeException("Collision with existing file");
        }
    }

    private String getContentHash(Path path) {
        try (BufferedReader reader = Files.newBufferedReader(path)) {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");

            char[] buffer = new char[8192];
            int read;
            while ((read = reader.read(buffer, 0, buffer.length)) > 0) {
                digest.update(new String(buffer, 0, read).getBytes());
            }

            return bytesToHex(digest.digest());
        } catch (IOException | NoSuchAlgorithmException e) {
            // handle exception
        }
    }

    private void executeUtilityAndUpdate(TempFile tempFile) {
        try {
            Process process = Runtime.getRuntime().exec("command " + tempFile.getPath());

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                // handle utility failure by implementing retry logic
                throw new RuntimeException("Utility execution failed");
