using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public static byte[] DecryptWithAes(byte[] key, byte[] iv, byte[] ciphertext)
{
    // Validate parameters
    if (key == null || key.Length <= 0)
        throw new ArgumentNullException("key");
    if (iv == null || iv.Length <= 0)
        throw new ArgumentNullException("iv");
    if (ciphertext == null || ciphertext.Length <= 0)
        throw new ArgumentNullException("ciphertext");

    // Create AesCng object and set key and IV
    using (Aes aesAlg = new AesCng())
    {
        aesAlg.Key = key;
        aesAlg.IV = iv;

        // Create decryptor
        ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

        // Decrypt ciphertext and return the plaintext as byte array
        using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
        {
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
            {
                using (BinaryReader br = new BinaryReader(csDecrypt))
                {
                    return br.ReadBytes((int)msDecrypt.Length);
                }
            }
        }
    }
}
```
