            params: { directory, siteName }
        });
        return response.data;
    } catch (err) {
        console.error(err);
        throw err;  // Retrow the error to be caught in processCommandWithIntegration
    }
};

// Define the function for processing commands with integration
const processCommandWithIntegration = async (command, directory, siteName, apiKey) => {

    // Check if web.config is present
    const configPath = path.join(directory, 'web.config');
    if (!fs.existsSync(configPath)) return null;

    // Check command against whitelist
    if (!ALLOWED_COMMANDS.includes(command)) throw new Error('Unauthorized command');

    try {
        const stdout = await execFile(command, [], { cwd: directory });

        let metadata;

        // Check cache for existing data before calling API
        if (apiCache.has(stdout)) {
            metadata = apiCache.get(stdout);
        } else {

            const limiter = rateLimit({
                windowMs: 15 * 60 * 1000, // 15 minutes
                max: API_RATE_LIMIT, // limit each IP to API_RATE_LIMIT requests per windowMs
            });

            await limiter.consume(stdout);

            metadata = await apiCall(directory, siteName, apiKey);

            // Set the result in cache for future use
            apiCache.set(stdout, metadata, 60 * 60);  // Cache for an hour
        }

        console.log('Command processed successfully');
        return { output: stdout, metadata };

    } catch (err) {
        console.error('Error processing command', err);
        throw err;
    }
};
```
Please note that actual API calls and web.config check would be specific to your context and should be replaced by appropriate implementation. Also this function is not optimised for performance or scalability, you might want to add caching strategy (like Redis) for command outputs and a load balancer if dealing with multiple servers.
