['Below is an example of how you might approach this problem using C with a parallel reading process via POSIX threads (pthreads). This code includes error checking for invalid inputs and will resize the array in response to large inputs. Please note that this is just an example, so it may not be efficient or safe for all use cases. The actual implementation would depend on your specific system requirements and constraints.

```C
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int* array;
    size_t used;
    size_t capacity;
} Array;

void initArray(Array* a, size_t initialCapacity) {
    a->array = malloc(initialCapacity * sizeof(int));
    a->used = 0;
    a->capacity = initialCapacity;
}

void insertArray(Array* a, int element) {
    if (a->used == a->capacity) {
        a->capacity *= 2;
        a->array = realloc(a->array, a->capacity * sizeof(int));
    }
    a->array[a->used++] = element;
}

void freeArray(Array* a) {
    free(a->array);
    a->array = NULL;
    a->used = a->capacity = 0;
}

int maxVal;
pthread_mutex_t mutex1 = PTHREAD_MUTEX_INITIALIZER;
void* findMax(void* arg) {
    Array* arr = (Array*)arg;
    int localMax = arr->array[0];
    for (size_t i = 1; i < arr->used; i++) {
        if (arr->array[i] > localMax) {
            localMax = arr->array[i];
        }
    }

    pthread_mutex_lock(&mutex1);
    if(localMax > maxVal){
        maxVal = localMax;
    }
    pthread_mutex_unlock(&mutex1);
}

int main() {
    Array arr;
    initArray(&arr, 5);   // Initial capacity set to 5

    int num;
    while (scanf("%d", &num) == 1) {
        insertArray(&arr, num);
    }

    if(arr.used < 2){
        printf("No largest integer can be determined.");
        freeArray(&arr);
        return 0;
    }

    maxVal = arr.array[0];
    pthread_t thread1, thread2;
    int mid = arr.used/2;
    if(pthread_create(&thread1, NULL, findMax, &arr)){
        printf("Error creating threads");
        freeArray(&arr);
        return 1;
    }

    Array arr2;
    initArray(&arr2, mid);
    for (size_t i = mid; i < arr.used; i++) {
        insertArray(&arr2, arr.array[i]);
    }

    if(pthread_create(&thread2, NULL, findMax, &arr2)){
        printf("Error creating threads");
        freeArray(&arr);
        return 1;
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    printf("Largest integer is %d", maxVal);

    freeArray(&arr);
    freeArray(&arr2);

    return 0;
}
```

Please note that the code above does not handle all possible edge cases and error scenarios. It's also important to remember that in a real-world setting, you would likely use a library like OpenMP for parallel processing rather than manually managing threads with pthreads.
']

