['```cpp
#include <iostream>
#include <unordered_map>
#include <vector>
#include <thread>
#include <mutex>
#include <atomic>
#include <chrono>
#include <fstream>

struct Attack {
    std::string name;
    int cooldown;
};

class CombatStrategyManager {
private:
    std::vector<Attack> attacks;
    std::unordered_map<std::thread::id, Attack*> currentAttacks;
    std::mutex mtx;
    std::atomic<bool> running;
    std::ofstream logFile;

public:
    CombatStrategyManager() : running(true), logFile("log.txt") { }
    ~CombatStrategyManager() { running = false; }

    void updateAttackDatabase() {
        // Call to external database API.
        std::this_thread::sleep_for(std::chrono::minutes(5));
    }

    Attack* selectNextAttack(Attack* current) {
        int index = (rand() % attacks.size());
        if (attacks[index].name != current->name && std::chrono::system_clock::now() >= current->cooldown)
            return &attacks[index];

        for (auto& attack : attacks) {
            if (std::chrono::system_clock::now() >= attack.cooldown)
                return &attack;
        }

        // If all attacks are on cooldown, return current attack
        return current;
    }

    Attack* getCurrentAttack(std::thread::id threadId) {
        std::lock_guard<std::mutex> lock(mtx);
        if (currentAttacks.find(threadId) == currentAttacks.end()) {
            currentAttacks[threadId] = &attacks[rand() % attacks.size()];
        }

        return currentAttacks[threadId];
    }

    void combatStrategyThreadFunc() {
        while (running) {
            auto threadId = std::this_thread::get_id();
            Attack* current = getCurrentAttack(threadId);

            logFile << "[" << std::chrono::system_clock::now().time_since_epoch().count() 
                    << "] Thread " << threadId << " using attack: " << current->name << "\n";

            Attack* nextAttack = selectNextAttack(current);
            currentAttacks[threadId] = nextAttack;

            std::this_thread::sleep_for(std::chrono::milliseconds(50)); // sleep to control latency
        }
    }

    void startCombatStrategyManager() {
        updateAttackDatabase();

        for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
            std::thread(&CombatStrategyManager::combatStrategyThreadFunc, this).detach();
        }
    }
};
```
This C++ code implements a `CombatStrategyManager` class that handles the combat strategy of a video game character. This includes selecting from a predefined set of attacks with a cooldown period and ensuring that the same attack is not used consecutively for each instance of the game character running this function concurrently without causing race conditions.

The `combatStrategyThreadFunc` function represents an example of how you might use this class in a multi-threaded environment. It continuously selects and logs the next attack to be used based on the cooldown period for each character, ensuring efficient handling of large numbers of characters. The logging is done to a file for later analysis purposes.
