using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Diagnostics;

public class RandomValueManager<T> where T : IComparable<T>
{
    private ConcurrentDictionary<Type, IRandomGenerator<T>> generators = new ConcurrentDictionary<Type, IRandomGenerator<T>>();
    private object lockObj = new object();

    public void Initialize(T min, T max)
    {
        if (min.CompareTo(max) > 0)
        {
            throw new ArgumentException("Min value is greater than Max value!");
        }

        generators[typeof(T)] = new RandomGenerator<T>(min, max);
    }

    public T GenerateValue()
    {
        IRandomGenerator<T> generator;
        if (generators.TryGetValue(typeof(T), out generator))
        {
            return generator.Generate();
        }

        throw new InvalidOperationException("No generator for the specified type exists.");
    }

    public void Reset()
    {
        generators = new ConcurrentDictionary<Type, IRandomGenerator<T>>();
    }
}

public interface IRandomGenerator<out T> where T : IComparable<T>
{
    T Generate();
}

public class RandomGenerator<T> : IRandomGenerator<T> where T : IComparable<T>
{
    private T min;
    private T max;
    private Stopwatch stopWatch = new Stopwatch();
    private long generationCount = 0;

    public RandomGenerator(T min, T max)
    {
        this.min = min;
        this.max = max;

        if (typeof(T) != typeof(int)) 
            throw new NotImplementedException("Only integers are supported for now.");

        stopWatch.Start();
    }

    public T Generate()
    {
        Interlocked.Increment(ref generationCount);

        var random = new Random((int)stopWatch.ElapsedTicks);

        if (typeof(T) == typeof(int)) 
            return (T)(object)random.Next(Convert.ToInt32(min), Convert.ToInt32(max));

        throw new NotImplementedException("Only integers are supported for now.");
    }
}
