#include <pthread.h>
#include <stdlib.h>

typedef struct {
    // add necessary fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    int head, tail;
    NFAPI_CRC_INDICATION_PDU_T* buffer[10000];
} CircularBuffer;

void init(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    pthread_mutex_init(&cb->lock, NULL);
}

int push(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T* value) {
    if((cb->head + 1) % 10000 == cb->tail) return -1; // buffer is full

    pthread_mutex_lock(&cb->lock);

    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % 10000;

    if(cb->head == cb->tail) {
        // buffer is full, start overwriting the oldest data
        cb->tail = (cb->tail + 1) % 10000;
    }

    pthread_mutex_unlock(&cb->lock);

    return 0; // success
}

NFAPI_CRC_INDICATION_PDU_T* pop(CircularBuffer *cb) {
    if(cb->head == cb->tail) return NULL; // buffer is empty

    pthread_mutex_lock(&cb->lock);

    NFAPI_CRC_INDICATION_PDU_T* value = cb->buffer[cb->tail];
    cb->tail = (cb->tail + 1) % 10000;

    pthread_mutex_unlock(&cb->lock);

    return value; // success
}

void clear(CircularBuffer *cb) {
    pthread_mutex_lock(&cb->lock);

    cb->head = 0;
    cb->tail = 0;

    pthread_mutex_unlock(&cb->lock);
}
```
