['Here is an implementation example for `DynamicValueGenerator` class: 

```csharp
using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;
using Newtonsoft.Json;

public class DynamicValueGenerator {
    private ConcurrentDictionary<string, Range> ranges = new ConcurrentDictionary<string, Range>();

    public struct Range {
        public string Id { get; set; }
        public int Version { get; set; }
        public float Start { get; set; }
        public float End { get; set; }
        public bool InclusiveStart { get; set; }
        public bool InclusiveEnd { get; set; }
    }

    private static readonly Lazy<DynamicValueGenerator> lazy = new Lazy<DynamicValueGenerator>(() => new DynamicValueGenerator());

    public static DynamicValueGenerator Instance { get { return lazy.Value; } }

    // Use a thread-safe collection for managing concurrent access and updates to ranges
    private ConcurrentDictionary<string, Range> activeRanges = new ConcurrentDictionary<string, Range>();

    public DynamicValueGenerator() {
        AddDefaultRange();
    }

    // Load/Save methods here that can load or save data from an external configuration service

    private void AddDefaultRange() {
        activeRanges.TryAdd("default", new Range { Id = "default", Version = 1, Start = 0f, End = 1f, InclusiveStart = true, InclusiveEnd = false });
    }

    public float GenerateFloat(string rangeId) {
        if (activeRanges.TryGetValue(rangeId ?? "default", out Range range)) {
            return GenerateFromRange(range);
        } else {
            throw new InvalidOperationException("Invalid range id");
        }
    }

    public int GenerateInteger(string rangeId) {
        if (activeRanges.TryGetValue(rangeId ?? "default", out Range range)) {
            return (int)GenerateFromRange(range);
        } else {
            throw new InvalidOperationException("Invalid range id");
        }
    }

    private float GenerateFromRange(Range range) {
        var random = new Random();

        // Calculating the bounds taking into account the inclusive/exclusive nature of the range endpoints
        var lowerBound = range.InclusiveStart ? Math.Ceiling(range.Start) : Math.Floor(range.Start);
        var upperBound = range.InclusiveEnd ? Math.Floor(range.End) : Math.Ceiling(range.End);

        // Generating a random float number within the calculated bounds
        return (float)(lowerBound + random.NextDouble() * (upperBound - lowerBound));
    }

    public override string ToString() {
        return JsonConvert.SerializeObject(activeRanges);
    }
}
```
Note: This is a simplified example and doesn't handle all the requirements you mentioned in the question like thread safety for updating ranges, integration with an external logging system or service discovery. Real world applications would likely use more complex patterns for these issues, such as using locks to control access to shared data, using dependency injection to inject a logger, or implementing retries and circuit breakers to handle network failures.
