['Here is a simple solution that meets the requirements of your question:

```c
#include <stdio.h>
#include <stdlib.h>

typedef enum {SUCCESS, FAIL} status_t;

typedef struct {
    char timestamp[20];
    double amount;
    status_t status;
} transaction_t;

transaction_t* readTransactions(const char *filename, int *count) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening the file.\n");
        return NULL;
    }

    int max = 10;
    transaction_t* transactions = malloc(max * sizeof(*transactions));
    char line[256];
    *count = 0;

    while (fgets(line, sizeof(line), file)) {
        if (*count == max) {
            max *= 2;
            transactions = realloc(transactions, max * sizeof(*transactions));
        }

        transaction_t* current = &transactions[*count];

        if (sscanf(line, "%19[^,],%lf,%u", current->timestamp, &current->amount, 
                   &current->status) != 3) {
            printf("Malformed input at line %d.\n", *count + 1);
            continue;
        }
        ++(*count);
    }

    fclose(file);
    return transactions;
}

void processTransactions(transaction_t* transactions, int count) {
    for (int i = 0; i < count; ++i) {
        if (transactions[i].status == SUCCESS) {
            printf("Transaction: %s Amount: %.2f Status: Successful\n", 
                   transactions[i].timestamp, transactions[i].amount);
        } else {
            printf("Transaction: %s Amount: %.2f Status: Failed\n", 
                   transactions[i].timestamp, transactions[i].amount);
        }
    }
}
```
The function `readTransactions` reads a CSV file and returns an array of transaction structures. It dynamically allocates memory for the maximum number of expected transactions, doubling that allocation whenever it runs out of space. The `processTransactions` function then processes these transactions by printing their details if they're successful. 

Please note that this is a simple implementation and doesn't include error handling or logging as per your requirements. You could add more robust error handling, for example, checking the return value of `fopen`, `malloc`, and `sscanf` to handle potential errors. For production code, you should also consider adding logging mechanisms (like a log file) to record errors and exceptions.
