// The dynamic array and its associated lock.
UEStats* statsArray = NULL;
size_t statsCount = 0, statsCapacity = 0;
pthread_mutex_t statsLock = PTHREAD_MUTEX_INITIALIZER;

void addStats(const UEStats newStat) {
    pthread_mutex_lock(&statsLock);

    // If the array is full, reallocate it.
    if (statsCount == statsCapacity) {
        statsCapacity = statsCapacity ? statsCapacity * 2 : 1;
        statsArray = realloc(statsArray, sizeof(UEStats) * statsCapacity);
    }

    // Check for duplicate UE_ID.
    for (size_t i = 0; i < statsCount; ++i) {
        if (!strcmp(newStat.UE_ID, statsArray[i].UE_ID)) {
            printf("Error: Duplicate UE_ID.\n");
            pthread_mutex_unlock(&statsLock);
            return;
        }
    }

    // Add the new stat and update count.
    memcpy(&statsArray[statsCount++], &newStat, sizeof(UEStats));

    pthread_mutex_unlock(&statsLock);
}
