['Writing a full-fledged JPEG image parser in C is an extensive task that involves multiple aspects of programming such as file I/O, memory management, error handling and data processing. Here's a high-level example of how you might structure the code for parsing metadata from a JPEG image.

```C
#include <stdio.h>
#include <stdlib.h>
#include <jpeglib.h>
#include "metadata.h" // Replace with your actual metadata header file

typedef struct {
    int chrominance_subsampling;
    bool alpha_channel_present;
    int bit_depth;
    int position;
} Metadata;

Metadata* parseJpeg(const char* filename) {
    FILE *file = fopen(filename, "rb"); // Open the file in binary mode for reading

    if (file == NULL) {
        printf("Failed to open JPEG file.\n");
        return NULL;
    }

    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;

    // Initialize the JPEG decompression object with the default error handler
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    // Specify the data source (our file) and then read JPEG header
    jpeg_stdio_src(&cinfo, file);
    jpeg_read_header(&cinfo, TRUE);

    if(cinfo.jpeg_color_space == JCS_EXT_RGBA || cinfo.jpeg_color_space == JCS_CMYK) {
        // Extract the metadata from the header of the JPEG file
        Metadata* metadata = malloc(sizeof(Metadata));

        metadata->chrominance_subsampling = cinfo.comp_info[0].h_samp_factor; // Assuming the chrominance subsampling is always the same for all components
        metadata->alpha_channel_present = (cinfo.jpeg_color_space == JCS_EXT_RGBA);
        metadata->bit_depth = cinfo.input_components == 3 ? 8 : 24; // Assuming RGB or YCbCr are commonly used

        return metadata;
    } else {
        printf("Unsupported color space in JPEG file.\n");
        jpeg_destroy_decompress(&cinfo);
        fclose(file);

        return NULL; // Return an error if the color space is not recognized or supported.
    }

    jpeg_destroy_decompress(&cinfo);
    fclose(file);
}
```
This example assumes you have a separate header file (metadata.h) that contains your Metadata struct definition and function prototypes, as well as any necessary error handling or data augmentation code for the library. Real-world development would also involve more comprehensive unit tests and documentation. 

