void initialize_AES(const char *password, int iterations) {
    EVP_PKEY_CTX *pctx;
    EVP_PKEY *pkey = NULL;
    unsigned char salt[8]; // Replace with your desired salt length
    RAND_bytes(salt, sizeof(salt));

    pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HKDF, NULL);
