        || !EVP_PKEY_hkdf_ctrl(pctx, EVP_PKEY_OP_DERIVE, EVP_PKEY_CTRL_SET_MD, EVP_sha256()) 
        || !EVP_PKEY_hkdf_ctrl(pctx, EVP_PKEY_OP_DERIVE, EVP_PKEY_CTRL_SET_INFO, salt, sizeof(salt))
        || !EVP_PKEY_derive_set_peer(pctx, password)
        || !EVP_PKEY_derive(pctx, NULL)) {
        // Handle error here.
