Offset* manage_memory(int count, int min, int max) {
    if (count > 10000 || count <= 0) return NULL;
    srand((unsigned int)time(NULL));

    Offset* arr = (Offset*)malloc(sizeof(Offset)*count);
    if (arr == NULL) exit(EXIT_FAILURE);

    for (int i = 0; i < count; ++i) {
        Record* data = (Record*)malloc(sizeof(Record));
        if (data == NULL) {
            free(arr);
            return NULL;
        }

        memset(data->buffer, 'A', 256); // Fill the buffer with 'A's.
        data->value = min + rand() % ((max + 1) - min);

        arr[i].id = i;
        arr[i].data = data;
    }

    return arr;
}
