CryptoAlgorithm* loadSharedLibrary(char *libPath, unsigned long checksum){
    if(!verifyChecksum(libPath,checksum)){
        syslog(LOG_ERR,"Failed to verify library at %s", libPath);
        return NULL;
    }

    void *handle = dlopen(libPath, RTLD_LAZY);
    if (!handle) {
        syslog(LOG_ERR,"Failed to load library at %s: %s\n", libPath, dlerror());
        return NULL;
    }

    CryptoAlgorithm* (*listCryptoAlgoFunc)();
    *(void **) (&listCryptoAlgoFunc) = dlsym(handle, "listCryptoAlgo");

    char *error_message;
    if ((error_message = dlerror()) != NULL)  {
        syslog(LOG_ERR,"Failed to load function listCryptoAlgo: %s\n", error_message);
        return NULL;
    }

    CryptoAlgorithm* cryptoList = (*listCryptoAlgoFunc)();
    if(!cryptoList){
        syslog(LOG_ERR,"Failed to get list of functions from library at %s\n", libPath);
        return NULL;
    }

    syslog(LOG_INFO, "Successfully loaded cryptographic algorithms from %s",libPath);
    return cryptoList;
}
