file_metadata **metadata;
file_info **infos;
int count = 0; // Keeps track of current number of files.

void initialize() {
    file_offsets = malloc(10000 * sizeof(long));
    file_paths = malloc(10000 * sizeof(char*));
    metadata = malloc(10000 * sizeof(file_metadata*));
    infos = malloc(10000 * sizeof(file_info*));
}

void destroy() {
    free(file_offsets);
    for (int i = 0; i < count; ++i) {
        free(file_paths[i]);
        free(metadata[i]);
        json_object_put(infos[i]->tags); // Release JSON object.
        free(infos[i]);
    }
    free(file_paths);
    free(metadata);
    free(infos);
}

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s) {
  size_t new_len = s->len + size*nmemb;
  s->ptr = realloc(s->ptr, new_len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "realloc() failed\n");
    exit(EXIT_FAILURE);
  }
  memcpy(s->ptr+s->len, ptr, size*nmemb);
  s->ptr[new_len] = '\0';
  s->len = new_len;

  return size*nmemb;
}

void fetch_metadata(const char *filepath) {
    CURL *curl = curl_easy_init();
    struct string s;
    init_string(&s);

    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/metadata"); // Set your API endpoint
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);
        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            pthread_mutex_lock(&lock);
            file_paths[count] = strdup(filepath); // Copy the string to prevent corruption.

            struct json_object *parsed_json = json_tokener_parse(s.ptr); // Use a JSON library to parse the result.
            metadata[count] = malloc(sizeof(file_metadata));
            infos[count] = malloc(sizeof(file_info));

            /* Populate metadata and file_infos from parsed_json */
            json_object_put(parsed_json); // Cleanup
            ++count;
            pthread_mutex_unlock(&lock);
        }

        free_string(&s);
        curl_easy_cleanup(curl);
    }
}
