```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef int64_t offset_t;
typedef uint32_t key_t;
typedef int32_t value_t;
typedef struct record_s {
    key_t key;
    value_t value;
} record_t;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // for thread safety

void manage_memory(size_t num_offsets, size_t num_keys, unsigned int *seed) {
    offset_t* offsets = malloc(num_offsets * sizeof(*offsets));
    key_t* keys = malloc(num_keys * sizeof(*keys));
    record_t* records = calloc(num_offsets, sizeof(*records)); // ensure zeroed memory

    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    srand(*seed);

    for(size_t i = 0; i < num_offsets; ++i){
        offsets[i] = 2 * i - 5;
    }

    // generate unique prime numbers
    size_t primes[] = {101, 103, 107, 109, 113, 127, 131, 137, 139};

    for (size_t i = 0; i < num_keys; ++i){
        keys[i] = primes[i % sizeof(primes)]; // just a sample logic to get unique prime numbers between 100 and 1000
    }

    // initialize records with random value within -100 to 100 and ensure uniqueness
    size_t unique_values[201] = {0}; // map of used values, allowing a range from -100 to 100

    for (size_t i = 0; i < num_offsets; ++i){
        while(1){
            value_t random_value = rand() % 201 - 100; // get a value within -100 to 100
            if (!unique_values[random_value + 100]){ // check uniqueness, +100 for indexing from zero
                unique_values[random_value + 100] = 1; // mark as used
                records[i].key = keys[i % num_keys]; // use modulus to handle when `num_offsets` > `num_keys`
                records[i].value = random_value; 
                break;
            }
        }
    }

    for (size_t i = 0; i < num_offsets; ++i){
        pthread_mutex_lock(&lock); // lock before modifying shared resource

        records[i].value += offsets[i] * keys[i % num_keys];

        pthread_mutex_unlock(&lock); // unlock after modification
    }

    free(offsets);
    free(keys);
    free(records);
}
```
This solution uses locks for thread safety, but spinlocks or other forms of synchronization might be more suitable depending on the specific requirements and constraints of your environment. 

Please remember to always use memory allocation functions carefully, handle errors correctly, and avoid memory leaks by freeing allocated memory after it is no longer needed. It's also crucial to consider memory fragmentation and cache locality in your implementation for optimal performance under varying memory pressure scenarios. Please note that this code doesn't provide integrity checks like ensuring unique `value_t` values or all `offset_t` adjustments were correctly applied. You may need additional logic to implement these requirements based on your specific use case.
