// We'll use bubble sort for its simplicity and O(n) time complexity
void bubbleSort(int* arr, int n){ 
    for (int i = 0; i < n-1; i++){       
        for (int j = 0; j < n-i-1; j++){  
            if (arr[j] > arr[j+1]){
                // Swap the elements
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }
}

