    public DynamicValueGenerator() { }

    // Add a range
    public void AddRange(double min, double max) {
        lock(_lock) {
            if (max <= min) throw new ArgumentException("Max should be greater than Min"); 

            // Ensure the new range doesn't overlap with existing ones.
            if (_ranges.Any(range => !(range.Item1 > max || range.Item2 < min))) {
                throw new ArgumentException("New range overlaps with existing ranges");
            }

            _ranges.Add(Tuple.Create(min, max));
        }
    }

    // Remove a range
    public void RemoveRange(double min, double max) {
        lock(_lock) { 
            _ranges.RemoveAll(range => Math.Abs(range.Item1 - min) < Double.Epsilon && Math.Abs(range.Item2 - max) < Double.Epsilon);
        }
    }

    // Generate random number within specified ranges
    public double GetRandomValue() {
        lock(_lock) { 
            if (!_ranges.Any()) throw new InvalidOperationException("No ranges defined");

            var range = _ranges[new Random().Next(0, _ranges.Count)];
            return new Random().NextDouble() * (range.Item2 - range.Item1) + range.Item1;
        }
    }

    // Override ToString to provide clear representation of all active ranges
    public override string ToString() {
        StringBuilder sb = new StringBuilder();

        lock(_lock) { 
