["Here's a basic implementation of your problem in C++. This program uses `std::forward_list` for efficient memory use and `std::atomic` for thread-safe concurrent access. Note that this doesn't account for all edge cases you might want to handle, but it'll give you a starting point:

```C++
#include <string>
#include <forward_list>
#include <mutex>
#include <atomic>

class StringList {
private:
    std::forward_list<std::string> list;
    std::mutex mtx;  // for thread safety
    std::atomic<int> limit = 0;
    int counter = 0;

public:
    void setLimit(int new_limit) {
        limit = new_limit;
    }

    bool insertAfterTarget(const std::string& target, const std::string& insertion) {
        if (counter >= limit || limit == 0) {
            return false;  // exceeded limit or not set
        }

        mtx.lock();  // begin critical section
        ++counter;

        auto prev = list.before_begin();
        auto it = list.begin();
        while (it != list.end()) {
            if (*it == target) {
                list.insert_after(prev, insertion);

                mtx.unlock();  // end critical section
                return true;
            }
            ++it; ++prev;
        }

        // not found: append to end
        list.push_front(insertion);

        mtx.unlock();  // end critical section
        return true;
    }
};
```
Please note that std::forward_list does not provide efficient insertions at arbitrary positions, so the program searches for the target linearly from start to finish. Depending on your usage pattern and requirements, a different data structure might be more appropriate. For example, if you often need to search through the list after initial modifications, std::vector could be a better choice due to its random access performance.
"]

