```csharp
// C# Code:
using System;
using System.Collections.Concurrent;

public class ValueGeneratorManager {
    private readonly ConcurrentDictionary<Type, object> _generators = new ConcurrentDictionary<Type, object>();
    private readonly ConcurrentDictionary<Type, int> _frequencies = new ConcurrentDictionary<Type, int>();

    public void Register(Type type) {
        if (!_generators.ContainsKey(type)) {
            var generator = (IGenerator)_serviceProvider.GetService(typeof(IGenerator));
            _generators[type] = generator;
            _frequencies[type] = 0;
        }
    }

    public void Generate<T>() where T : IComparable {
        if (_generators.TryGetValue(typeof(T), out var generatorObj)) {
            Interlocked.Increment(ref _frequencies[typeof(T)]);
            var generator = (IGenerator<T>)generatorObj;
            return generator.Next();
        } else {
            throw new InvalidOperationException("Generator not found.");
        }
    }

    public void ResetFrequency() {
        foreach(var type in _frequencies.Keys) {
            _frequencies[type] = 0;
        }
    }

    // Other methods for range validation, error handling etc. would go here...
}
```
This is a simplified example and doesn't include all the necessary components such as actual implementations of the IGenerator interface (which would be responsible for generating values), exception handling, concurrency control, and other considerations mentioned in your prompt. The real-world implementation would require more robust design decisions considering performance, scalability, extensibility, memory usage, etc.
