    std::vector<LogEvent> events_;
    std::string deviceSerialNumber_;
};

class DeviceLogsManager {
public:
    void addDevice(const std::string& serialNumber) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (devices_.count(serialNumber) == 0) {
            devices_[serialNumber] = DeviceLogs(serialNumber);
        }
    }

    void removeDevice(const std::string& serialNumber) {
        std::lock_guard<std::mutex> lock(mtx_);
        devices_.erase(serialNumber);
    }

    void addEventToDevice(const std::string& serialNumber, const LogEvent& logEvent) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (devices_.count(serialNumber) != 0) {
            devices_[serialNumber].addEvent(logEvent);
        } else {
            throw std::runtime_error("No such device");
        }
    }

    DeviceLogs getDeviceLogs(const std::string& serialNumber) const {
        std::lock_guard<std::mutex> lock(mtx_);
        if (devices_.count(serialNumber) != 0) {
            return devices_.at(serialNumber);
        } else {
            throw std::runtime_error("No such device");
        }
    }

