```csharp
using System;
using System.Collections.Generic;
using System.Threading;
using System.Linq;
using System.Reflection;

public class DynamicValueGenerator<T> where T : IComparable<T>
{
    private List<(Guid id, T lowerBoundary, T upperBoundary, object version)> _ranges = new();
    private ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();

    public void AddRange((Guid Id, T LowerBoundary, T UpperBoundary, object Version) range)
    {
        _lock.EnterWriteLock();
        try
        {
            if (_ranges.Any(x => x.id == range.Id))
                throw new ArgumentException("Duplicate IDs are not allowed.");

            var overlappingRanges = _ranges.Where(x => (range.LowerBoundary.CompareTo(x.upperBoundary) < 0 && range.UpperBoundary.CompareTo(x.lowerBoundary) > 0));
            if (overlappingRanges.Any())
                throw new ArgumentException("Overlapping ranges are not allowed.");

            var outOfOrderRange = _ranges.Where(x => x.upperBoundary.CompareTo(range.LowerBoundary) > 0 && x.lowerBoundary.CompareTo(range.UpperBoundary) < 0);
            if (outOfOrderRange.Any())
                throw new ArgumentException("Out of order range is not allowed.");

            _ranges.Add(range);
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }

    public void RemoveRange((Guid Id, T LowerBoundary, T UpperBoundary, object Version) range)
    {
        _lock.EnterWriteLock();
        try
        {
            _ranges.RemoveAll(x => x.id == range.Id);
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }

    public T GenerateRandomValue()
    {
        _lock.EnterReadLock();
        try
        {
            var random = new Random();
            var rangeIndex = random.Next(_ranges.Count);
            dynamic lowerBoundary = _ranges[rangeIndex].lowerBoundary;
            dynamic upperBoundary = _ranges[rangeIndex].upperBoundary;

            if (typeof(T) == typeof(float))
                return (T)(object)(random.NextDouble() * (double)(upperBoundary - lowerBoundary) + (double)lowerBoundary);
            else if (typeof(T) == typeof(int))
                return (T)(object)random.Next((int)lowerBoundary, (int)upperBoundary + 1);
            else throw new ArgumentException("Unsupported type");
        }
        finally
        {
            _lock.ExitReadLock();
        }
    }

    public override string ToString()
    {
        var sb = new StringBuilder();
        foreach (var range in _ranges)
        {
            sb.AppendLine($"ID: {range.id}, Lower Boundary: {range.lowerBoundary}, Upper Boundary: {range.upperBoundary}, Version: {range.version}");
        }

        return sb.ToString();
    }
}
``` 
