#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    _Atomic(int) value;
} Record;

struct MemoryPool {
    pthread_mutex_t lock;
    void *memory;
    size_t memorySize;
    size_t allocated;
};

void* allocateFromMemoryPool(_Atomic(long)* offsets, int* keys, Record* records, struct MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->allocated + sizeof(Record) > pool->memorySize) {
        // Allocate more memory if necessary
        pool->memory = realloc(pool->memory, 2 * pool->memorySize);
        pool->memorySize = 2 * pool->memorySize;
    }
    void* allocation = (char*)pool->memory + pool->allocated;
    pool->allocated += sizeof(Record);
    pthread_mutex_unlock(&pool->lock);
    return allocation;
}

void initialize(_Atomic(long)* offsets, int* keys, Record* records, size_t length) {
    struct MemoryPool pool = {.memorySize = 1024 * 1024, .allocated = 0}; // Start with 1MB

    for (size_t i = 0; i < length; ++i) {
        Record* record = allocateFromMemoryPool(offsets, keys, records, &pool);
        if (!record) return; // Out of memory

        record->value = rand() % 100; // Assuming the range is [0, 99]
    }

    free(pool.memory);
}
```

