// Function to parse XML element by name using XPath
xmlNodePtr parseXMLElement(xmlDocPtr doc, xmlChar *xpathExpr) {
    xmlXPathContextPtr context;
    xmlXPathObjectPtr result;

    context = xmlXPathNewContext(doc);
    if (context == NULL) return NULL;

    result = xmlXPathEvalExpression(xpathExpr, context);
    xmlXPathFreeContext(context);

    if (result == NULL || result->nodesetval == NULL) {
        xmlXPathFreeObject(result);
        return NULL;
    }

    xmlNodePtr node = result->nodesetval->nodeTab[0];  // Get the first matching element
    xmlXPathFreeObject(result);  

