function querySelectorAll(selector, parentNode = document) {
  const iterator = document.evaluate(selector, parentNode, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
  const nodes = [];

  for (let node = iterator.snapshotItem(); node; node = iterator.iterateNext()) {
    nodes.push(node);
  }

  return nodes;
}

// Function to search the DOM using XPath
function domTraversal(selector) {
  const matches = querySelectorAll(selector, document);
  for (const match of matches) {
      match.textContent += '/';
    }
}

