['Below is a very basic outline of how you might implement this task in C. Note that TIFF metadata extraction and hashing are not provided as these are complex tasks and there are many libraries available (like libtiff and OpenSSL) to do these tasks, depending on the exact requirements. This example also doesn't include logging or file locking mechanisms, which would require more specifics about your use case.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h> // You need to install OpenSSL

// Assuming TIFF metadata extraction and validation as separate functions
int validateMetadata(char* filePath, int *bitsPerSample, int *samplesPerPixel, int *extraSamples);
void extractMetadata(char* filePath, int *bitsPerSample, int *samplesPerPixel, int *extraSamples);

// Function to compute the MD5 hash of a string and return it as hexadecimal string
const char *processImageAndComputeHashWithLogging(char* tiffFilePath, char* inputString, int maxLength, char* logFilePath, int supportedBitDepths[], int size) {
    static char hexDigest[33]; // MD5 digest is 16 bytes long, each byte represented as two hex characters and a null terminator

    int bitsPerSample, samplesPerPixel, extraSamples;
    if (!validateMetadata(tiffFilePath, &bitsPerSample, &samplesPerPixel, &extraSamples)) {
        fprintf(stderr, "Invalid metadata\n"); // You need to log this in a production environment
        return NULL;
    }

    int isSupported = 0;
    for (int i = 0; i < size; ++i) {
        if (bitsPerSample == supportedBitDepths[i]) {
            isSupported = 1;
            break;
        }
    }

    if (!isSupported) {
        fprintf(stderr, "Unsupported bit depth\n"); // You need to log this in a production environment
        return NULL;
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)inputString, strlen(inputString), digest);

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&hexDigest[i*2], "%02x", digest[i]);
    }

    return hexDigest;
}
```
To use the function:
