// Define a compression context structure.
typedef struct {
    z_stream stream;
} compression_context;

void initialize_compression(compression_context* ctx) {
    ctx->stream.zalloc = Z_NULL;
    ctx->stream.zfree = Z_NULL;
    ctx->stream.opaque = Z_NULL;
    deflateInit(&ctx->stream, Z_DEFAULT_COMPRESSION);
}

int compress_data(compression_context* ctx, uint8_t* input, size_t input_len, uint8_t* output, size_t* output_len) {
    ctx->stream.avail_in = input_len;
    ctx->stream.next_in = input;

    ctx->stream.avail_out = *output_len;
    ctx->stream.next_out = output;

    int retval = deflate(&ctx->stream, Z_FINISH);
    assert(retval == Z_STREAM_END); // Check for success.

    *output_len -= ctx->stream.avail_out;
    return Z_OK;
}
