["Here is an outline of how you might implement this in C. The actual implementation may vary based on specific requirements and constraints. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <limits.h>

typedef struct record {
    long offset;
    int key;
    double timestamp;
} Record;

typedef struct cache {
    pthread_mutex_t lock;
    size_t size;
    size_t capacity;
    Record* records;
    size_t* accessOrder;
    size_t oldestIdx;  // Index of the oldest record in 'records' array.
} Cache;

Cache cache = {
    .lock = PTHREAD_MUTEX_INITIALIZER,
    .size = 0,
    .capacity = SIZE_MAX,  // Set to maximum limit initially.
    .oldestIdx = 0,
};

void initCache(size_t capacity) {
    if (cache.records != NULL) free(cache.records);
    cache.capacity = capacity;
    cache.records = calloc(capacity, sizeof(Record));
    cache.accessOrder = malloc(capacity * sizeof(size_t));
}

void addToCache(long offset, int key) {
    pthread_mutex_lock(&cache.lock);

    if (cache.size < cache.capacity) {
        // Cache has space for a new record.
        ++cache.size;
    } else {
        // Replace the oldest record with a new one.
        cache.oldestIdx = (cache.oldestIdx + 1) % cache.capacity;
    }

    Record* rec = &cache.records[cache.oldestIdx];
    rec->offset = offset;
    rec->key = key;
    time(&rec->timestamp);  // Update timestamp to current time.

    pthread_mutex_unlock(&cache.lock);
}

void destroyCache() {
    free(cache.records);
    cache.records = NULL;
    free(cache.accessOrder);
    cache.accessOrder = NULL;
    cache.size = 0;
    cache.capacity = 0;
}
``` 
This code provides a simple LRU (Least Recently Used) caching mechanism with a fixed size limit. It uses mutexes for thread safety and atomic operations to manage shared resources. Please note that this is just the beginning of your implementation, you will need additional error handling mechanisms, database integration, performance optimization etc. Also consider using other languages/frameworks more suited for large scale systems like Java or Python with multi-threading support for better resource utilization and easier development in a multi-threaded environment.
