typedef struct sensor_data {
    float temperature;
    uint32_t timestamp;
    size_t sequence;
} sensor_data;

sensor_data* manageBuffer(int maxSamples, int newSamples) {
    srand((unsigned int) time(NULL)); // seed the random generator with current time

    static int totalSamples = 0; // keep track of total number of samples across function calls
    sensor_data *buffer = malloc(maxSamples * sizeof(sensor_data));

    if (newSamples > maxSamples) newSamples = maxSamples; // ensure we don't overflow the buffer

    int startIndex = 0; // sliding window: index where to start overwriting old samples
    if (totalSamples + newSamples >= maxSamples) {
        totalSamples = maxSamples; // update total samples count
        startIndex = totalSamples - newSamples; // calculate the starting point for new samples
    } else {
        totalSamples += newSamples; // just update total samples count
    }

    // generate random values and fill in the buffer
    for (int i = 0; i < newSamples; i++) {
        buffer[(startIndex + i) % maxSamples].temperature = ((float)rand()/(float)(RAND_MAX)) * 35.0f; // temperature reading between 0-35 C
        buffer[(startIndex + i) % maxSamples].timestamp = (uint32_t)time(NULL); // timestamp in seconds
        buffer[(startIndex + i) % maxSamples].sequence = totalSamples - newSamples + i; // sequential number
    }

    return buffer;
}
```
