    struct record* ptrRecord;
} offset;

typedef struct {
    long offset;
    int key;
    double timestamp;
} record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
char tempBuffer[1024]; // Buffer to copy char data from the first record

offset* createStructure(long upperLimit, int keyRange) {
    srand(time(NULL));
    offset* array = malloc(sizeof(offset) * 10000);
    if (array == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < 10000; i++) {
        array[i].ptrRecord = malloc(sizeof(record));
        if (array[i].ptrRecord == NULL) {
            perror("Memory allocation failed");
            // Deallocate already allocated memory
            for (int j = 0; j < i; j++) {
                free(array[j].ptrRecord);
            }
            free(array);
            return NULL;
        }
        array[i].value = rand() % upperLimit;
        array[i].ptrRecord->key = rand() % keyRange;
        array[i].ptrRecord->timestamp = time(NULL);
    }

    // Copy the char buffer content from the first record to a temporary buffer
    strncpy(tempBuffer, (char*)array[0].ptrRecord, sizeof(record));

    return array;
}
```
