```c
#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>
#include <sys/stat.h>
#include <errno.h>

typedef struct {
    char *filename;
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    char **metadata; // Assuming metadata is a string array, adjust as needed
} ImageMetadata;

int processImagesAndComputeHashesWithLogging(char *dirPath, char **strings, int maxLength, char *logFilePath, int *supportedBitDepths) {
    FILE *logFile = fopen(logFilePath, "w");
    if (logFile == NULL) {
        printf("Failed to open log file for writing: %s\n", strerror(errno));
        return -1;
    }

    DIR *dir = opendir(dirPath);
    if (dir == NULL) {
        fprintf(logFile, "Failed to open directory: %s\n", strerror(errno));
        fclose(logFile);
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".tif") != NULL) { // Assuming TIFF files end with .tif
            char filePath[1024]; 
            snprintf(filePath, sizeof(filePath), "%s/%s", dirPath, entry->d_name);

            ImageMetadata metadata = parseTiff(filePath); // Assuming the function exists and is correct

            int valid = 0;
            for (int i = 0; supportedBitDepths[i] != 0; ++i) {
                if (metadata.bits_per_sample == supportedBitDepths[i]) {
                    valid = 1;
                    break;
                }
            }

            if (!valid) {
                fprintf(logFile, "Unsupported bit depth in file %s: %d\n", entry->d_name, metadata.bits_per_sample);
                continue; // Skip to next file
            }

            for (int i = 0; strings[i] != NULL; ++i) {
                char *hash = computeMD5(strings[i]);  // Assuming the function exists and is correct
                fprintf(logFile, "Hash of string '%s' from file %s: %s\n", strings[i], entry->d_name, hash);
                free(hash); // Clean up after ourselves
            }
        }
    }

    closedir(dir);
    fclose(logFile);

    return 0;
}
```
This code uses a basic directory traversal approach with `opendir`, `readdir` and `closedir`. It assumes that the TIFF files are located in one directory. For concurrent processing of multiple image files you would need to implement your own mechanism or use a library like OpenMP. Also, you would want to use better error handling and clean up resources properly in a real-world scenario.
