["```C
#include <stdlib.h>
#include <pthread.h>
#define N 1024 // predefined list size
#define REINIT_LIMIT 1000000 // records limit before reinitialization

typedef struct {
    int value;
    long* offset;
} record;

long offsets[N];
int keys[REINIT_LIMIT];
record* records;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // for thread safety

void init() {
    for (int i = 0; i < N; ++i) offsets[i] = /* unique predefined value */;
}

// You need a better random function, this is just an example.
long get_random(long min, long max){ 
    return rand() % (max - min + 1) + min;
}

record* setup(size_t numRecords, int status[]) {
    srand(time(NULL)); // seeding random function

    for (int i = 0; i < REINIT_LIMIT && i < numRecords; ++i) keys[i] = i;

    records = malloc(numRecords * sizeof(*records));
    if (!records){ 
        *status = -1; // failed allocation
        return NULL;
    }

    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = get_random(/* min */, /* max */);
        pthread_mutex_lock(&mutex); // locking for thread safety
        if (i % REINIT_LIMIT == 0 && i != 0){ 
            for (int j = 0; j < REINIT_LIMIT && i+j < numRecords; ++j) keys[j] = j;
        }
        records[i].offset = &offsets[keys[i%REINIT_LIMIT]]; // pointer to offset
        pthread_mutex_unlock(&mutex); // unlocking for thread safety
    }

    *status = 0; // successful initialization
    return records;
}

void cleanup() { 
    free(records);
    pthread_mutex_destroy(&mutex);
}
```
This function uses a global mutex to ensure thread safety. It's crucial as multiple threads might be reading/writing simultaneously to the `keys` and `offsets` arrays, which can lead to data corruption or race conditions if not handled correctly. 

The offset array is updated every N records processed by assigning it a new pointer from our predefined list. 

Each record has an associated offset in the offsets array. When we reach REINIT_LIMIT, we reinitialize the keys to point back to the start of our predefined list. This allows frequent updates without causing memory reallocations or cache pollution.

All dynamically allocated memory is freed with `free()` when no longer needed to prevent memory leaks.
"]

