    long *offsets = malloc(sizeof(long) * count);
    if (!offsets) {
        printf("Failed to allocate memory for offsets\n");
        return -1;
    }

    int *keys = malloc(sizeof(int) * count);
    if (!keys) {
        printf("Failed to allocate memory for keys\n");
        free(offsets);
        return -1;
    }

    record *records = malloc(sizeof(record) * count);
    if (!records) {
        printf("Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return -1;
    }

    // initialize data structures
    srand((unsigned int) time(NULL));

    for (int i = 0; i < count; ++i) {
        offsets[i] = rand();
        keys[i] = i;

        records[i].value = rand() % 100; // assuming range is [0, 99] for simplicity
        records[i].offset = &offsets[i];
    }

    // reinitialize key array after specified count of records have been processed
    int processed_records = 0;

    while (processed_records < count) {
        if (processed_records % reinitialize_count == 0) {
            for (int i = processed_records; i < processed_records + reinitialize_count && i < count; ++i) {
                keys[i] = i; // reinitialization of keys array here
            }
