["This is a complex task that involves several aspects of multi-threaded programming and synchronization, as well as memory management and concurrent access control. Here's the basic structure of such a function in C language. This code doesn't cover every requirement you mentioned due to its length but it should give you an idea on how to start:

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct Record {
    int value;
    atomic_long* offset;
    time_t timestamp;
} Record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; 
static pthread_cond_t cond  = PTHREAD_COND_INITIALIZER;

Record** records;
long* offsets;
int* keys;
int N = 1000, recordCount = 0, keyCounter = 0;
time_t freshnessWindow = 60; // seconds

void init() {
    srand(time(NULL));
    offsets = malloc(sizeof(long) * N);
    keys = malloc(sizeof(int) * N);
    records = calloc(N, sizeof(Record*));
}

void allocateNewOffset() {
    if (recordCount == N - 1) {
        // Reinitialize offsets and keys
        for (int i = 0; i < N; ++i) {
            offsets[i] = rand(); // predefined value or checksum
            keys[i] = keyCounter++;
        }

        recordCount = 0;
    } else {
        ++recordCount;
    }
}

void* handleRecord(void* arg) {
    int index = *((int*)arg);

    pthread_mutex_lock(&mutex);

    if (records[index] == NULL || time(NULL) - atomic_load_explicit(&records[index]->timestamp, memory_order_relaxed) > freshnessWindow) {
        Record* record = malloc(sizeof(Record));
        record->value = rand() % 100; // random number within a specified range
        allocateNewOffset();
        atomic_store_explicit(&record->offset, &offsets[index], memory_order_relaxed);
        atomic_thread_fence(memory_order_release);
        records[index] = record;
    }

    // Process the record

    pthread_cond_signal(&cond);

    pthread_mutex_unlock(&mutex);
}
```

This code is a very high-level demonstration and doesn't cover all the points in your requirements. It only includes a basic structure for handling records, allocating new offsets/keys, validating freshness of the record, etc. You would need to expand on this function to handle more complex situations such as ensuring thread safety, optimizing memory access patterns, and managing cache usage.
