    Record *record;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 
Node* head = NULL;
int count = 0;
const int MAX_RECORDS = 65536; //max records limit
const int BATCH_SIZE = 1024; //records per batch
const int MAX_STRING_LEN = 1024; //max length of string

void* processDataFeed(void *arg) {
    pthread_mutex_lock(&lock); 

    if (count >= MAX_RECORDS) {
        printf("Max records limit reached!\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    Node* newNode = malloc(sizeof(Node)); 
    if (!newNode) {
        printf("Memory allocation error: %s\n", strerror(errno));
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Initialize record 
    Record* newRecord = malloc(sizeof(Record));
    if (!newRecord) {
        printf("Memory allocation error: %s\n", strerror(errno));
        free(newNode);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    newRecord->offset = ... //get offset value
    newRecord->key = ... //get key value
    newRecord->timestamp = time(NULL); 
    newRecord->buffer = malloc(MAX_STRING_LEN); 
    if (!newRecord->buffer) {
        printf("Memory allocation error: %s\n", strerror(errno));
        free(newNode);
        free(newRecord);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    sprintf(newRecord->buffer, "%d", newRecord->key); 
    if (strlen(newRecord->buffer) > MAX_STRING_LEN - 1) {
        printf("String representation exceeds maximum length!\n");
        free(newNode);
        free(newRecord->buffer);
        free(newRecord);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    newNode->record = newRecord; 
    newNode->next = head; 
    head = newNode; 
    count++; 

    // Garbage collection strategy 
    if (count % BATCH_SIZE == 0) {
        Node* temp;
        while(head != NULL) {
            temp = head;
            head = head->next;

            free(temp->record->buffer);
            free(temp->record);
            free(temp);
        }

        count = 0; 
    }

    pthread_mutex_unlock(&lock); 
    return NULL;
}
