            item->value = "";
        }

        *bundle = realloc(*bundle, (size + 1) * sizeof(Item));
        if (*bundle == NULL) {
            perror("Failed to resize bundle\n");
            return -1;
        }
        (*bundle)[size] = *item;
        size++;
    }

    fclose(file);
    return size;
}
