    long timestamp;
    double amount;
    char description[20];
} Transaction;

typedef struct Account {
    char* identifier;
    Transaction** transactions;
    size_t transactionCount;
    pthread_mutex_t lock;
} Account;

Account** accounts = NULL;
size_t accountCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addTransaction(char* identifier, Transaction* transaction) {
    pthread_mutex_lock(&lock);

    Account* account = NULL;

    for (size_t i = 0; i < accountCount; ++i) {
        if (strcmp(accounts[i]->identifier, identifier) == 0) {
            account = accounts[i];
            break;
        }
    }

    if (!account) {
        account = calloc(1, sizeof(Account));

        if (!account) {
            perror("Failed to allocate memory for new account");
            pthread_mutex_unlock(&lock);
            return;
        }

        account->identifier = strdup(identifier);

        if (!account->identifier) {
            free(account);
            perror("Failed to allocate memory for identifier");
            pthread_mutex_unlock(&lock);
            return;
        }

        accounts = realloc(accounts, (accountCount + 1) * sizeof(Account*));

        if (!accounts) {
            free(account->identifier);
            free(account);
            perror("Failed to resize account list");
            pthread_mutex_unlock(&lock);
            return;
        }

        accounts[accountCount++] = account;
    }

    pthread_mutex_unlock(&lock);

    pthread_mutex_lock(&account->lock);

    account->transactions = realloc(account->transactions, (account->transactionCount + 1) * sizeof(Transaction*));

    if (!account->transactions) {
        perror("Failed to resize transaction list");
        pthread_mutex_unlock(&account->lock);
        return;
    }

    account->transactions[account->transactionCount++] = transaction;

    pthread_mutex_unlock(&account->lock);
}

