import java.io.*;
import java.security.*;
import java.util.*;
import javax.xml.bind.DatatypeConverter;

public class HashingService {
    private static final int MAX_LENGTH = 2048; // 2KB
    private ExternalHashingService externalService = new ExternalHashingService();
    private Map<String, String> cache = new HashMap<>();
    private Configuration config = Configuration.getInstance();

    public synchronized String hash(String input) throws Exception {
        if (input == null || input.length() > MAX_LENGTH) {
            return externalService.hash(input);
        }

        String cachedHash = cache.get(input);
        if (cachedHash != null) {
            return cachedHash;
        } else {
            long startTime = System.nanoTime();
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes("UTF-8"));
            String hash = DatatypeConverter.printHexBinary(digest);
            cache.put(input, hash);

            long endTime = System.nanoTime();
            System.out.println("Hash computation took " + (endTime - startTime) + " nanoseconds.");

            return hash;
        }
    }

    public void monitorService() {
        int queueLength = externalService.getQueueLength();
        long responseTime = externalService.getResponseTime();

        if (queueLength > config.getMaxConcurrentRequests()) {
            System.out.println("WARNING: Hashing service queue is overloaded!");
        } else if (responseTime > config.getResponseTimeAlertThreshold()) {
            System.out.println("WARNING: Hashing service response time too high!");
        }
    }

    public static void main(String[] args) throws Exception {
        HashingService service = new HashingService();

        long startTime = System.nanoTime();
        String hash = service.hash("some input string");
        long endTime = System.nanoTime();

        System.out.println("Hash: " + hash);
        System.out.println("Total processing time took " + (endTime - startTime) + " nanoseconds.");
    }
}
