['Here's the C code for `allocateAndPopulateRecords` function considering above constraints. This is simplified version of what you described in task as your question was quite extensive. The full implementation would be lengthy, hence I have to make certain assumptions and omissions to simplify it. 

Please note that this is a basic example and not fully adheres to best practices for error handling, memory management etc. You'd likely want to expand on this to fit your actual needs.

```c
#include <stdlib.h>
#include <time.h>
#include <assert.h>
#include <string.h>
#include <sqlite3.h>

typedef struct {
    int* key;
    int* value;
} Record;

void allocateAndPopulateRecords(long num_offsets, 
                                long num_keys, 
                                int min_value, 
                                int max_value, 
                                sqlite3* connection, 
                                const char* command) {
    srand((unsigned int)time(NULL));

    if (num_offsets <= 0 || num_keys <= 0) {
        // Error case
        printf("Error: Invalid input values\n");
        return;
    }

    long* offsets = malloc(sizeof(*offsets) * num_offsets);
    if (offsets == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    int* keys = malloc(sizeof(*keys) * num_keys);
    if (keys == NULL) {
        free(offsets);
        printf("Memory allocation failed.\n");
        return;
    }

    Record* records = malloc(sizeof(*records) * num_keys);
    if (records == NULL) {
        free(offsets);
        free(keys);
        printf("Memory allocation failed.\n");
        return;
    }

    // Populate key array with unique keys, ascending order.
    for (int i = 0; i < num_keys; ++i) {
        keys[i] = i + 1;
    }

    // Populate records 
    for (long i = 0; i < num_keys; ++i) {
        records[i].key = &keys[i];
        int randomValue = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = malloc(sizeof(*records[i].value));
        if (records[i].value == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }

        *records[i].value = randomValue;
    }

    // Construct SQL command
    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(connection, command, -1, &stmt, NULL) != SQLITE_OK) {
        printf("Error: Failed to prepare SQL statement.\n");
        return;
    }

    // Execute SQL command
    if (sqlite3_step(stmt) != SQLITE_DONE) {
        printf("Failed to execute SQL statement.\n");
    } else {
        printf("SQL command executed successfully.\n");
    }

    sqlite3_finalize(stmt);

    // Free memory
    free(offsets);
    free(keys);
    for (long i = 0; i < num_keys; ++i) {
        free(records[i].value);
    }
    free(records);
}
```

Please note that you need to install and link `sqlite3` library. The code is written in C, which might not be the best fit for your application due to lack of support for higher-level constructs like classes or exceptions, but it should work as expected. 

You may also want to consider using a more modern language with better memory management and exception handling features such as C++ or even Rust if you are developing a high performance system.
']

