Record** initializeRecords(long* offsetValues, int numOffsets, int rangeStart, int rangeEnd) {
    // Initialize a hash table for tracking unique random values
    int usedValues[rangeEnd - rangeStart + 1] = {0}; 

    Record **records = malloc(sizeof(Record*) * numOffsets);
    if (records == NULL) return NULL;

    // Iterate over offset values and allocate memory for records
    for (int i = 0; i < numOffsets; ++i) {
        long offset = offsetValues[i];
