            printf("Invalid offset value %ld\n", offset);
            continue;
        } 

        Record *record = malloc(sizeof(Record));
        if (record == NULL) return NULL;

        // Generate a unique random value for each record
        do {
            record->value = rand() % rangeEnd + rangeStart;
        } while (usedValues[record->value - rangeStart]);

        usedValues[record->value - rangeStart] = 1;

        records[i] = record;
    }

    return records;
}

