    int total = 0, filtered = 0, memoryUsed = 0;

    for (int i = 0; i < num_records; ++i) {
        Record *record = malloc(sizeof(*record));

        if (!record) { // handle allocation failure gracefully
            printf("Memory allocation failed.\n");
            exit(1); 
        }

        record->offset = i;
        record->key = rand() % (max_key - min_key + 1) + min_key;
        if(record->key < min_key || record->key > max_key) {
            filtered++;
            continue;
        }

        record->timestamp = time(NULL); // set timestamp to current time in seconds since epoch
        memoryUsed += sizeof(*record);
        total++;
    }

    if (logging == 1){ 
        printf("Total records processed: %d\n", num_records);
        printf("Records filtered out due to key value constraints: %d\n", filtered);
        printf("Total memory used in bytes: %d\n", memoryUsed);
    }
}
