using System.Security.Cryptography;
using System.Text;

public static string CalculateMD5Hash(string input) {
    if (input == null) return null;  // Return NULL in case of invalid input

    StringBuilder hash = new StringBuilder();
    MD5CryptoServiceProvider md5provider = new MD5CryptoServiceProvider();
    byte[] bytes = md5provider.ComputeHash(new UTF8Encoding().GetBytes(input));

    for (int i = 0; i < bytes.Length; i++) {
        hash.Append(bytes[i].ToString("x2"));  // Convert to hexadecimal string
    }

    return hash.ToString();
}
```
**Python Class with Factory Pattern**
```python
import json
from abc import ABC, abstractmethod

class JSONFactory:
    subclasses = {}

    @classmethod
    def register_subclass(cls, id):
        def decorator(subclass):
            cls.subclasses[id] = subclass
            return subclass
        return decorator

    @classmethod
    def create(cls, id, *args, **kwargs):
        if id in cls.subclasses:
            return cls.subclasses[id](*args, **kwargs)
        else:
            raise ValueError('Bad id {}'.format(id))

class JSONObject(ABC):  # Abstract Base Class
    @abstractmethod
    def to_json(self):
        pass

@JSONFactory.register_subclass('my_type')
class MyType(JSONObject):
    def __init__(self, value):
        self.value = value

    def to_json(self):
        return json.dumps({'type': 'my_type', 'data': self.value})
