void* initialize_data(size_t num_offsets, int min_value, int max_value) {
    if (num_offsets == 0) {
        log_function("Error: No offsets provided");
        return NULL;
    }

    size_t total_size = sizeof(long)*num_offsets + sizeof(int)*num_offsets + sizeof(record_t)*num_offsets;
    data_structures_t* data = mmap(NULL, total_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (data == MAP_FAILED) {
        log_function("Error: Memory allocation failed");
        return NULL;
    }

    // Initialize memory in a thread-safe manner.
    pthread_mutex_lock(&lock);

    data->offsets = (long*)data;
    data->keys = (int*)(data->offsets + num_offsets);
    data->records = (record_t*)(data->keys + num_offsets);

    srand(rand_seed);  // Initialize the random number generator.

    for (size_t i = 0; i < num_offsets; ++i) {
