int* read_input(size_t *length) {
    int i = 0;
    int value;
    size_t capacity = 1024;  // initial allocation size
    int* data = malloc(capacity * sizeof(int));
    if (data == NULL) {
        printf("Memory allocation error\n");
        exit(EXIT_FAILURE);
    }

    while (scanf("%d", &value) == 1) {
        if (i >= capacity - 1) {  // prevent overflow
            capacity *= 2;
            data = realloc(data, capacity * sizeof(int));
            if (data == NULL) {
                printf("Memory allocation error\n");
                exit(EXIT_FAILURE);
            }
        }

        // prevent excessively large numbers causing performance issues or memory constraints
        if (value > INT_MAX / 1024) {
            printf("Input value is too large, it will cause an integer overflow. Skipping this value.\n");
            continue;
        }

        data[i++] = value;
    }

    *length = i;
    return data;
}

