    if (array == NULL || length == 0) {
        printf("Invalid input\n");
        exit(EXIT_FAILURE);
    }

    int max = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }

    return max;
