Record* generate_records(int num, int minKey, int maxKey) {
    // Allocate memory for all records in one go
    Record* records = (Record*)malloc(num * sizeof(Record));

    for(int i = 0; i < num; i++) {
        // Generate random key between min and max range
        int key = rand() % (maxKey - minKey + 1) + minKey;

        if(key <= 0 || key > 1024) {
            fprintf(stderr, "Invalid key value: %d\n", key);
