        // Generate current time stamp in seconds since the epoch
        double timestamp = (double)time(NULL);

        // Allocate memory for buffer based on key size
        char* buffer = (char*)malloc(key * sizeof(char));

        records[i] = (Record){i, key, timestamp, buffer};
    }

    return records;
}
```
