        log[i].status_flag = rand() % 2 == 0 ? 'T' : 'F';  // Random status flag.

        log[i].message = (char*) malloc(msg_length + 1);  // Allocate memory for message string.
        if (log[i].message == NULL) {
            while(--i >= 0) free(log[i].message);  // Free previously allocated memory.
            free(log);  // Also free log itself.
