void manage_memory(size_t num_offsets, size_t num_keys, unsigned int *seed) {
    offset_t* offsets = malloc(num_offsets * sizeof(offset_t));
    key_t* keys = calloc(num_keys, sizeof(key_t));
    record_t* records = malloc(num_keys * sizeof(record_t));
    log_entry_t* logs = malloc(num_keys * sizeof(log_entry_t));

    if (offsets == NULL || keys == NULL || records == NULL || logs == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        goto cleanup;
    }

    srand(*seed);
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = 2 * i - 5;
    }

    for (size_t i = 0, prime = 101; i < num_keys; ) {
        bool isPrime = true;
        for (size_t j = 2; j*j <= prime; ++j) {
            if (prime % j == 0) {
                isPrime = false;
                break;
            }
        }

        if (isPrime) {
            keys[i] = prime;
            ++i;
        }

        ++prime;
    }

    for (size_t i = 0; i < num_keys; ++i) {
        records[i].key = keys[i];
        records[i].value = rand_r(seed) % 201 - 100;
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        pthread_mutex_lock(&lock);
        records[i].value *= offsets[i];
        pthread_mutex_unlock(&lock);

        logs[i].timestamp = time(NULL);
        logs[i].status = rand_r(seed) % 2;
        logs[i].message = malloc(10 * sizeof(char)); // assuming fixed string length of 10 characters
        if (logs[i].message == NULL) {
            fprintf(stderr, "Memory allocation failed!\n");
            goto cleanup;
        }

        sprintf(logs[i].message, "%lu", logs[i].timestamp); // convert timestamp to string
    }

cleanup:
    free(offsets);
    free(keys);
    free(records);
    for (size_t i = 0; i < num_logs; ++i) {
        free(logs[i].message);
    }
    free(logs);
}
```
