```c
#include <stdio.h>
#include <pthread.h>
#include <stdatomic.h>
#include <errno.h>
#include <unistd.h>

#define MAX_BUFFER_SIZE 1024

typedef struct {
    char key[64];
    time_t timestamp;
    double value;
} DataItem;

typedef struct {
    DataItem data[MAX_BUFFER_SIZE];
    _Atomic size_t start, end;
} CircularBuffer;

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    CircularBuffer buffer;
    int isRunning;
    int numWorkers;
    pthread_t *workers;
} Engine;

int engineInit(Engine* e, int maxSources) {
    if (maxSources > MAX_BUFFER_SIZE) {
        fprintf(stderr, "Maximum number of sources exceeded. Consider increasing buffer size.\n");
        return -1;
    }

    pthread_mutex_init(&e->mutex, NULL);
    pthread_cond_init(&e->cond, NULL);

    e->buffer.start = ATOMIC_VAR_INIT(0);
    e->buffer.end = ATOMIC_VAR_INIT(0);

    e->isRunning = 1;
    e->numWorkers = maxSources;
    e->workers = malloc(sizeof(*e->workers) * e->numWorkers);

    for (int i = 0; i < e->numWorkers; ++i) {
        pthread_create(&e->workers[i], NULL, processData, e);
    }

    return 0;
}

void engineAdd(Engine* e, DataItem item) {
    size_t end = atomic_load(&e->buffer.end);
    e->buffer.data[end % MAX_BUFFER_SIZE] = item;
    atomic_store(&e->buffer.end, (end + 1) % MAX_BUFFER_SIZE);

    pthread_cond_signal(&e->cond);
}

void* processData(void *arg) {
    Engine *e = arg;
    DataItem item;
    while (e->isRunning) {
        pthread_mutex_lock(&e->mutex);

        while (atomic_load(&e->buffer.start) == atomic_load(&e->buffer.end)) {
            pthread_cond_wait(&e->cond, &e->mutex);
        }

        item = e->buffer.data[e->buffer.start % MAX_BUFFER_SIZE];
        atomic_fetch_add(&e->buffer.start, 1);

        pthread_mutex_unlock(&e->mutex);

        // Process the data item...
    }

    return NULL;
}

void engineDestroy(Engine* e) {
    e->isRunning = 0;

    for (int i = 0; i < e->numWorkers; ++i) {
        pthread_cond_signal(&e->cond);  // Wake up all workers to finish processing data.
    }

    for (int i = 0; i < e->numWorkers; ++i) {
        pthread_join(e->workers[i], NULL);  // Wait until all threads are finished.
    }

    free(e->workers);
    pthread_mutex_destroy(&e->mutex);
    pthread_cond_destroy(&e->cond);
}
```
The `engineInit` function initializes the engine and starts worker threads. The `engineAdd` function adds a data item to the buffer, which will be processed by one of the worker threads. The `processData` function is run by each worker thread and processes incoming data items until the engine is destroyed. Finally, `engineDestroy` stops all workers and releases resources.
']

