typedef struct Transaction {
    long transaction_id;
    double amount;
    char* description;
    timestamp_t timestamp;
} Transaction;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // used for thread safety
int total_transactions = 0;
double transaction_sum = 0.0;

void* handleErrors(void *ptr) {
    if (ptr == NULL) {
        fprintf(stderr, "Out of memory error\n");
        exit(EXIT_FAILURE);
    }
}

Transaction* initializeTransactions() {
    Transaction* transactions = malloc(sizeof(Transaction));  // initial allocation
    handleErrors(transactions);

    return transactions;
}

void resizeArray(Transaction** array, int new_size) {
    *array = realloc(*array, sizeof(Transaction) * new_size);
    handleErrors(array);
}

long generateUniqueId(double amount, char* description, timestamp_t timestamp) {
    long hash = 5381;
    int c;

    while ((c = *description++)) {
        hash = ((hash << 5) + hash) + c; // hash function djb2
    }

    return (long)(amount * 100.0) ^ timestamp ^ hash;  // combining input values with a hashed description for unique id
}

void addTransaction(Transaction* transactions, double amount, char* description) {
    pthread_mutex_lock(&lock);   // locking for thread safety

    if (total_transactions % 10 == 0 && total_transactions != 0) {  // check if resize needed
        resizeArray(&transactions, total_transactions + 10);  // add 10 extra spaces when resizing array
    }

    transactions[total_transactions].amount = amount;
    transactions[total_transactions].description = malloc(strlen(description) + 1);
    strcpy(transactions[total_transactions].description, description);
    handleErrors(transactions[total_transactions].description);

    timestamp_t now = time(NULL);  // get current local time
    transactions[total_transactions].timestamp = now;

    long uniqueId = generateUniqueId(amount, description, now);
    transactions[total_transactions].transaction_id = uniqueId;

    transaction_sum += amount;   // update total sum of amounts
    total_transactions++;  // increment the count of transactions

    pthread_mutex_unlock(&lock);  // unlock after operations done
}

void printTransactionSum() {
    printf("Total Transaction Sum: %f\n", transaction_sum);
}
```
