```c
#include <pthread.h>
#include <stdbool.h>
#include <time.h>
#include <stdio.h>

typedef struct Task {
    char id;
    time_t scheduled_time;
    bool is_running;
    void *data;
} Task;

Task tasks[MAX_TASKS];  // assuming MAX_TASKS is a defined constant
int task_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_task(char id, time_t scheduled_time, bool is_running, void *data) {
    pthread_mutex_lock(&lock);

    if (task_count >= MAX_TASKS) {
        printf("Maximum number of tasks reached!\n");
        return;
    }

    Task new_task = { .id = id, .scheduled_time = scheduled_time, .is_running = is_running, .data = data };
    tasks[task_count++] = new_task;

    pthread_mutex_unlock(&lock);
}

void update_task(char id, time_t scheduled_time, bool is_running, void *data) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < task_count; i++) {
        if (tasks[i].id == id) {
            tasks[i].scheduled_time = scheduled_time;
            tasks[i].is_running = is_running;
            tasks[i].data = data;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void remove_task(char id) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < task_count; i++) {
        if (tasks[i].id == id) {
            tasks[i] = tasks[--task_count];  // replace with the last task and decrement count
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}
```
In a real-world scenario, you would also need to implement serialization/deserialization functions that handle errors. For logging tasks addition/update/removal, you could use simple printf statements or more sophisticated logging libraries, and for ensuring thread safety, you might consider using higher level constructs like mutexes, condition variables, etc., in pthreads.
