const fs = require('fs/promises');
const path = require('path');
const crypto = require('crypto');

async function processDirectoryContent(directoryPath, randomStringLength = 16, inputToHash = '', algorithm = 'sha256') {
    const files = await fs.readdir(directoryPath);

    let integratedOutput = '';
    for (let file of files) {
        const content = await fs.readFile(path.join(directoryPath, file), 'utf8');

        // Customizable transformations on content can go here. For example:
        const uppercasedContent = content.toUpperCase();
        integratedOutput += uppercasedContent;
    }

    const randomString = crypto.randomBytes(Math.ceil(randomStringLength / 2)).toString('hex').slice(0, randomStringLength);

    // Create a hash object using the provided algorithm
    let hashedInput = '';
    if (inputToHash) {
        const hash = crypto.createHash(algorithm);
        hash.update(inputToHash);
        hashedInput = hash.digest('hex');
    }

    return { integratedOutput, randomString, hashedInput };
}
```

