#include <time.h>

typedef struct record {
    int value;
    time_t timestamp;
    size_t refcount;
} Record;

Record** initialize(size_t count, int min, int max) {
    // Allocate memory for arrays
    long* offsets = malloc(count * sizeof(long));
    if (offsets == NULL) return NULL; // Handle allocation failure

    int* keys = malloc(count * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        return NULL; // Handle allocation failure
    }

    Record** records = malloc(count * sizeof(Record*));
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL; // Handle allocation failure
    }

    pthread_mutex_t locks[count];
    for (size_t i = 0; i < count; i++) {
        if (pthread_mutex_init(&locks[i], NULL) != 0) {
            // Handle lock initialization failure
        }

        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) {
            for (size_t j = 0; j < i; j++) pthread_mutex_destroy(&locks[j]);
            free(offsets);
            free(keys);
            return NULL; // Handle allocation failure
        }

        records[i]->timestamp = time(NULL);
        records[i]->refcount = 0;
    }

    srand(time(NULL)); 

    for (size_t i = 0; i < count; i++) {
        pthread_mutex_lock(&locks[i]); // Acquire lock

        int value = min + rand() % ((max + 1) - min);
        records[i]->value = value;

        pthread_mutex_unlock(&locks[i]); // Release lock
    }

    return records;
}
```
