} event;

typedef struct {
    event** events;
    size_t capacity;
    atomic_size_t size;
    pthread_rwlock_t lock;
} EventCollection;

EventCollection* createEventCollection() {
    EventCollection* collection = malloc(sizeof(EventCollection));
    collection->capacity = 1024;
    collection->events = calloc(collection->capacity, sizeof(event*));
    atomic_init(&collection->size, 0);
    pthread_rwlock_init(&collection->lock, NULL);
    return collection;
}

void destroyEventCollection(EventCollection* collection) {
    for (size_t i = 0; i < collection->capacity; ++i) {
        if (collection->events[i] != NULL) {
            free(collection->events[i]->description);
            free(collection->events[i]);
        }
    }
    free(collection->events);
    pthread_rwlock_destroy(&collection->lock);
    free(collection);
}

void insertEvent(EventCollection* collection, event* newEvent) {
    size_t index = atomic_fetch_add(&collection->size, 1);
    if (index >= collection->capacity) {
        // Grow the array. This is a simplistic approach; in practice you might want to implement a more efficient strategy like doubling the capacity each time it's exceeded.
        size_t newCapacity = collection->capacity * 2;
        event** newEvents = calloc(newCapacity, sizeof(event*));
        memcpy(newEvents, collection->events, collection->capacity * sizeof(event*));
        free(collection->events);
        collection->events = newEvents;
        collection->capacity = newCapacity;
    }
    pthread_rwlock_wrlock(&collection->lock);
    collection->events[index] = newEvent;
    pthread_rwlock_unlock(&collection->lock);
}

event* getEvent(EventCollection* collection, int id) {
    for (size_t i = 0; i < atomic_load(&collection->size); ++i) {
        if (collection->events[i] != NULL && collection->events[i]->id == id) {
            return collection->events[i];
        }
    }
    return NULL;
}

void deleteEvent(EventCollection* collection, int id) {
    pthread_rwlock_wrlock(&collection->lock);
    for (size_t i = 0; i < atomic_load(&collection->size); ++i) {
        if (collection->events[i] != NULL && collection->events[i]->id == id) {
            free(collection->events[i]->description);
            free(collection->events[i]);
            collection->events[i] = NULL;
            atomic_fetch_sub(&collection->size, 1);
            break;
        }
    }
    pthread_rwlock_unlock(&collection->lock);
}

void updateEvent(EventCollection* collection, int id, char* newDescription) {
    for (size_t i = 0; i < atomic_load(&collection->size); ++i) {
        if (collection->events[i] != NULL && collection->events[i]->id == id) {
