int hash(int key, int size) {
    return key % size;
}

Record **initializeRecords(int num_records) {
    Record **table = (Record**)malloc(num_records*sizeof(Record*));

    for (int i = 0; i < num_records; ++i) {
        table[i] = NULL;
    }

    return table;
}

void insertRecord(Record **table, int key, Record *record, int size) {
    int index = hash(key, size);
    record->next = table[index];
    table[index] = record;
}

bool checkDuplicateKeys(long* offsets, int* keys, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        for (int j = i + 1; j < num_records; ++j) {
            if (keys[i] == keys[j]) {
                printf("Error: Duplicate key detected!\n");
                free(offsets);
                free(keys);
                exit(EXIT_FAILURE);
            }
        }
    }

    return false;
}

