["Here is the basic outline of how you might implement such a system in C. Please note that this code is just an example for illustration and should be refined to better fit the specific needs of your project. Also, please consider using standard libraries or frameworks whenever possible.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define a record structure
typedef struct Record {
    int key;
    long offset;
    int valid; // Boolean field to indicate validity
    struct Record *next;
} Record;

// Define the hash table
Record **table;
int capacity = 1000; // Initial capacity
float load_factor = 0.7; // Load factor threshold for resizing
int count = 0; // Number of records in the table
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Lock for thread-safe access

// Hash function using a simple modulo operation
unsigned int hash(int key) {
    return key % capacity;
}

// Resize the table to maintain efficient lookup operations
void resize() {
    pthread_mutex_lock(&lock); // Lock before resizing

    // Save current table and its size
    Record **oldTable = table;
    int oldCapacity = capacity;

    // Double the capacity
    capacity *= 2;
    count = 0; // Reset the record counter

    // Allocate memory for the new table
    table = (Record **) malloc(capacity * sizeof(Record *));

    // Initialize all elements in the new table to NULL
    for (int i = 0; i < capacity; ++i) {
        table[i] = NULL;
    }

    // Rehash and reinsert old records into the new table
    for (int i = 0; i < oldCapacity; ++i) {
        Record *record = oldTable[i];
        while(record != NULL) {
            insertRecord(record->key, record->offset); // Insert each record into the new table
            Record *temp = record; 
            record = record->next;
            free(temp); // Free memory of old records
        }
    }

    free(oldTable); // Free memory of the old table

    pthread_mutex_unlock(&lock); // Unlock after resizing
}

// Insert a record into the hash table
void insertRecord(int key, long offset) {
    Record *record = (Record *) malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    record->valid = 1;

    // Calculate the hash value and insert into the table
    unsigned int index = hash(key);
    record->next = table[index];
    table[index] = record;

    count++;

    // Check if resizing is necessary
    if (count > capacity * load_factor) {
        resize();
    }
}

// Search for a record by key, return NULL if not found
Record *searchRecord(int key) {
    pthread_mutex_lock(&lock); // Lock before searching

    unsigned int index = hash(key);
    Record *record = table[index];

    while (record != NULL) {
        if (record->key == key && record->valid) {
            pthread_mutex_unlock(&lock); // Unlock after found
            return record;
        }
        record = record->next;
    }

    pthread_mutex_unlock(&lock); // Unlock after not found
    return NULL;
}

// Serialize the table to a file
void serialize(FILE *file) {
    pthread_mutex_lock(&lock); // Lock before serializing

    fwrite(&count, sizeof(int), 1, file); // Write the count of records

    for (int i = 0; i < capacity; ++i) {
        Record *record = table[i];
        while (record != NULL) {
            if (record->valid) { // Only serialize valid records
                fwrite(&(record->key), sizeof(int), 1, file);
                fwrite(&(record->offset), sizeof(long), 1, file);
            }
            record = record->next;
        }
    }

    pthread_mutex_unlock(&lock); // Unlock after serializing
}

// Deserialize the table from a file
void deserialize(FILE *file) {
    pthread_mutex_lock(&lock); // Lock before deserializing

    int total;
    fread(&total, sizeof(int), 1, file); // Read the count of records

    for (int i = 0; i < total; ++i) {
        int key;
        long offset;

        fread(&key, sizeof(int), 1, file);
        fread(&offset, sizeof(long), 1, file);

        insertRecord(key, offset); // Insert each record into the table
    }

    pthread_mutex_unlock(&lock); // Unlock after deserializing
}
```
Note: This is a simple implementation and doesn't cover all possible cases or edge conditions. It should be extended to meet your specific requirements, such as handling errors and concurrency control. Also, you may need to adapt the code according to your project needs or programming environment, and make sure it meets your performance requirements in real-world scenarios.
"]

