["Here is a simplified implementation of this task using C language with POSIX threads to ensure thread safety. I will not use a logging service as it's not provided by default in all systems or may require additional libraries such as syslog, zap etc. Also the error handling part is omitted for brevity.

```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct Session {
    char ip[16];
    time_t startTime;
    int status; // 0: inactive, 1: active, 2: terminated
} Session;

typedef struct SessionsManager {
    pthread_mutex_t lock;
    Session* sessions;
    size_t count;
    size_t capacity;
} SessionsManager;

void initSessions(SessionsManager* manager) {
    manager->sessions = malloc(sizeof(Session)*10); // Initial capacity of 10
    manager->count = 0;
    manager->capacity = 10;
}

void addSession(SessionsManager* manager, char ip[]) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) { // Reallocate more memory when full
        manager->sessions = realloc(manager->sessions, sizeof(Session)*manager->capacity*2);
        manager->capacity *= 2;
    }

    strcpy(manager->sessions[manager->count].ip, ip); // Store client IP
    manager->sessions[manager->count].startTime = time(NULL); // Record start time
    manager->sessions[manager->count].status = 1; // Initialize as active session
    ++manager->count;

    pthread_mutex_unlock(&manager->lock);
}

void removeInactiveSessions(SessionsManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if ((time(NULL) - manager->sessions[i].startTime) > 60*60 && // If session inactive for more than 1 hour
            manager->sessions[i].status != 2) { // And not terminated

            // Remove this session by swapping it with the last one and reducing count
            --manager->count;
            memcpy(&manager->sessions[i], &manager->sessions[manager->count], sizeof(Session));
        }
    }

    pthread_mutex_unlock(&manager->lock);
}
```

