void appendLogEntry(log_entries* logs, log_entry entry) {
    if (logs->size == logs->capacity) {
        size_t newCapacity = (logs->capacity == 0) ? 1 : logs->capacity * 2;
        log_entry* newEntries = realloc(logs->entries, newCapacity * sizeof(*newEntries));
        if (!newEntries) {
            // Handle memory allocation error here...
        }

        logs->entries = newEntries;
        logs->capacity = newCapacity;
    }

    logs->entries[logs->size++] = entry;
