```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double value;
} Record;

Record* records = NULL;
long* offsets = NULL;
int* keys = NULL;
size_t recordCount = 0;
size_t maxMemory = 1024 * 1024 * 500; // 500 MB
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
const long MAX_OFFSET = 100000000000L;
int errorCode = 0;
char* errorMessage = NULL;

void setError(int code, const char* message) {
    pthread_mutex_lock(&lock);
    if (errorCode == 0) {
        errorCode = code;
        if (errorMessage != NULL) {
            free(errorMessage);
        }
        errorMessage = strdup(message);
    }
    pthread_mutex_unlock(&lock);
}

void allocateMemory(size_t n, size_t m, size_t p) {
    if (n < 0 || m < 0 || p < 0) {
        setError(-1, "Negative array sizes are not allowed.");
        return;
    }

    // Calculate total memory needed and check against maxMemory limit
    size_t offsetsSize = n * sizeof(long);
    size_t keysSize = m * sizeof(int);
    size_t recordsSize = p * sizeof(Record);
    size_t totalSize = offsetsSize + keysSize + recordsSize;

    if (totalSize > maxMemory) {
        setError(-2, "Total memory needed exceeds the limit.");
        return;
    }

    // Allocate memory for arrays and structs
    offsets = malloc(offsetsSize);
    keys = malloc(keysSize);
    records = calloc(recordsSize, 1);
}

void populateRecords() {
    if (errorCode != 0) return;

    for (size_t i = 0; i < recordCount; ++i) {
        records[i].offset = random() % MAX_OFFSET; // generate a random offset within the limit

        int key;
        do {
            key = random();
        } while (!isKeyUnique(key));
        records[i].key = key;
    }
}

int isKeyUnique(int key) {
    for (size_t i = 0; i < recordCount; ++i) {
        if (records[i].key == key) return 0; // Key already exists
    }
    return 1; // Key is unique
}

void updateRecord(int index, double value) {
    if (index < 0 || index >= recordCount) {
        setError(-3, "Invalid record index.");
        return;
    }

    records[index].value = value;
}
```
