```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h> // For threads and locks

typedef struct Record {
    int id;
    char *str;
} Record;

// This is the linked list node for collision resolution
typedef struct Node {
    char *key;
    Record value;
    struct Node *next;
} Node;

typedef struct HashTable {
    size_t capacity;
    size_t size; // Current number of records
    Node **buckets; 
    pthread_mutex_t lock; // For concurrency control
} HashTable;

// A simple hash function, you might want to choose a better one according to your needs
size_t hash(char *key, size_t capacity) {
    size_t hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % capacity;
}

// Initialize the hashtable
HashTable* init_hashtable(size_t initialCapacity) {
    HashTable *table = malloc(sizeof(HashTable));

    if (!table)
        return NULL; // Failed to allocate memory

    table->capacity = initialCapacity;
    table->buckets = calloc(initialCapacity, sizeof(Node*));
    pthread_mutex_init(&(table->lock), NULL);

    if (!table->buckets) {
        free(table); // Failed to allocate memory for buckets
        return NULL;
    }

    return table;
}
``` 
This is just the start and you would need more functions to handle adding, updating, retrieving records, resizing hash tables, handling collisions, serialization/deserialization, thread safety etc. Also please note that error checking has been kept minimal for brevity but should be added according to your requirements.
