#define LOG_ENTRY_BUFFER 1024
#define DESCRIPTION_LENGTH 512
typedef struct {
    time_t timestamp;
    int eventID;
    char* description;
} log_entry;

log_entry* initializeLogEntries(int bufferSize, const char* messageTemplate) {
    log_entry* entries = (log_entry*) malloc(sizeof(log_entry) * bufferSize);
    if (entries == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < bufferSize; i++) {
        entries[i].timestamp = time(NULL);
        entries[i].eventID = i;

        char* description = malloc(sizeof(char)* DESCRIPTION_LENGTH);
        if (description == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        sprintf(description, messageTemplate, i);
        entries[i].description = description;
    }

    return entries;
}

void serializeToJSON(log_entry* entries, int bufferSize) {
    json_t *array = json_array();
    for (int i = 0; i < bufferSize; i++) {
        json_t *object = json_object();

        // Populate object with entry data.
        json_object_set(object, "timestamp", json_string(ctime(&entries[i].timestamp)));
        json_object_set(object, "eventID", json_integer(entries[i].eventID));
        json_object_set(object, "description", json_string(entries[i].description));

        // Add object to array.
        json_array_append(array, object);
    }

    // Print out JSON string.
    char *jsonString = json_dumps(array, JSON_COMPACT | JSON_INDENT(4));
    printf("%s\n", jsonString);

    free(jsonString);
    json_decref(array);
}

void* asyncProcessing(void* arg) {
    log_entry* entries = initializeLogEntries(LOG_ENTRY_BUFFER, "Event number %d has occurred");
    serializeToJSON(entries, LOG_ENTRY_BUFFER);

    // Free dynamically allocated memory.
    for (int i = 0; i < LOG_ENTRY_BUFFER; i++) {
        free(entries[i].description);
    }
    free(entries);
}
```
