typedef struct {
    char *key;
    int value;
} config_setting;

config_setting* settings = NULL;
int num_settings = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void append(char* key, int value) {
    pthread_mutex_lock(&lock);

    settings = realloc(settings, (num_settings + 1) * sizeof(*settings));
    if (!settings) {
        perror("realloc failed");
        exit(-1);
    }

    settings[num_settings].key = strdup(key);
    if (!settings[num_settings].key) {
        perror("strdup failed");
        exit(-1);
    }

    settings[num_settings].value = value;
    ++num_settings;

    pthread_mutex_unlock(&lock);
}

config_setting* get(const char* key) {
    for (int i = 0; i < num_settings; ++i) {
        if (strcmp(key, settings[i].key) == 0) {
            return &settings[i];
        }
    }

    return NULL;
}
```
