typedef struct Record {
    long offset;
    int key;
    double timestamp;
    char label[20];
    float weight;
    struct Record *next;
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Record *head = NULL;

// Insert a new record at the beginning of the list (Thread-safe)
void insert(int key, double timestamp, char label[], float weight) {
    Record *new_node = malloc(sizeof(Record));
    new_node->key = key;
    new_node->timestamp = timestamp;
    strcpy(new_node->label, label);
    new_node->weight = weight;

    pthread_mutex_lock(&lock);  // Acquire lock
    if (head == NULL) {
        head = new_node;
    } else {
        new_node->next = head;
        head = new_node;
    }
    pthread_mutex_unlock(&lock);  // Release lock
}

// Remove a record from the list (Thread-safe)
void delete(int key) {
    if (head == NULL) return;
    Record *temp = head;
    Record *prev = NULL;

    pthread_mutex_lock(&lock);  // Acquire lock
    if (temp != NULL && temp->key == key) {  // If the key is in the head node
        head = temp->next;
        free(temp);
        return;
    }

    while (temp != NULL && temp->key != key) {  // Search for the key to be deleted
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;  // If the key was not present in linked list
    prev->next = temp->next;  // Unlink the node from linked list
    free(temp);  // Free memory
    pthread_mutex_unlock(&lock);  // Release lock
}

