typedef struct {
    float volume;
    char* symbol;
} Transaction;

typedef struct {
    double* prices;
    char** symbols;
    Transaction** transactions;

    size_t priceCount;
    size_t symbolCount;
    size_t transactionCount;

    pthread_mutex_t lock; // for thread safety
} FinancialDataManager;

int initFinancialDataManager(FinancialDataManager* manager) {
    if(!manager ||
       pthread_mutex_init(&(manager->lock), NULL)) {
        return -1;
    }

    manager->prices = NULL;
    manager->symbols = NULL;
    manager->transactions = NULL;

    manager->priceCount = 0;
    manager->symbolCount = 0;
    manager->transactionCount = 0;

    return 0;
}

int addPrice(FinancialDataManager* manager, double price) {
    if(!manager || pthread_mutex_lock(&(manager->lock))) {
        return -1;
    }

    double* newPrices = realloc(manager->prices, sizeof(double) * (manager->priceCount + 1));
    if(!newPrices) {
        pthread_mutex_unlock(&(manager->lock));
        return -1;
    }

    manager->prices = newPrices;
    manager->prices[manager->priceCount++] = price;

    pthread_mutex_unlock(&(manager->lock));
    return 0;
}

int addSymbol(FinancialDataManager* manager, const char* symbol) {
    if(!manager || !symbol || pthread_mutex_lock(&(manager->lock))) {
        return -1;
    }

    char** newSymbols = realloc(manager->symbols, sizeof(char*) * (manager->symbolCount + 1));
    if(!newSymbols) {
        pthread_mutex_unlock(&(manager->lock));
        return -1;
    }

    newSymbols[manager->symbolCount] = malloc(strlen(symbol) + 1);
    if(!newSymbols[manager->symbolCount]) {
        pthread_mutex_unlock(&(manager->lock));
        return -1;
    }

    strcpy(newSymbols[manager->symbolCount++], symbol);
    manager->symbols = newSymbols;

    pthread_mutex_unlock(&(manager->lock));
    return 0;
}

int addTransaction(FinancialDataManager* manager, Transaction transaction) {
    if(!manager || pthread_mutex_lock(&(manager->lock))) {
        return -1;
    }

    Transaction** newTransactions = realloc(manager->transactions, sizeof(Transaction*) * (manager->transactionCount + 1));
    if(!newTransactions) {
        pthread_mutex_unlock(&(manager->lock));
        return -1;
    }

    newTransactions[manager->transactionCount] = malloc(sizeof(Transaction));
    if(!newTransactions[manager->transactionCount]) {
        pthread_mutex_unlock(&(manager->lock));
        return -1;
    }

    *(newTransactions[manager->transactionCount++]) = transaction;
    manager->transactions = newTransactions;

    pthread_mutex_unlock(&(manager->lock));
    return 0;
}

void freeFinancialDataManager(FinancialDataManager* manager) {
    if(!manager || pthread_mutex_lock(&(manager->lock))) {
        return;
    }

    for(size_t i = 0; i < manager->symbolCount; ++i) {
        free(manager->symbols[i]);
    }

    for(size_t i = 0; i < manager->transactionCount; ++i) {
        free(manager->transactions[i]);
    }

    pthread_mutex_unlock(&(manager->lock));

    if(manager->prices) {
        free(manager->prices);
    }

    if(manager->symbols) {
        free(manager->symbols);
    }

    if(manager->transactions) {
        free(manager->transactions);
    }

    pthread_mutex_destroy(&(manager->lock));
}
```
