    if (task == NULL) return NULL;  // Check malloc failure

    task->priority = priority;
    task->description = strdup(description);  // Allocate and copy description string
    task->timestamp = time(NULL);  // Get current timestamp

    return task;
}

void destroy_task(Task* task) {
