['Here's an example implementation in C. Please note that this code does not include the integration with an external logging service as it involves additional dependencies such as network operations which can affect performance significantly. It also doesn't handle concurrent event additions or data corruption and race conditions to avoid complexity. 

In a real-world application, you would need error handling for memory allocation failures, and logging of events through an external service should be done asynchronously using separate threads or processes. Also, the code does not include thread safety mechanisms like locks or atomic operations which are necessary in a multithreaded environment to avoid data corruption and race conditions:

```c
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <stdlib.h>

typedef struct {
    char* message;
    int event_type;
    time_t timestamp;
} Event;

typedef struct {
    size_t capacity;
    size_t count;
    Event *events;
} EventList;

EventList createEventList(size_t initialSize) {
    EventList list;

    list.capacity = initialSize;
    list.count = 0;
    list.events = malloc(initialSize * sizeof(Event));
    if (list.events == NULL && initialSize > 0) {
        fprintf(stderr, "Memory allocation error\n");
        exit(EXIT_FAILURE);
    }

    return list;
}

void addToList(EventList *list, Event event) {
    if (list->count == list->capacity) {
        // Double the capacity when we reach the limit
        list->capacity = list->capacity ? list->capacity*2 : 1;

        // Reallocate the memory with new capacity
        Event *newEvents = realloc(list->events, list->capacity * sizeof(Event));
        if (newEvents == NULL) {
            fprintf(stderr, "Memory allocation error\n");
            exit(EXIT_FAILURE);
        } else {
            list->events = newEvents;
        }
    }

    // Copy the event to the list and increment count
    memcpy(&list->events[list->count], &event, sizeof(Event));
    list->count++;
}

void printListInReverse(const EventList *list) {
    for (size_t i = list->count; i > 0; --i) {
        printf("Message: %s\n", list->events[i - 1].message);
        printf("Event Type: %d\n", list->events[i - 1].event_type);
        printf("Timestamp: %ld\n", (long)list->events[i - 1].timestamp);
    }
}

void destroyList(EventList *list) {
    free(list->events);
    list->capacity = 0;
    list->count = 0;
    list->events = NULL;
}
```
To use this code, you would first create an EventList using `createEventList`. You can then add events to the list with `addToList` and print all events in reverse order with `printListInReverse`. When you're done with the list, be sure to destroy it with `destroyList` to free up allocated memory.
']

