['Here's a simplified code sketch of how such a function might look like in C:

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Error handling mechanism
void error_exit(char *error) {
    // Logging and recovery from allocation failures
    fprintf(stderr, "%s: %s\n", error, strerror(errno));
    exit(EXIT_FAILURE);
}

typedef struct record {
    long offset;
    int key;
    double timestamp; // milliseconds since the epoch
} record_t;

// Dummy for external data source updates
void* updateDataSource(void *arg) {
    while (1) {
        sleep(30);  // Every 30 seconds, periodically prune outdated records
    }
    return NULL;
}

typedef struct node {
    record_t rec;
    struct node* next;
} node_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Thread-safety for shared resources
node_t* head = NULL;  // Start of the list
int recordsCount = 0;

record_t* allocateRecord(long offset, int key) {
    record_t *rec = malloc(sizeof(*rec));
    if (rec == NULL) error_exit("Failed to allocate memory for a new record");

    rec->offset = offset;
    rec->key = key;
    struct timespec ts;  // Current time in milliseconds since the epoch
    clock_gettime(CLOCK_REALTIME, &ts);
    rec->timestamp = (double)ts.tv_sec * 1000 + ts.tv_nsec / 1e6;
    return rec;
}

void freeRecordList() {
    pthread_mutex_lock(&lock); // Lock to prevent data race while modifying the list
    node_t* temp = head, *prev;

    while (temp != NULL) {
        prev = temp;
        temp = temp->next;
        free(prev);
    }

    head = NULL;
    recordsCount = 0;  // Reset count
    pthread_mutex_unlock(&lock);
}

void insertRecord(long offset, int key) {
    record_t *rec = allocateRecord(offset, key);

    pthread_mutex_lock(&lock);
    node_t* newNode = malloc(sizeof(*newNode));  // Allocating memory for the node
    if (newNode == NULL) error_exit("Failed to allocate memory for a new list node");

    newNode->rec = *rec;
    free(rec);
    newNode->next = head;
    head = newNode;  // Insert at the beginning of the list
    ++recordsCount;
    pthread_mutex_unlock(&lock);
}

record_t* findRecordByKey(int key) {
    pthread_mutex_lock(&lock);
    node_t *temp = head;

    while (temp != NULL) {
        if (temp->rec.key == key) {  // Search by key in the list
            record_t* foundRec = malloc(sizeof(*foundRec));
            if (foundRec == NULL) error_exit("Failed to allocate memory for a found record");
            *foundRec = temp->rec;
            pthread_mutex_unlock(&lock);
            return foundRec;
        }
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;  // Record not found in the list
}

void removeRecordByKey(int key) {
    pthread_mutex_lock(&lock);
    node_t *temp = head, *prev = NULL;

    while (temp != NULL && temp->rec.key != key) {  // Search for the record to delete
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) {
      pthread_mutex_unlock(&lock);
      return;
    }

    if (prev != NULL) {  // If the node to delete is not head
        prev->next = temp->next;
    } else {
        head = temp->next;
    }

    --recordsCount;
    free(temp);  // Free memory of deleted record
    pthread_mutex_unlock(&lock);
}
```
Please note that the code is a simplified version and for real usage, additional error handling mechanisms should be implemented as per requirements.
']

