public class ValueGeneratorManager<T> where T : IComparable {
    private Dictionary<string, Random> generators = new Dictionary<string, Random>();
    private object syncLock = new object();

    public void Initialize(params string[] generatorNames) {
        foreach (var name in generatorNames) {
            generators.Add(name, new Random());
        }
    }

    public T GenerateRandomValue(string generatorName, T min, T max) {
        lock (syncLock) {
            if (!generators.ContainsKey(generatorName)) throw new ArgumentException("Invalid generator.");

            var result = default(T);
            try {
                result = (T)Convert.ChangeType(generators[generatorName].NextDouble() * (dynamic)max, typeof(T));
                if (result < min) result += min;
            } catch (InvalidCastException ex) {
                throw new ArgumentException("Incompatible type.", ex);
            }

            return result;
        }
    }

    public void ResetGenerator(string generatorName) {
        if (!generators.ContainsKey(generatorName)) throw new ArgumentException("Invalid generator.");

        lock (syncLock) {
            generators[generatorName] = new Random();
        }
    }

    private bool IsValidRange(T min, T max) {
        return Comparer<T>.Default.Compare(min, max) < 0;
    }
}
