```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Point {
    double x;
    double y;
} Point;

typedef struct Measurement {
    double value;
    char* name;
    const Point* point;
} Measurement;

typedef struct MeasurementArray {
    pthread_mutex_t lock;
    int limit;
    int size;
    Measurement** measurements;
} MeasurementArray;

MeasurementArray* createMeasurementArray(int limit) {
    MeasurementArray* array = (MeasurementArray*) malloc(sizeof(MeasurementArray));
    if (!array) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->limit = limit;
    array->size = 0;
    array->measurements = (Measurement**) malloc(limit * sizeof(Measurement*));

    return array;
}

int addMeasurement(MeasurementArray* array, Measurement* measurement) {
    if (!array || !measurement || array->size >= array->limit) return -1;  // Error cases

    pthread_mutex_lock(&array->lock);
    if (array->size >= array->limit) return -2;  // Race condition check

    Measurement* newMeasurement = malloc(sizeof(Measurement));
    if (!newMeasurement) {
        pthread_mutex_unlock(&array->lock);
        return -3;  // Allocation failure
    }

    memcpy(newMeasurement, measurement, sizeof(Measurement));
    array->measurements[array->size++] = newMeasurement;

    pthread_mutex_unlock(&array->lock);
    return 0;  // Success
}
```
This code provides a basic starting point. It doesn't include any integration with an external logging library or configuration file, doesn't handle out-of-memory conditions, and doesn't integrate with the null pointer dereferences and buffer overflows. These are all significant considerations to take when designing such a solution.
