    int priority;
    char* message;
} Event;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int fd = 0;

char* generateRandomString(size_t length) {
    static char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *randomString = NULL;

    if (length) {
        randomString = malloc(length + 1);
        if (randomString) {
            for (size_t n = 0;n < length;n++) {
                int key = rand() % (int)(sizeof charset - 1);
                randomString[n] = charset[key];
            }
            randomString[length] = '\0';
        }
    }

    return randomString;
}

Event* createEvent(int minMsgLength, int maxMsgLength) {
    Event *newEvent = malloc(sizeof(Event));
    if (newEvent == NULL) {
        exit(EXIT_FAILURE); // Handle error properly in production code.
    }

    newEvent->timestamp = time(NULL);
    newEvent->priority = rand() % 10;

    int msgLength = (rand() % maxMsgLength) + minMsgLength;
    newEvent->message = generateRandomString(msgLength);

    return newEvent;
}

void logToFile(const Event* event, bool enableLogging) {
    if (!enableLogging) {
        return;
    }

    pthread_mutex_lock(&mutex);
    write(fd, event->message, strlen(event->message));
    pthread_mutex_unlock(&mutex);
}

void* generateEvents(void *arg) {
    srand(time(NULL)); // Initialize random seed.

    int numEvents = ((int*) arg)[0];
    int minMsgLength = ((int*) arg)[1];
    int maxMsgLength = ((int*) arg)[2];
    bool enableLogging = ((bool*) arg)[3];

    if (enableLogging) {
        fd = open("log.txt", O_WRONLY | O_CREAT, 0644); // Open log file in append mode.
        if (fd == -1) {
            exit(EXIT_FAILURE); // Handle error properly in production code.
        }
    }

    for(int i = 0; i < numEvents; ++i) {
        Event *event = createEvent(minMsgLength, maxMsgLength);

        logToFile(event, enableLogging);

        free(event->message);
        free(event);
    }

    if (enableLogging && close(fd) == -1) {
        exit(EXIT_FAILURE); // Handle error properly in production code.
    }
}
```
