typedef struct {
    char* message;
    unsigned char* key;
    unsigned char* iv;
} Config;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initRecord(Record *record, int numOfRecords) {
    srand(time(NULL));
    for (int i = 0; i < numOfRecords; i++) {
        record[i].offset = rand(); // Random offset value within range
        record[i].key = rand() % 100; // Random key value within a predefined range
        record[i].timestamp = (double)time(NULL); // Current time
    }
}

void decryptMessage(Config* config, unsigned char* output) {
    DES_cblock iv;
    memcpy(&iv, config->iv, 8);

    DES_key_schedule key_sched;
    DES_set_key((const_DES_cblock *)config->key, &key_sched); // Set the key for decryption

    unsigned char* ciphertext = (unsigned char*) malloc(strlen(config->message) * 3 / 4);
    int length = EVP_DecodeBlock(ciphertext, (const unsigned char*) config->message, strlen(config->message)); // Decode the Base64 encoded message

    DES_ede3_cfb64_encrypt((unsigned char*) ciphertext, output, length, &key_sched, &iv, DES_DECRYPT); // Triple DES decryption
}

void* manageRecords(void* args) {
    int numOfRecords = *((int*)args);
    Record* records = (Record*)malloc(numOfRecords * sizeof(Record));

    pthread_mutex_lock(&mutex); // Lock the mutex to ensure thread safety
    initRecord(records, numOfRecords);
    pthread_mutex_unlock(&mutex); // Unlock the mutex after initializing records

    return NULL;
}

int main() {
    int numOfRecords = 100; // Number of records to initialize

    // Initialize a config structure and set parameters
    Config* config = (Config*)malloc(sizeof(Config)); 
    config->message = "Base64EncodedMessage";
    config->key = "secretKey123";
    config->iv = "initializationVector";

    pthread_t thread;
    if (pthread_create(&thread, NULL, manageRecords, &numOfRecords)) { // Create a new thread to handle record initialization
        printf("Failed to create thread\n");
        return 1;
    }

    unsigned char* output = malloc(strlen(config->message) * 3 / 4);
    decryptMessage(config, output); // Decrypt the message

    pthread_join(thread, NULL); // Wait for the thread to finish before exiting

    free(output);
    free(config->key);
    free(config->iv);
    free(config);

    return 0;
}
