#include <time.h>
#include <pthread.h>

#define MAX_STRING_LENGTH 20

typedef struct {
    double value;
    char buffer[MAX_STRING_LENGTH + 1]; // +1 for null terminator
} Entry;

typedef struct {
    Entry* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray createDynamicArray() {
    DynamicArray arr = { NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER };
    return arr;
}

void addEntry(DynamicArray* arr) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->size == arr->capacity) { // if we need to resize the array
        size_t newCapacity = (arr->capacity == 0) ? 1 : arr->capacity * 2;

        Entry* newArray = realloc(arr->array, sizeof(*newArray) * newCapacity);
        if (newArray == NULL) { // handle allocation failure
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&arr->mutex);
            return;
        }

        arr->array = newArray;
        arr->capacity = newCapacity;
    }

    srand(time(NULL)); // initialize random seed 
    Entry newEntry;
    newEntry.value = 10.0 * ((double) rand() / RAND_MAX); // generate a random floating-point number between 0 and 10

    size_t stringLength = rand() % MAX_STRING_LENGTH + 1; // generate a random length for the string, from 1 to MAX_STRING_LENGTH
    for (size_t i = 0; i < stringLength; ++i) {
        newEntry.buffer[i] = 'a' + rand() % ('z' - 'a'); // fill buffer with random characters between a and z
    }
    newEntry.buffer[stringLength] = '\0'; // null-terminate the string

