```C
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} record;

typedef struct {
    size_t num_records;
    int min_key;
    int max_key;
    time_t min_timestamp;
    time_t max_timestamp;
    char* filepath;
} ConfigParams;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

record* generate_records(ConfigParams params) {
    record *records = malloc(params.num_records * sizeof(record));

    if (records == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        exit(-1);
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < params.num_records; ++i) {
        records[i].offset = i * sizeof(record);
        records[i].key = rand() % (params.max_key - params.min_key + 1) + params.min_key;

        time_t random_timestamp = rand();
        while (random_timestamp < params.min_timestamp || random_timestamp > params.max_timestamp) {
            random_timestamp = rand();
        }
        records[i].timestamp = (double)random_timestamp;
    }

    return records;
}

void write_to_disk(record* records, size_t num_records, char* filepath) {
    pthread_mutex_lock(&lock);

    FILE *file = fopen(filepath, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file %s\n", filepath);
        exit(-1);
    }

    size_t elements_written = fwrite(records, sizeof(record), num_records, file);
    if (elements_written != num_records) {
        fprintf(stderr, "Failed to write all records to disk\n");
        exit(-1);
    }

    fclose(file);

    pthread_mutex_unlock(&lock);
}
```

This example creates a thread-safe function `generate_records()` that generates the array of records. The function then writes this to disk using the non-blocking lock `pthread_mutex_lock()` and `pthread_mutex_unlock()` for synchronization, with error checking included as well. Please note that you would likely want to include more sophisticated logging, error handling, etc. in a production environment.
