#include <time.h>
#include <string.h>

typedef struct {
    double timestamp;
    int priority;
    char* message;
} Event;

void generate_event(int minLength, int maxLength, FILE *file) {
    srand((unsigned int) time(NULL));
    Event event;
    event.timestamp = (double)time(NULL);
    event.priority = rand() % 10 + 1; // priority between 1 and 10

    int length = minLength + (rand() % (maxLength - minLength)); // random message length
    event.message = malloc((length+1) * sizeof(char));
    for (int i = 0; i < length; i++) {
        event.message[i] = 'a' + rand()%26;  // generate random string
    }
    event.message[length] = '\0';

    if(file == NULL){
        printf("Timestamp: %f, Priority: %d, Message: %s\n", event.timestamp, event.priority, event.message);
    } else {
        fprintf(file, "Timestamp: %f, Priority: %d, Message: %s\n", event.timestamp, event.priority, event.message); 
    }

    free(event.message); // clean up dynamically allocated memory
}
```
The function `generate_event` generates a random event and logs it to either the console or to the file pointed by a FILE pointer passed as an argument. It uses dynamic allocation for the message string which should be freed afterwards to avoid memory leaks. If no file is provided (i.e., the FILE pointer is NULL), the function will log events to the console, otherwise it logs them to the specified file.
