        records[i].offset = rand();  // Generate a random offset.
        records[i].key = rand() % RAND_MAX;  // Generate a random key.

        // Generate a random timestamp within the specified range.
        double range = max_ts - min_ts;
        double div = RAND_MAX / range;
        records[i].timestamp = min_ts + (rand() / div); 
    }

    return records;
}
