["The problem description is quite broad and complex, implementing all these features in a single function can be quite overwhelming. Here's a simplified version of what such an implementation might look like using pthread_rwlock_t for thread-safe operations, a simple cache mechanism with a read/write lock to maintain cache coherence, and an array list style structure to efficiently resize:

```c
#include <pthread.h>
#include <stdlib.h>

typedef union {
    long offset;
    int key;
} RecordValue;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
    RecordValue* values;
} RecordList;

RecordList create(size_t initialSize) {
    RecordList list;
    list.capacity = initialSize;
    list.count = 0;
    list.values = malloc(initialSize * sizeof(RecordValue));
    pthread_rwlock_init(&list.lock, NULL);
    return list;
}

void add(RecordList* list, RecordValue value) {
    pthread_rwlock_wrlock(&list->lock);

    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->values = realloc(list->values, list->capacity * sizeof(RecordValue));
    }

    list->values[list->count++] = value;

    pthread_rwlock_unlock(&list->lock);
}

// For simplicity, this function assumes that the key values are unique.
RecordValue* getByKey(RecordList* list, int key) {
    pthread_rwlock_rdlock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->values[i].key == key) {
            RecordValue* result = &list->values[i];

            pthread_rwlock_unlock(&list->lock);
            return result;
        }
    }

    pthread_rwlock_unlock(&list->lock);
    return NULL;
}

RecordValue* getByIndex(RecordList* list, size_t index) {
    if (index >= list->count) {
        return NULL;
    }

    pthread_rwlock_rdlock(&list->lock);

    RecordValue* result = &list->values[index];

    pthread_rwlock_unlock(&list->lock);
    return result;
}
``` 

