    long offset;
    int key;
    double timestamp;
} Record;

// Function to initialize records with unique keys and timestamps within specified ranges
enum ErrorCode initRecords(Record** records_ptr, size_t max_records, int key_lower, int key_upper) {
    // Allocate memory for the records array
    *records_ptr = (Record*) malloc(max_records * sizeof(Record));

    if (*records_ptr == NULL) {
        return ALLOCATION_FAILURE;  // Return error code when allocation fails
    }

    int key_range = key_upper - key_lower + 1;

    for (size_t i = 0; i < max_records; ++i) {
        (*records_ptr)[i].offset = i;  // Set offset to the record's index in array

        if(key_range > RAND_MAX || key_upper <= key_lower){
            return ALLOCATION_FAILURE;
        }

        int unique_key = rand() % key_range + key_lower;  // Generate a unique key within the range

        for (size_t j = 0; j < i; ++j) {
            if ((*records_ptr)[j].key == unique_key) {
                --i;  // If the generated key is not unique, try again
                break;
            }
        }

        (*records_ptr)[i].key = unique_key;  // Set the record's key to the generated unique key
        (*records_ptr)[i].timestamp = time(NULL);  // Set timestamp to current time in seconds since epoch
    }

    return SUCCESS;  // No errors occurred, return success code
}

// Function to deallocate allocated memory when done
void freeRecords(Record** records_ptr) {
    free(*records_ptr);
    *records_ptr = NULL;
}
