    unsigned long size;
    double timestamp;
};

void generateFileRecords(std::vector<FileRecord>& fileRecords, const fs::path& directoryPath, int numFiles, unsigned long minSize, unsigned long maxSize) {

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<unsigned long> sizeDistrib(minSize, maxSize);
    std::vector<std::string> filenames = getFilenameList(directoryPath);  // assuming a function to get the filename list from the directory.

