        FileRecord record;

        try {
            if(!filenames.empty()) {
                std::uniform_int_distribution<unsigned long> filenameDistrib(0, filenames.size()-1);
                unsigned long index = filenameDistrib(gen);
                record.filename = filenames[index];
                filenames.erase(filenames.begin()+index);  // remove the used filename to avoid duplicates in different records
            } else {
                std::cout << "No more file names available!" << std::endl;
                break;
            }

            record.size = sizeDistrib(gen);
            record.timestamp = std::time(0);
        } catch (const std::bad_alloc& e) {
            mtx.unlock();
            throw std::runtime_error("Memory allocation failure!");
        }

        fileRecords.push_back(record);
