void* allocate_records(void *args) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;  // Mutex lock for thread safety
    record *records;
    int *keys;
    long *offsets;
    size_t num_records, key_range, timestamp_range;
    unsigned int seed = time(NULL);

    pthread_mutex_lock(&mutex);  // Lock mutex before accessing shared data
