        printf("Error: Number of records exceeded limit.\n");
        pthread_mutex_unlock(&mutex);  // Unlock mutex before returning to avoid deadlock
        return NULL;
    }

    records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        printf("Error: Failed to allocate memory for records.\n");
        pthread_mutex_unlock(&mutex);  // Unlock mutex before returning to avoid deadlock
        return NULL;
