["Here is a basic implementation using a hashmap and mutexes for thread safety:

```C
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef struct {
    double value;
    char *identifier;
} Entry;

typedef struct Node_t {
    Entry *entry;
    struct Node_t *next;
} Node;

Node *entries[1009] = {NULL};  // Prime number for less collisions
pthread_mutex_t locks[1009] = PTHREAD_MUTEX_INITIALIZER;

unsigned long hash(char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % 1009;
}

void add_entry(Entry *new_entry) {
    unsigned long index = hash(new_entry->identifier);
    pthread_mutex_lock(&locks[index]);

    Node *node = malloc(sizeof(Node));
    node->entry = new_entry;
    node->next = entries[index];
    entries[index] = node;

    pthread_mutex_unlock(&locks[index]);
}

Entry* get_entry(char *id) {
    unsigned long index = hash(id);
    pthread_mutex_lock(&locks[index]);

    Node *node = entries[index];
    while (node != NULL) {
        if (strcmp(node->entry->identifier, id) == 0) {
            pthread_mutex_unlock(&locks[index]);
            return node->entry;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&locks[index]);
    return NULL;
}

void remove_entry(char *id) {
    unsigned long index = hash(id);
    pthread_mutex_lock(&locks[index]);

    Node **link = &entries[index];
    while (*link != NULL) {
        if (strcmp((*link)->entry->identifier, id) == 0) {
            Node *node_to_free = *link;
            *link = (*link)->next;
            free(node_to_free);

            pthread_mutex_unlock(&locks[index]);
            return;
        }

        link = &(*link)->next;
    }

    pthread_mutex_unlock(&locks[index]);
}

void iterate(void (*operation)(Entry*)) {
    for (int i = 0; i < 1009; ++i) {
        pthread_mutex_lock(&locks[i]);

        Node *node = entries[i];
        while (node != NULL) {
            operation(node->entry);
            node = node->next;
        }

        pthread_mutex_unlock(&locks[i]);
    }
}
```
This code provides a basic hashmap implementation where each entry is inserted into the map using its identifier's hash value. Each operation has been made thread-safe by locking the appropriate mutex before performing any operations on the corresponding bucket. Additionally, memory allocation for new entries and nodes is performed in a manner that minimizes overhead without affecting performance.
