        *head = newNode;
    } else {
        Node* current = *head;

        while (current->next != NULL && 
               current->next->value < newNode->value) { 
            current = current->next;
        }

        newNode->next = current->next;
        current->next = newNode;
    }
}

// Traverse linked list to create balanced BST
typedef struct bst_node{
    double value;
    struct bst_node *left, *right;
} BSTNode;

BSTNode* sortedLinkedListToBST(Node** headRef, int n) {
    if (n <= 0) return NULL;

    BSTNode *left = sortedLinkedListToBST(headRef, n/2);

    BSTNode *root = malloc(sizeof(BSTNode));
    root->value = (*headRef)->value;

    root->left = left;

    *headRef = (*headRef)->next;

    root->right = sortedLinkedListToBST(headRef, n - n/2 - 1);

    return root;
}
