typedef struct record {
    long offset;
    int key;
    double timestamp;
} Record;

typedef struct node {
    Record *record;
    struct node *next;
} Node;

typedef struct hash_table {
    Node **buckets;
    size_t capacity;
    size_t size;
} HashTable;

Record* new_record(long offset, int key) {
    Record *new_rec = (Record*) malloc(sizeof(Record));
    assert(new_rec != NULL);  // Handle allocation failure gracefully.

    new_rec->offset = offset;
    new_rec->key = key;
    new_rec->timestamp = time(NULL);  // Initialize timestamp to current time in seconds since epoch.

    return new_rec;
}

Node* new_node(Record *record) {
    Node *new_nde = (Node*) malloc(sizeof(Node));
    assert(new_nde != NULL);  // Handle allocation failure gracefully.

    new_nde->record = record;
    new_nde->next = NULL;

    return new_nde;
}

HashTable* new_hash_table(size_t capacity) {
    HashTable *new_htb = (HashTable*) malloc(sizeof(HashTable));
    assert(new_htb != NULL);  // Handle allocation failure gracefully.

    new_htb->capacity = capacity;
    new_htb->size = 0;

    new_htb->buckets = (Node**) malloc(sizeof(Node*) * capacity);
    assert(new_htb->buckets != NULL);  // Handle allocation failure gracefully.

    for (size_t i = 0; i < capacity; ++i) {
        new_htb->buckets[i] = NULL;
    }

    return new_htb;
}

void insert(HashTable *hash_table, Node *node) {
    size_t index = node->record->key % hash_table->capacity;

    if (hash_table->buckets[index] == NULL) {
        hash_table->buckets[index] = node;
    } else {
        Node *curr = hash_table->buckets[index];

        while (curr->next != NULL && curr->record->key != node->record->key) {
            curr = curr->next;
        }

        if (curr->record->key == node->record->key) {  // If collision, update existing record.
            free(curr->record);
            curr->record = node->record;
            free(node);
        } else {  // Otherwise, add to the end of the chain.
            curr->next = node;
        }
    }

    hash_table->size++;
}

Record* find(HashTable *hash_table, int key) {
    size_t index = key % hash_table->capacity;

    Node *curr = hash_table->buckets[index];

    while (curr != NULL && curr->record->key != key) {
        curr = curr->next;
    }

    if (curr == NULL) {  // If not found, return NULL.
        return NULL;
    } else {
        return curr->record;
    }
}
```
