['Here is an initial implementation in C using POSIX Threads (pthreads) for thread safety:

```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
    char* id;
} record;

record** records = NULL;
int size = 0;
char* prefix = "record_"; // default prefix, can be changed
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void insertRecord(long offset, int key) {
    pthread_mutex_lock(&mutex);
    ++size;
    records = realloc(records, size * sizeof(record*));
    if (records == NULL) {
        --size; // rollback
        fprintf(stderr, "Memory allocation error\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    records[size - 1] = malloc(sizeof(record));
    if (records[size - 1] == NULL) {
        --size; // rollback
        fprintf(stderr, "Memory allocation error\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    records[size - 1]->offset = offset;
    records[size - 1]->key = key;
    time_t t = time(NULL);
    records[size - 1]->timestamp = (double)t;

    char* idStr = malloc(20 * sizeof(char)); // length of size + null terminator
    if (idStr == NULL) {
        --size; // rollback
        fprintf(stderr, "Memory allocation error\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    sprintf(idStr, "%s%d", prefix, size - 1);
    records[size - 1]->id = idStr;
    pthread_mutex_unlock(&mutex);
}

record* getRecord(int key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < size; ++i) {
        if (records[i]->key == key) {
            pthread_mutex_unlock(&mutex);
            return records[i];
        }
    }

    fprintf(stderr, "Record with key %d not found\n", key);
    pthread_mutex_unlock(&mutex);
    return NULL; // no record found
}
