typedef struct record {
    long offset;
    int key;
    double timestamp;
} Record;

typedef struct node {
    int key;
    Record* rec;
    struct node* next;
} Node;

Node** hashTable = NULL;
int tableSize = 0;
const int initialSize = 1024;

void initializeHashTable() {
    if (hashTable == NULL) {
        hashTable = malloc(sizeof(Node*) * initialSize);
        for (int i = 0; i < initialSize; ++i) {
            hashTable[i] = NULL;
        }
        tableSize = initialSize;
    }
}

Record* createRecord(long offset, int key) {
    Record* rec = malloc(sizeof(Record));
    if (rec == NULL) return NULL;

    rec->offset = offset;
    rec->key = key;
    rec->timestamp = (double)time(NULL);

    int index = abs(key) % tableSize;
    Node* node = malloc(sizeof(Node));
    if (node == NULL) return NULL;

    node->rec = rec;
    node->next = hashTable[index];
    hashTable[index] = node;

    return rec;
}

void deallocateHashTable() {
    for (int i = 0; i < tableSize; ++i) {
        Node* currNode = hashTable[i];
        while (currNode != NULL) {
            Node* nextNode = currNode->next;
            free(currNode->rec);
            free(currNode);
            currNode = nextNode;
        }
    }
    free(hashTable);
}
```

