        struct timespec ts;
        timespec_get(&ts, TIME_UTC);
        records[i].timestamp = (double)ts.tv_sec + ((double)ts.tv_nsec / 1e9);
        if(precision > 0) {
            double precisionValue = 1 / precision;
            records[i].timestamp -= fmod(records[i].timestamp, precisionValue);
        }
    }

    // Sort the array if required.
    if (sortFlag) qsort(records, maxSize, sizeof(Record), compareRecords);

    return records; 
}

int isUnique(Record** records, int size, int index) {
    for (int i = 0; i < index; ++i) {
        if ((*records)[index].key == (*records)[i].key) return -1;
    }

    return 0;
}

void cleanUp(Record** records, int maxSize) {
    // Deallocate memory.
    free(*records);
    *records = NULL;
}

int compareRecords(const void* a, const void* b) {
   Record* recordA = (Record*)a;
   Record* recordB = (Record*)b; 

   if(recordA->key < recordB->key) return -1;
   else if(recordA->key == recordB->key) return 0;
   else return 1;
}
```
The function initializeRecords() is the main one which accepts the parameters for maximum number of records, key range limits, timestamp precision and a flag indicating whether the records should be sorted by their keys after initialization. Each record’s integer key should be unique within the allocated array, ensuring no collisions occur. 

Use the function cleanUp() to deallocate all allocated memory when done. It is important that users of this function are responsible for managing any dynamic allocation or deallocation, particularly in a larger system with dependencies on other components or libraries.

