void allocateMemory(UserEntry **users, int numEntries) {
    srand((unsigned int)time(NULL)); // seeding the random number generator with current time

    *users = (UserEntry*) malloc(numEntries * sizeof(UserEntry));
    if (*users == NULL) {
        printf("Failed to allocate memory.\n");
        exit(1);
    }
}

void generateRandomValues(UserEntry *users, int numEntries) {
    for (int i = 0; i < numEntries; i++) {
        users[i].offset = rand();
        users[i].key = rand() % 100 + 1; // assuming key range is between 1 and 100

        int nameIndex = rand() % nameCount;
        size_t len = strlen(userNames[nameIndex]);
        users[i].user_name = (char*) malloc((len+1) * sizeof(char)); // including the null terminator
        if (users[i].user_name == NULL) {
            printf("Failed to allocate memory for user name %d.\n", i);
            exit(1);
        }
        strncpy(users[i].user_name, userNames[nameIndex], len+1); // copy the string safely

        if (strcmp(users[i].user_name, "") == 0) { // checking for empty strings
            printf("Empty username detected. Exiting.\n");
            exit(1);
        }
    }
}

void freeMemory(UserEntry *users, int numEntries) {
    for (int i = 0; i < numEntries; i++) {
        if (users[i].user_name != NULL) {
            free(users[i].user_name); // free each user name
        }
    }

    if (users != NULL) {
        free(users); // finally, free the whole array
    }
}

