    UserEntry *users = NULL;

    allocateMemory(&users, numEntries);

    generateRandomValues(users, numEntries);

    printf("Successfully allocated and generated random values for %d entries.\n", numEntries);

    freeMemory(users, numEntries);

    return 0;
}
