    for(int i = data->fieldCount - 1; i >= 0 && i >= data->fieldCount - 2; i--) {
        char* endptr;
        double val = strtod(data->fields[i], &endptr);

        if(*endptr == '\0') { // successful conversion to numeric field
            if(num1 == 0.0) num1 = val;
            else if(num2 == 0.0) num2 = val;
        }
    }

    // Calculate average and append to line data
    double avg = (num1 + num2) / 2.0;
    char* strAvg = malloc(32);
    sprintf(strAvg, " %.2lf", avg);

    // Reallocate memory to append average string
    data->fields[data->fieldCount] = realloc(data->fields[data->fieldCount], 
                                            strlen(strAvg) + 1);
    strcat(data->fields[data->fieldCount++], strAvg);

    free(strAvg);
}

int main() {
    // Open files, read lines into LineData structs and create threads for processing
    pthread_t* threads = malloc(sizeof(pthread_t) * lineCount); // assume line count is known

    for(int i = 0; i < lineCount; i++) {
