#include <stdlib.h>
#include <time.h>
#include <stdatomic.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    double timestamp;
} record_t;

typedef struct hash_node {
    record_t* value;
    struct hash_node *next;
} hash_node_t;

typedef struct hash_table {
    size_t capacity;
    atomic_size_t count;
    pthread_mutex_t lock;
    hash_node_t **nodes;
} hash_table_t;

hash_table_t* create_table(size_t capacity) {
    hash_table_t *new_table = malloc(sizeof(hash_table_t));
    new_table->capacity = capacity;
    atomic_init(&new_table->count, 0);
    pthread_mutex_init(&new_table->lock, NULL);
    new_table->nodes = calloc(new_table->capacity, sizeof(hash_node_t *));

    if (!new_table->nodes) {
        free(new_table);
        return NULL;
    }
    return new_table;
}

void insert_record(hash_table_t* table, record_t *value) {
    size_t index = value->key % table->capacity;

    pthread_mutex_lock(&table->lock);
    hash_node_t *node = malloc(sizeof(hash_node_t));
    node->value = value;
    node->next = table->nodes[index];
    table->nodes[index] = node;

    atomic_fetch_add(&table->count, 1);
    pthread_mutex_unlock(&table->lock);
}

// This is just the start. You will need to implement functions for retrieving records from the table and deallocating memory properly in each function call. Also note that you should use more efficient collision resolution strategies like chaining or open addressing, instead of the simple linked list used here.
