```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class HashingFunction {
    private static final Logger logger = LogManager.getLogger(HashingFunction.class);

    public enum OutputFormat{HEX, BASE64}

    public byte[] hashIntegers(OutputFormat outputFormat, int... numbers) throws Exception {
        if (numbers == null || numbers.length == 0) throw new IllegalArgumentException("No numbers provided");

        StringBuilder sb = new StringBuilder();
        for (int num : numbers){
            if (Integer.toString(num).length() > SystemConfiguration.getInstance().getMaximumAllowedLength()) 
                throw new Exception("Excessively large input detected, aborting processing");

            sb.append(num);
        }

        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hash = digest.digest(sb.toString().getBytes(StandardCharsets.UTF_8));

        logger.info("Hashed integer: " + sb.toString());

        switch (outputFormat){
            case HEX: 
                return toHexString(hash).getBytes();
            case BASE64: 
                return Base64.encodeBase64(hash);
        }
        throw new IllegalArgumentException("Invalid output format");
    }

    private String toHexString(byte[] bytes) {
        Formatter formatter = new Formatter();
        for (byte b : bytes) formatter.format("%02x", b);
        return formatter.toString();
    }
}
```

