```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} record;

void create_records(int sets, int recordsPerSet) {
    if (sets <= 0 || recordsPerSet <= 0) {
        fprintf(stderr, "Number of sets and records per set must be positive integers.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for pointers to record sets.
    record **records = malloc(sets * sizeof(record*));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    double currentTime = time(NULL); // Get the current time.

    for (int i = 0; i < sets; ++i) {
        records[i] = malloc(recordsPerSet * sizeof(record));

        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");

            // Free previously allocated memory before exit.
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }

            free(records);
            exit(EXIT_FAILURE);
        }

        for (int j = 0; j < recordsPerSet; ++j) {
            records[i][j].offset = i * recordsPerSet + j; // Set offset.
            records[i][j].key = j; // Set key.
            records[i][j].timestamp = currentTime; // Set timestamp.
        }
    }

    // Free allocated memory.
    for (int i = 0; i < sets; ++i) {
        free(records[i]);
    }

    free(records);
}
```
This function creates an array of pointers to 'record' structures, where each pointer points to a dynamically allocated block of memory that stores multiple 'record' structures. The timestamp for all records is set to the current time at the start of the function execution. In case of allocation failure, the function frees previously allocated blocks and exits with an error message.
