        printf("Error: Allocation failed for record sets\n");
        return NULL;
    }

    // allocate memory for each set of records
    for (int i = 0; i < setCount; i++) {
        records[i] = calloc(recordPerSet, sizeof(Record));

        if (records[i] == NULL) {
            printf("Error: Allocation failed for record %d\n", i);

            // deallocate previous sets in case of allocation failure
            for (int j = 0; j < i; j++) 
                free(records[j]);
            free(records);

            return NULL;
        }

        // initialize each record's fields
        for (int j = 0; j < recordPerSet; j++) {
            records[i][j].offset = i * recordPerSet + j;
            records[i][j].key = rand();

            struct timespec ts;
            timespec_get(&ts, TIME_UTC);
            double randomOffset = 1e-3 * (rand() % 1001 - 500); // in milliseconds
            records[i][j].timestamp = (double)ts.tv_sec + randomOffset;

            const int identifierSize = 20; // arbitrary size, adjust as needed
            records[i][j].identifier = malloc(identifierSize);
            sprintf(records[i][j].identifier, "Record %d", j + 1);
        }
    }

    return records;
}

void deallocate_records(Record** records, int setCount) {
    for (int i = 0; i < setCount; i++) {
        // free each identifier string
        for (int j = 0; records[i] != NULL && records[i][j].identifier != NULL; j++) 
            free(records[i][j].identifier);

        // free each set of records
        free(records[i]);
    }

    // free the array holding the record sets
    free(records);
}
```
