['Here's a skeleton C code that implements some features mentioned in your requirements using pthread library for thread safety and a logging framework (e.g., log4c) for tracking allocations/deallocations:

```C
#include <pthread.h>
#include <log4c.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    char* user_name;
} Entry;

typedef struct {
    size_t limit;  // Max number of entries allowed in array
    Entry** entries;  // Array of entries
    size_t count;  // Current count of entries
    pthread_mutex_t lock;  // Mutex for thread safety
} EntryManager;

void initEntry(Entry* e, long offset, int key, const char* userName) {
    e->offset = offset;
    e->key = key;
    e->user_name = strdup(userName);
}

void freeEntry(Entry* e) {
    free(e->user_name);
}

// Initialize the entry manager
void initManager(EntryManager* mgr, size_t limit) {
    mgr->limit = limit;
    mgr->entries = calloc(mgr->limit, sizeof(Entry*));
    mgr->count = 0;
    pthread_mutex_init(&mgr->lock, NULL);
}

// Free all entries and the manager itself
void freeManager(EntryManager* mgr) {
    for (size_t i = 0; i < mgr->count; ++i) {
        freeEntry(mgr->entries[i]);
        free(mgr->entries[i]);
    }
    free(mgr->entries);
}

// Add an entry, maintaining uniqueness of keys and ensuring total memory usage doesn't exceed limit.
void addEntry(EntryManager* mgr, long offset, int key, const char* userName) {
    pthread_mutex_lock(&mgr->lock);
    if (mgr->count >= mgr->limit) {
        log4c_category_log(log4c_category_get("manager"), LOG4C_PRIORITY_ERROR, "Entry limit exceeded!");
        pthread_mutex_unlock(&mgr->lock);
        return;
    }
    for (size_t i = 0; i < mgr->count; ++i) {
        if (mgr->entries[i]->key == key) {
            log4c_category_log(log4c_category_get("manager"), LOG4C_PRIORITY_ERROR, "Duplicate key found!");
            pthread_mutex_unlock(&mgr->lock);
            return;
        }
    }
    mgr->entries[mgr->count] = calloc(1, sizeof(Entry));
    initEntry(mgr->entries[mgr->count], offset, key, userName);
    ++mgr->count;
    pthread_mutex_unlock(&mgr->lock);
}

// Filter entries based on minimum key value threshold
Entry** filterEntries(const EntryManager* mgr, int minKey, size_t* count) {
    *count = 0;
    for (size_t i = 0; i < mgr->count; ++i) {
        if (mgr->entries[i]->key >= minKey) {
            ++(*count);
        }
    }
    Entry** result = calloc(*count, sizeof(Entry*));
    size_t j = 0;
    for (size_t i = 0; i < mgr->count; ++i) {
        if (mgr->entries[i]->key >= minKey) {
            result[j++] = mgr->entries[i];
        }
    }
    return result;
}
```
Please note that this is a simple example and in a real-world scenario, we would need to take care of other factors such as error checking, memory management for the configuration manager, and so on. Also, the code doesn't implement dynamic resizing due to complexity, but it shows how you could add it by using `realloc` instead of `calloc` when adding an entry.
']

