char* taskDescriptions[] = {"Task1", "Task2", "Task3"};
int numTasks = sizeof(taskDescriptions) / sizeof(taskDescriptions[0]);

// Function to generate random priority level within specified range
int generatePriorityLevel() {
    int min = 1;  // Minimum priority level
    int max = 5;  // Maximum priority level
    return rand() % (max - min + 1) + min;
}

void dynamicTaskList(int numTasksToGenerate) {
    srand((unsigned int) time(NULL));

    Task* taskList = malloc(numTasksToGenerate * sizeof(Task));
    if(taskList == NULL){
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return;
    } 

    int allocated = 0;

    for (int i = 0; i < numTasksToGenerate && allocated < numTasks; ++i) {
        taskList[i].timestamp = time(NULL);

        // Ensure unique descriptions by selecting from predefined list
        if (numTasks > 0){
            int index = rand() % numTasks;
            char* description = malloc(strlen(taskDescriptions[index]) + 1);

            if(description == NULL){
                fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
                continue;  // Skip this iteration and continue with the next task
            }

            strcpy(description, taskDescriptions[index]);
            taskList[i].description = description;
            ++allocated;
        } else {
            fprintf(stderr, "No more tasks to generate.\n");
            break;  // No more tasks to generate
        }

        taskList[i].priorityLevel = generatePriorityLevel();
    }

    printf("Successfully allocated %d tasks\n", allocated);

    // Free allocated memory when done
    for (int i = 0; i < numTasksToGenerate && allocated > 0; ++i, --allocated) {
        free(taskList[i].description);
    }
    free(taskList);
}
```
