    size_t count;
    struct CategoryNode *next;
} Category;

Category *categoryHashTable[10007];
int totalEvents = 0; // Use atomic operations in a multithreaded environment.

EventLog *createEvent(char* message, int logLevel) {
    EventLog *log = malloc(sizeof(EventLog));

    if(!log){
        printf("Memory allocation failed.\n");
        return NULL; // Returning NULL in case of failure.
    }

    log->timestamp = time(NULL);

    log->messageBuffer = malloc(1024 * sizeof(char));

    if(!log->messageBuffer){
        printf("Memory allocation failed.\n");
        free(log); // Free the partially allocated memory.
        return NULL; 
    }

    strncpy(log->messageBuffer, message, 1023); // Don't forget to null terminate your string.

    log->logLevel = logLevel;

    return log;
}

void deleteEvent(EventLog *event){
    free(event->messageBuffer);
    free(event);
}

Category* createCategory(char* name){
    Category *newCategory = malloc(sizeof(Category));

    if(!newCategory){
        printf("Memory allocation failed.\n");
        return NULL; 
    }

    newCategory->name = malloc(128 * sizeof(char));

    if(!newCategory->name){
        printf("Memory allocation failed.\n");
        free(newCategory); // Free the partially allocated memory.
        return NULL; 
    }

    strncpy(newCategory->name, name, 127); // Don't forget to null terminate your string.

    newCategory->count = 0;

    newCategory->next = NULL;

    return newCategory;
}

void deleteCategory(Category *category){
    free(category->name);
    free(category);
}

unsigned int hashCode(char* name) { // A simple hash function.
    unsigned int code = 0;

    for (int i = 0; name[i] != '\0'; ++i){ 
        code = code * 31 + name[i];
    }

    return code % 10007; // Ensuring it stays within the array bounds.
}

void logEvent(char* message, char* categoryName, int logLevel) {
    EventLog *newEvent = createEvent(message, logLevel);

    if(!newEvent){
        return; 
    }

    unsigned int hashIndex = hashCode(categoryName);
    Category *currCategory = categoryHashTable[hashIndex];

    while (currCategory != NULL) { // Traversing the linked list.

        if (strcmp(currCategory->name, categoryName) == 0){ 
            currCategory->count++;
            break;
        }

        currCategory = currCategory->next;
    }

    // If we reached the end of the list and no matching category was found.
    if (currCategory == NULL){ 

        Category *newCategory = createCategory(categoryName);

        newCategory->count = 1;
        newCategory->next = categoryHashTable[hashIndex]; // Adding to the beginning of the list.

        categoryHashTable[hashIndex] = newCategory;
    }

    totalEvents++;
}
``` 
