using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public enum DataType { Integer, Float }

public interface IDataSource<T> where T : struct
{
    Task<T?> FetchDataAsync();
}

public class DataSourceConfiguration
{
    public int UpdateFrequency { get; set; }
    public DataType DataType { get; set; }
    // Other configuration options here...
}

public class DataSourceManager
{
    private Dictionary<string, (IDataSource<int> Source, DataSourceConfiguration Config)> 
        _integerDataSources = new();

    private Dictionary<string, (IDataSource<float> Source, DataSourceConfiguration Config)> 
        _floatDataSources = new();

    public void AddDataSource(string name, IDataSource source, DataSourceConfiguration config)
    {
        switch (config.DataType)
        {
            case DataType.Integer:
                _integerDataSources[name] = (source as IDataSource<int>, config);
                break;
            case DataType.Float:
                _floatDataSources[name] = (source as IDataSource<float>, config);
                break;
        }
    }

    public void RemoveDataSource(string name)
    {
        if (_integerDataSources.ContainsKey(name))
            _integerDataSources.Remove(name);

        else if (_floatDataSources.ContainsKey(name))
            _floatDataSources.Remove(name);
    }

    public async Task<IEnumerable<object>> AggregateDataAsync()
    {
        var result = new List<object>();

        foreach (var dataSource in _integerDataSources)
        {
            try 
            {
                result.Add(await dataSource.Value.Source.FetchDataAsync());
            }
            catch 
            {
                // Handle missing data or other exceptions...
                result.Add(null);
            }
        }

        foreach (var dataSource in _floatDataSources)
        {
            try 
            {
                result.Add(await dataSource.Value.Source.FetchDataAsync());
            }
            catch 
            {
                // Handle missing data or other exceptions...
                result.Add(null);
            }
        }

        return result;
    }

    public override string ToString()
    {
        var info = "";

        foreach (var dataSource in _integerDataSources)
        {
            info += $"Name: {dataSource.Key}, Type: Integer, Frequency: {dataSource.Value.Config.UpdateFrequency}\n";
        }

        foreach (var dataSource in _floatDataSources)
        {
            info += $"Name: {dataSource.Key}, Type: Float, Frequency: {dataSource.Value.Config.UpdateFrequency}\n";
        }

        return info;
    }
}
```

