['```C#
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using Microsoft.Extensions.Logging;
using Amazon; // Or use the specific AWS SDK for .NET

public class SecureDataService {
    private readonly ILogger<SecureDataService> logger;
    private readonly IExternalStorage storage;
    private const int MaxAttempts = 3;
    private ReaderWriterLockSlim keyIvLock = new ReaderWriterLockSlim();
    private byte[] key, iv;

    public SecureDataService(ILogger<SecureDataService> logger, IExternalStorage storage) {
        this.logger = logger;
        this.storage = storage;
    }

    public async Task EncryptAsync(byte[] dataToEncrypt, byte[] key, byte[] iv) {
        using (var aesCBC = new AesCbc(key, iv)) {
            await EncryptDecorator(() => this.storage.SaveKeyIVAsync(aesCBC.GetKey(), aesCBC.GetIV()));

            try {
                var encryptedData = aesCBC.Encrypt(dataToEncrypt);
                // Save the encrypted data...
            } catch (Exception e) {
                logger.LogError("Failed to encrypt data: {0}", e.Message);
            }
        }
    }

    public async Task DecryptAsync(byte[] dataToDecrypt, byte[] key, byte[] iv) {
        using (var aesCBC = new AesCbc(key, iv)) {
            await EncryptDecorator(() => this.storage.SaveKeyIVAsync(aesCBC.GetKey(), aesCBC.GetIV()));

            try {
                var decryptedData = aesCBC.Decrypt(dataToDecrypt);
                // Save the decrypted data...
            } catch (Exception e) {
                logger.LogError("Failed to decrypt data: {0}", e.Message);
            }
        }
    }

    private async Task EncryptDecorator(Func<Task> action) {
        int attempts = 0;
        while (attempts < MaxAttempts) {
            try {
                keyIvLock.EnterWriteLock();
                await action();
                return;
            } catch (Exception e) {
                logger.LogWarning("Failed to save key and IV: {0}", e.Message);
                attempts++;
            } finally {
                keyIvLock.ExitWriteLock();
            }
        }

        throw new Exception($"Failed to store key and IV after {MaxAttempts} attempts.");
    }
}
``` 

The `AesCbc` class is a wrapper around the AES encryption in CBC mode, handling padding internally. The `IExternalStorage` interface represents an external storage service that provides methods for saving key and IV data to a remote database or server:

