typedef struct {
    long offset;
    int key;
    double timestamp;
    char* payload;
} Record;

Record** records = NULL;
int numRecords = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addRecord(long offset, int key, double timestamp, const char* payload) {
    pthread_mutex_lock(&lock);

    // reallocate memory for the record array
    records = (Record**)realloc(records, sizeof(Record*) * (numRecords + 1));
    if (!records) exit(EXIT_FAILURE); // handle allocation failure

    // allocate memory for new record
    Record* newRecord = (Record*)malloc(sizeof(Record));
    if (!newRecord) exit(EXIT_FAILURE); // handle allocation failure

    newRecord->offset = offset;
    newRecord->key = key;
    newRecord->timestamp = timestamp;

    size_t payloadSize = strlen(payload) + 1;
    newRecord->payload = (char*)malloc(sizeof(char) * payloadSize);
    if (!newRecord->payload) exit(EXIT_FAILURE); // handle allocation failure

    strncpy(newRecord->payload, payload, payloadSize);

    records[numRecords] = newRecord;
    numRecords++;

    pthread_mutex_unlock(&lock);
}
``` 
