#include <string.h>
#include <time.h>

typedef struct Event {
    char *id;
    char *message;
    time_t timestamp;
    int priorityLevel;
} Event;

// Global event array and mutex for thread-safe access
GArray *events;
pthread_mutex_t eventsMutex = PTHREAD_MUTEX_INITIALIZER;

char* hash(const char *input) { /* function to generate hash */ }

// Helper function to create a new event
Event* newEvent(const char *message, int priorityLevel) {
    Event *event = malloc(sizeof(Event));
    if (!event) {
        // handle allocation failure
        return NULL;
    }

    event->id = hash(message);
    event->message = strdup(message);
    event->timestamp = time(NULL);
    event->priorityLevel = priorityLevel;

    return event;
}

// Function to add new events into the global array in a thread safe manner
void addEvent(const char *message, int priorityLevel) {
    pthread_mutex_lock(&eventsMutex);
    Event *event = newEvent(message, priorityLevel);
    if (!event) {
        // handle error
        return;
    }

    g_array_append_val(events, event);
    pthread_mutex_unlock(&eventsMutex);
}

// Helper function to count events with priority level above a threshold
int countEventsAboveThreshold(int threshold) {
    int count = 0;

    for (size_t i = 0; i < events->len; ++i) {
        Event *event = g_array_index(events, Event*, i);
        if (event->priorityLevel > threshold) {
            ++count;
        }
    }

    return count;
}
```
