    size_t offset_size;
    size_t key_size;
    size_t record_size;
} DataContainer;

DataContainer* init_data(size_t max_offset, size_t max_key, size_t max_record) {
    srand((unsigned int)time(NULL)); // seed the random number generator

    DataContainer *container = malloc(sizeof(DataContainer));
    if (container == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    container->offsets = malloc(max_offset * sizeof(long));
    if (container->offsets == NULL) {
        fprintf(stderr, "Offset memory allocation failed.\n");
        free(container);
        return NULL;
    }

    container->keys = malloc(max_key * sizeof(int));
    if (container->keys == NULL) {
        fprintf(stderr, "Key memory allocation failed.\n");
        free(container->offsets);
        free(container);
        return NULL;
    }

    container->records = malloc(max_record * sizeof(Record));
    if (container->records == NULL) {
        fprintf(stderr, "Record memory allocation failed.\n");
        free(container->offsets);
        free(container->keys);
        free(container);
        return NULL;
    }

    container->offset_size = max_offset;
    container->key_size = max_key;
    container->record_size = max_record;

    pthread_mutex_init(&container->lock, NULL); // initialize the mutex lock

    return container;
}
