typedef struct {
    long offset;
    int key;
    double timestamp;
} Event;

void* read_input(void *arg) {
    // Read integers from stdin and store in dynamically resizable array
    FILE *fp = fopen("/dev/stdin", "r");

    // Initial allocation size
    int capacity = 10;
    Event *events = malloc(capacity * sizeof(Event));
    if (events == NULL) {
        perror("Failed to allocate memory for events");
        return NULL;
    }

    int count = 0;
    while (fscanf(fp, "%d", &input) == 1) {
        // Check if we need to resize the array
        if (count >= capacity) {
            capacity *= 2;
            events = realloc(events, capacity * sizeof(Event));
            if (events == NULL) {
                perror("Failed to allocate memory for resized events");
                return NULL;
            }
        }

        // Populate the event
        Event e;
        e.offset = input;
        e.key = hash(input);  // This would be a function that applies some hash to the offset
        e.timestamp = time(NULL);

        events[count] = e;
        count++;
    }

    fclose(fp);

    *((int*)arg) = count;  // Pass back the number of events read
    return (void *)events;
}
```
This code reads integers from standard input, dynamically allocates an array to store them and fills it with 'event' structures. It resizes the array as necessary. It could be extended further to handle errors in parsing the configuration file, implement a caching mechanism, or integrate with a logging service, but doing so would require a more complex design than can be expressed here.
