```javascript
angular.module('app').factory('RefreshService', function($http) {
    var queue = [],
        pending = 0,
        successfulCount = 0,
        unsuccessfulQueue = [];

    return {
        refreshFields: function (fieldsToRefresh, id, url, timeout, concurrencyLimit) {
            for (var i = 0; i < fieldsToRefresh.length; i++) {
                queue.push({fieldName: fieldsToRefresh[i], id: id, url: url});
            }

            this.processQueue(timeout, concurrencyLimit);
        },

        processQueue: function (timeout, concurrencyLimit) {
            while (queue.length && pending < concurrencyLimit) {
                var currentRequest = queue.shift();

                this.sendRequest(currentRequest.fieldName, currentRequest.id, currentRequest.url, timeout);
            }
        },

        sendRequest: function (fieldName, id, url, timeout) {
            pending++;

            $http({method: 'GET', url: url + '/' + id}).then(
                function (response) { // on success
                    successfulCount++;

                    if (response.data[fieldName]) {
                        document.getElementById(fieldName).value = response.data[fieldName];
                    } else {
                        unsuccessfulQueue.push({field: fieldName});
                    }
                },

                function () { // on error
                    unsuccessfulQueue.push({field: fieldName});
                })['finally'](function() {
                    pending--;

                    if (queue.length > 0) {
                        this.processQueue();
                    } else if (pending === 0) {
                        console.log('Successfully refreshed fields: ' + successfulCount);

                        for (var i = 0; i < unsuccessfulQueue.length; i++) {
                            console.log('Failed to refresh field: ' + unsuccessfulQueue[i].field);
                        }
                    }
                });
        },

        notifyParentWindow: function () { // Not implemented in this basic version

        }
    };
});
