#include <stdatomic.h>

typedef struct {
    _Atomic(int) refCount;
    pthread_mutex_t lock;
} ModuleRefCounter;

typedef union {
    int iValue;
    double dValue;
    char* sValue;
} ValueType;

typedef struct {
    char* key;
    ValueType value;
} ConfigEntry;

typedef struct {
    char* name;
    void (*function)(void*);
} Module;

ModuleRefCounter** moduleRefCounters = NULL;
size_t moduleCapacity = 0;
size_t moduleSize = 0;
pthread_mutex_t moduleLock = PTHREAD_MUTEX_INITIALIZER;

void addModule(char* name, void (*function)(void*)) {
    if (name == NULL || function == NULL) {
        return;
    }

    pthread_mutex_lock(&moduleLock);
    if (moduleSize >= moduleCapacity) {
        // resize modules array to double capacity when full
        size_t newCapacity = moduleCapacity == 0 ? 1 : moduleCapacity * 2;
        ModuleRefCounter** newModuleRefCounters = 
            realloc(moduleRefCounters, sizeof(Module*)*newCapacity);

        // check for allocation failure
        if (newModuleRefCounters == NULL) {
            pthread_mutex_unlock(&moduleLock);
            return;
        }

        moduleRefCounters = newModuleRefCounters;
        moduleCapacity = newCapacity;
    }

    Module* module = malloc(sizeof(Module));
    if (module == NULL) {
        pthread_mutex_unlock(&moduleLock);
        return;
    }

    // initialize module
    module->name = strdup(name);
    module->function = function;

    ModuleRefCounter* refCounter = malloc(sizeof(ModuleRefCounter));
    if (refCounter == NULL) {
        free(module->name);
        free(module);
        pthread_mutex_unlock(&moduleLock);
        return;
    }

    // initialize reference counter and mutex lock
    atomic_init(&refCounter->refCount, 1);
    pthread_mutex_init(&refCounter->lock, NULL);

    moduleRefCounters[moduleSize] = refCounter;
    modules[moduleSize++] = module;

    pthread_mutex_unlock(&moduleLock);
}

// ... other functions for adding/removing configuration entries and invoking modules ...
```
