#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <unistd.h>
#include <sys/wait.h>
#include <string.h>
#define MAX_SIZE 500
#define MIN_VERTICES 50
#define MAX_VERTICES 100

typedef struct Edge {
    int id;
    char direction[4]; // "in", "out", "both"
} Edge;

typedef struct Vertex {
    int id;
    char type[7]; // "person", "place", "thing"
    atomic_int edgesCount; 
    Edge *edges;
} Vertex;

// Global variables for graph, cache, and logging.
Vertex **graph;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile;
int nextID = 0; // Generate unique IDs incrementally.

void createGraphAndBackgroundProcess() {
    pthread_mutex_lock(&lock);

    graph = malloc(sizeof(Vertex *) * MAX_SIZE); 

    for (int i = 0; i < MAX_VERTICES; ++i) {
        Vertex *v = malloc(sizeof(Vertex));

        v->id = __atomic_fetch_add(&nextID, 1, __ATOMIC_SEQ_CST);
        // Assign vertex properties here...

        int edgesCount = rand() % 5 + 1;
        v->edgesCount = ATOMIC_VAR_INIT(edgesCount);

        for (int j = 0; j < edgesCount; ++j) {
            Edge *e = malloc(sizeof(Edge));

            e->id = __atomic_fetch_add(&nextID, 1, __ATOMIC_SEQ_CST);
            // Assign edge properties here...

            v->edges[j] = *e;
        }

        graph[i] = v;
    }

    pthread_mutex_unlock(&lock);
}

void backgroundProcess() {
    pid_t pid = fork();
    if (pid == 0) { // This is the child process.
        char *args[] = {"ls", "-lh", "/var/log", NULL};
        execvp(args[0], args);

        exit(EXIT_SUCCESS);
    } else if (pid < 0) {  // Fork failed; exit.
        printf("Fork Failed\n");
        return 1;
    } else { // This is the parent process.
        int status;
        waitpid(pid, &status, 0); // Wait for child process to complete.

        if (WIFEXITED(status)) {
            if (WEXITSTATUS(status) == 0) return 1;
        }
    }

    return 0;
}
```
