typedef struct Record {
    long offset;
    int id;
    double timestamp;
    char filename[256]; // Assumes max length of 256 characters for filenames
} Record;

char *names[] = {"name1", "name2", "name3"};
int names_len = 3;

void logEvent(const char* message) {
    printf("LOG: %s\n", message);
}

Record* createRecords(int count, int *successfulCount) {
    if (count < 1 || successfulCount == NULL) {
        return NULL;
    }

    Record* records = malloc(sizeof(Record) * count);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return NULL;
    }

    clock_t startTime = clock();

    for (int i = 0; i < count; ++i) {
        Record *currentRecord = &records[i];

        currentRecord->offset = i;
        currentRecord->id = i;
        currentRecord->timestamp = ((double)clock() - startTime) / CLOCKS_PER_SEC * 1000.0; // Current time in milliseconds
        strncpy(currentRecord->filename, names[i % names_len], sizeof(currentRecord->filename));

        if (strcmp(currentRecord->filename, "") == 0) {
            logEvent("Fallback name used for filename");
            strncpy(currentRecord->filename, "default", sizeof(currentRecord->filename)); // Fallback placeholder name
        } else {
            char message[128];
            sprintf(message, "Created record with id %d and offset %ld at time %.0f ms", currentRecord->id, currentRecord->offset, currentRecord->timestamp);
            logEvent(message);
        }
    }

    *successfulCount = count;

    return records;
}

void deleteRecords(Record* records, int count) {
    if (records == NULL || count < 1) {
        return;
    }

    for (int i = 0; i < count; ++i) {
        Record *currentRecord = &records[i];

        char message[128];
        sprintf(message, "Deleted record with id %d and offset %ld", currentRecord->id, currentRecord->offset);
        logEvent(message);
    }

    free(records);
}
```
