['Here is a basic implementation of your requirements in C. It uses malloc for dynamic memory allocation. The records are stored in a hash table where each bucket stores all the records with same key value modulo max_key. Collisions are handled by linear probing which may not be optimal but it ensures that all keys remain unique within the allocated array. 

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

Record *records = NULL;
int count = 0, max_count, min_key, max_key, cleanup_interval;
time_t precision;
pthread_mutex_t lock;
pthread_cond_t cond;
volatile int shutdown = 0; // flag to signal the cleanup thread to exit

void *cleanup_func(void *arg) {
    while (!shutdown) {
        sleep(cleanup_interval);
        pthread_mutex_lock(&lock);
        for (int i=0; i<max_count && shutdown == 0; ++i) {
            free(records[i]);
            records[i] = NULL;
        }
        count = 0;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

int initialize(int max, int min, int maxk, time_t prec) {
    if (records != NULL) free(records); // clean up existing records
    records = calloc(max, sizeof(Record));
    if (!records) return -1;

    max_count = max;
    min_key = min;
    max_key = maxk;
    precision = prec;
    pthread_mutex_init(&lock, NULL);
    pthread_cond_init(&cond, NULL);

    srand(time(NULL)); // seed the random number generator

    return 0;
}

int insert() {
    if (count == max_count) return -2;

    int key = rand() % (max_key-min_key+1) + min_key; // generate a unique key within the given range
    double timestamp = time(NULL); 

    pthread_mutex_lock(&lock);
    for (;;) {
        int index = key % max_count;
        while (records[index]) {
            if (++index == max_count) index = 0; // wrap around to the start of the array
        }

        records[index] = malloc(sizeof(Record));
        if (!records[index]) {
            pthread_mutex_unlock(&lock);
            return -1; // allocation failed
        }

        records[index]->key = key;
        records[index]->timestamp = timestamp;
        records[index]->offset = 0; // default value, can be adjusted as required
        ++count;
        pthread_mutex_unlock(&lock);
        return 0;
    }
}

int query() {
    pthread_mutex_lock(&lock);
    int cnt = count;
    pthread_mutex_unlock(&lock);

    return cnt; // returns the total number of records currently allocated
}

void cleanup() {
    shutdown = 1;
    pthread_cond_signal(&cond);
}
```
Please note that this code does not handle insertion and retrieval under high load conditions. You may need to use a lock-free data structure or concurrent data structures for better performance. Also, error handling is minimal in this example. Real-world applications should be more robust and include checks for invalid arguments, system call failures, etc.
']

