```c
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} record;

// A simple linked list of batches to handle varying batch sizes.
typedef struct BatchNode {
    size_t batchSize; // Size of current batch.
    record* records;  // Array of records for this batch.
    struct BatchNode* next; // Pointer to the next batch.
} BatchNode;

// Function to dynamically allocate and manage memory for batches.
BatchNode* createBatches(size_t batchSize) {
    if (batchSize <= 0) {
        fprintf(stderr, "Error: invalid batch size.\n");
        return NULL;
    }

    BatchNode *head = malloc(sizeof(*head)); // Allocate memory for the head node.
    if (!head) {
        fprintf(stderr, "Error: allocation failed.\n");
        return NULL;
    }

    head->batchSize = batchSize; 
    head->records = malloc(batchSize * sizeof(*head->records)); // Allocate memory for the records.
    if (!head->records) {
        fprintf(stderr, "Error: allocation failed.\n");
        free(head);
        return NULL;
    }

    head->next = createBatches(batchSize * 2); // Recursively allocate memory for the next batch.

    return head;
}

// Function to release allocated memory recursively.
void destroyBatches(BatchNode* batches) {
    if (!batches) return;

    free(batches->records); // Free the records for this batch.
    destroyBatches(batches->next); // Recursively free memory for the next batch.
    free(batches); // Finally, free the head node.
}
```

This is a basic example and does not include all features requested. For full implementation, you would need to integrate this with your application logic and error checking/handling mechanisms. Make sure to use memory pools for record structures within the same batch for better efficiency in memory allocation/deallocation, dynamically adjust batch sizes based on workload patterns and system resources, implement filtering/processing of records, etc.
