    record* new_record = malloc(sizeof(record));

    if (new_record == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    srand((unsigned int)time(NULL));
    new_record->offset = rand();
    new_record->identifier = rand() % 100;
    new_record->timestamp = (double)rand() / RAND_MAX * 100.0;

    int filenameIndex = rand() % MAX_FILENAMES;
    strcpy(new_record->filename, filenames[filenameIndex]);

    pthread_mutex_lock(&mutex);
    totalFilenameLength += strlen(new_record->filename);

    if (totalFilenameLength > memoryLimit) {
        printf("Total memory usage exceeded the limit\n");
        free(new_record);
        pthread_exit(NULL);
    }

    logRecord(new_record, "Created");
    pthread_mutex_unlock(&mutex);

    return new_record;
}

void deleteRecord(void *args) {
    record* r = (record*) args;

    if (r == NULL) return;

    pthread_mutex_lock(&mutex);
    totalFilenameLength -= strlen(r->filename);
    logRecord(r, "Deleted");
    free(r);
    pthread_mutex_unlock(&mutex);
}

int main() {
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < MAX_FILENAMES; ++i) {
        totalFilenameLength += strlen(filenames[i]);
    }

    memoryLimit = totalFilenameLength * GROWTH_FACTOR;

    pthread_t threads[10];

    for (size_t i = 0; i < 10; ++i) {
        if(pthread_create(&threads[i], NULL, createRecord, NULL)) {
            printf("Error creating thread\n");
            return 1;
        }
    }

    for (size_t i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```
