#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char* key;
    int value;
    struct Node* next;
} Node;

Node* list = NULL; // global variable, not thread-safe

// Insert a new node, duplicating the given key string
void insert(const char* key, int value) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) exit(1); // handle memory allocation failure 

    size_t len = strlen(key);
    node->key = malloc(len + 1);
    if (node->key == NULL) exit(1); // handle memory allocation failure 
    strcpy(node->key, key);

    node->value = value;
    node->next = list;
    list = node;
}

// Delete a node by its key
void delete_by_key(const char* key) {
    Node** prev_next_ptr = &list;
    while (*prev_next_ptr != NULL) {
        if (strcmp((*prev_next_ptr)->key, key) == 0) {
            // delete this node
            Node* temp = *prev_next_ptr;
            *prev_next_ptr = temp->next;
            free(temp->key);
            free(temp);
        } else {
            prev_next_ptr = &((*prev_next_ptr)->next);
        }
    }
}

// Search for a node by its key, returns NULL if not found
Node* search_by_key(const char* key) {
    Node* node = list;
    while (node != NULL) {
        if (strcmp(node->key, key) == 0) {
            return node; // found it
        }
        node = node->next;
    }
    return NULL; // not found
}

// Update the integer value of a node if it already exists
void update_by_key(const char* key, int newValue) {
    Node* node = search_by_key(key);
    if (node != NULL) {
        node->value = newValue; // update value 
    }
}
