['Here is an example of how you might implement this in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure for node in linked list
typedef struct Node {
    double value;
    bool active;
    struct Node* next;
} Node;

// Structure for element
typedef struct Element {
    float flt;
    int integer;
    char chr;
} Element;

void initArraysAndList(double** dblArray, char** charArray, Element*** elemArray, Node** head) {
    // Allocate memory for arrays and list
    *dblArray = malloc(3 * sizeof(double));
    *charArray = malloc(3 * sizeof(char));
    *elemArray = malloc(3 * sizeof(Element*));

    for (int i = 0; i < 3; i++) {
        (*dblArray)[i] = 0.0;
        (*charArray)[i] = 'a';

        // Allocate memory for elements in array
        (*elemArray)[i] = malloc(sizeof(Element));
        (*elemArray)[i]->flt = 0.0f;
        (*elemArray)[i]->integer = 0;
        (*elemArray)[i]->chr = 'a';
    }

    // Allocate memory for list head
    *head = malloc(sizeof(Node));
    (*head)->value = 0.0;
    (*head)->active = true;
    (*head)->next = NULL;
}

void deleteArraysAndList(double** dblArray, char** charArray, Element*** elemArray, Node** head) {
    // Deallocate memory for arrays and list
    free(*dblArray);
    free(*charArray);

    for (int i = 0; i < 3; i++) {
        free((*elemArray)[i]);
    }

    free(*elemArray);

    Node *current = *head, *temp;
    while (current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
    }

    *dblArray = NULL;
    *charArray = NULL;
    *elemArray = NULL;
    *head = NULL;
}

void serializeToFile(double* dblArray, char* charArray, Element** elemArray, Node* head) {
    FILE* file = fopen("data.bin", "wb");

    // Serialize arrays and list to file
    for (int i = 0; i < 3; i++) {
        fwrite(&dblArray[i], sizeof(double), 1, file);
        fwrite(&charArray[i], sizeof(char), 1, file);

        // Serialize element to file
        fwrite(elemArray[i], sizeof(Element), 1, file);
    }

    Node* current = head;
    while (current != NULL) {
        // Serialize node to file
        fwrite(&current->value, sizeof(double), 1, file);
        fwrite(&current->active, sizeof(bool), 1, file);

        current = current->next;
    }

    fclose(file);
}

void deserializeFromFile(double** dblArray, char** charArray, Element*** elemArray, Node** head) {
    FILE* file = fopen("data.bin", "rb");

    // Deallocate existing memory for arrays and list
    deleteArraysAndList(dblArray, charArray, elemArray, head);

    // Allocate new memory for arrays and list
    initArraysAndList(dblArray, charArray, elemArray, head);

    // Deserialize arrays and list from file
    for (int i = 0; i < 3; i++) {
        fread(&(*dblArray)[i], sizeof(double), 1, file);
        fread(&(*charArray)[i], sizeof(char), 1, file);

        // Deserialize element from file
        fread((*elemArray)[i], sizeof(Element), 1, file);
    }

    Node** current = head;
    while (!feof(file)) {
        // Allocate memory for new node
        *current = malloc(sizeof(Node));

        fread(&(*current)->value, sizeof(double), 1, file);
        fread(&(*current)->active, sizeof(bool), 1, file);

        current = &(*current)->next;
    }

    // Remove last dummy node
    Node* temp = *head;
    while (temp->next != NULL) {
        temp = temp->next;
    }
    free(temp);
    (*current) = NULL;

    fclose(file);
}
```
This is a very basic example and may not meet all performance and memory usage requirements. In a real-world scenario, you would likely use more efficient data structures and algorithms, and ensure that error checking is in place to handle potential issues with file I/O or other system resources. Furthermore, this code does not manage memory for the 'char' type identifiers as per your request because it was unclear how they should be handled. You may need to modify this example based on your specific requirements.
