#include <string.h>

// Double array
double* readDoubleArray(const char* filename, int* size) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open %s\n", filename);
        return NULL;
    }

    double number;
    *size = 0;
    while (fscanf(file, "%lf", &number) == 1) {
        (*size)++;
    }

    rewind(file);
    double* array = malloc(*size * sizeof(double));
    for (int i = 0; i < *size; i++) {
        fscanf(file, "%lf", &array[i]);
    }

    fclose(file);
    return array;
}

// Char array
char* readCharArray(const char* filename, int* size) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open %s\n", filename);
        return NULL;
    }

    // Assuming each line is a new string
    char buffer[256];
    *size = 0;
    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        (*size) += strlen(buffer);
    }

    rewind(file);
    char* array = malloc(*size + 1); // Extra space for null terminator
    int offset = 0;
    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        strcpy(&array[offset], buffer);
        offset += strlen(buffer);
    }

    fclose(file);
    return array;
}

// Struct Array
