    for (int i = 0; i < MAX_TAGS && task->tags[i] != NULL; ++i) {
        fprintf(file, "%s\n", task->tags[i]); // Write each tag to file
    }
}
Task* deserializeTask(FILE* file) {
    char nameBuffer[256], tagBuffer[256];
    time_t deadline;
    int priority;

    if (fgets(nameBuffer, 256, file) == NULL) return NULL; // Read the name
    fscanf(file, "%ld\n%d\n", &deadline, &priority); // Read the deadline and priority

