['Your task involves a lot of complex features which will take extensive coding to implement. Here is a basic implementation of a `DynamicValueGenerator` class with some of your requirements, but without thread safety and configuration integration. Thread safety can be achieved using locks or other synchronization mechanisms such as Monitor or SemaphoreSlim depending on the use case. 

```csharp
using System;
using System.Collections.Generic;
using System.Threading;

public class DynamicValueGenerator<T> where T : IComparable<T>
{
    private List<(T min, T max)> _ranges = new List<(T, T)>();
    private Random _random = new Random();
    private object _syncRoot = new object();

    public void AddRange(T min, T max)
    {
        lock (_syncRoot)
        {
            _ranges.Add((min, max));
        }
    }

    public void RemoveRange(T min, T max)
    {
        lock (_syncRoot)
        {
            _ranges.Remove((min, max));
        }
    }

    public T GenerateValue()
    {
        (T min, T max) range;

        lock(_syncRoot)
        {
            if (_ranges.Count == 0) 
                throw new InvalidOperationException("No ranges defined");

            int index = _random.Next(0, _ranges.Count);
            range = _ranges[index];
        }

        if (typeof(T) == typeof(float))
        {
            double randomValue = 
                min + (_random.NextDouble() * (max - min));

            return (T)Convert.ChangeType(randomValue, typeof(T));
        }
        else if (typeof(T) == typeof(int))
        {
            int randomValue = _random.Next((int)(object)range.min, 1 + (int)(object)range.max);
            return (T)Convert.ChangeType(randomValue, typeof(T));
        }

        throw new NotSupportedException("Unsupported type");
    }
}
```
