#include <string.h>

typedef struct Transaction {
    char* description;
    double amount;
    time_t timestamp;
} Transaction;

void handleError(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

Transaction* createTransactionsFromFile(FILE* file, int numOfTransactions) {
    if (file == NULL || numOfTransactions < 1) handleError("Invalid parameters");

    Transaction* transactions = malloc(numOfTransactions * sizeof(Transaction));
    if (transactions == NULL) handleError("Memory allocation failed");

    char buffer[256];
    for (int i = 0; i < numOfTransactions && fgets(buffer, sizeof(buffer), file); ++i) {
        // Assuming descriptions are separated by commas.
        char* description = strtok(buffer, ",");
        if (description == NULL) handleError("Invalid transaction format");

        char* amountStr = strtok(NULL, ",");
        if (amountStr == NULL) handleError("Invalid transaction format");

        errno = 0;
        double amount = strtod(amountStr, NULL);
        if (errno != 0 || amount < 0.01) handleError("Invalid amount value"); // 0.01 is the minimum valid amount.

        time_t timestamp = time(NULL);
        if (timestamp == -1) handleError("Failed to get current time");

        transactions[i].description = strdup(description);
        transactions[i].amount = amount;
        transactions[i].timestamp = timestamp;
    }

    return transactions;
}

double findMaxAmount(Transaction* transactions, int numOfTransactions) {
    if (transactions == NULL || numOfTransactions < 1) handleError("Invalid parameters");

    double maxAmount = 0.0;
    for (int i = 0; i < numOfTransactions; ++i) {
        if (transactions[i].amount > maxAmount) {
            maxAmount = transactions[i].amount;
        }
    }

    return maxAmount;
}

void freeTransactionMemory(Transaction* transactions, int numOfTransactions) {
    for (int i = 0; i < numOfTransactions; ++i) {
        free(transactions[i].description);
    }
    free(transactions);
}
