```C
#include <stdio.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>
#include <errno.h>

typedef struct {
    int value;
} record;

typedef struct {
    long total_memory;
    char* serialization_path;
    int min_value, max_value;
} config;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
atomic_long memory_usage = 0;
config *current_config = NULL;
const long MEMORY_LIMIT = 1024*1024*1024; // 1GB limit for the example

void* allocate(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Allocation failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    atomic_fetch_add(&memory_usage, size);
    return ptr;
}

void deallocate(void* ptr, size_t size) {
    free(ptr);
    atomic_fetch_sub(&memory_usage, size);
}

int rand_range(int min, int max) {
    return min + (rand() % (max - min + 1));
}

record* create_record(config* config) {
    if (atomic_load(&memory_usage) > MEMORY_LIMIT) {
        fprintf(stderr, "Memory limit exceeded\n");
        return NULL;
    }

    record *rec = allocate(sizeof(*rec));
    rec->value = rand_range(config->min_value, config->max_value);

    return rec;
}

void serialize_record(FILE* file, const record* rec) {
    fprintf(file, "%d\n", rec->value);
}

void update_config(config *new_config) {
    pthread_mutex_lock(&lock);

    if (current_config != NULL) deallocate(current_config, sizeof(*current_config));

    current_config = allocate(sizeof(*new_config));
    memcpy(current_config, new_config, sizeof(*new_config));

    pthread_mutex_unlock(&lock);
}
```

