    double timestamp;
} record_t;

// mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int write_records(FILE *f, const record_t *r, size_t n) {
    pthread_mutex_lock(&lock);

    if (fwrite(r, sizeof(*r), n, f) != n) {
        // partial write error handling
        perror("Error writing records to file");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

record_t *read_records(FILE *f, size_t n) {
    record_t *r = malloc(n * sizeof(*r));

    if (r == NULL) {
        perror("Memory allocation error");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    if (fread(r, sizeof(*r), n, f) != n && !feof(f)) {
        // partial read error handling
        perror("Error reading records from file");
        free(r);
        r = NULL;
    }

    pthread_mutex_unlock(&lock);
    return r;
}

record_t *allocate_records(size_t n) {
