['Here's a basic example of how you might solve this problem using pthread_mutex for thread safety, gettimeofday() for time stamping, malloc() and free() for memory management. We'll add the monitoring by simply dividing the current allocated size by the total limit (100MB).

Please note that it's a simplified model and might need refinement according to specific requirements or limitations of the system you are using:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
long allocated = 0;
const long limit = 100 * 1024 * 1024; // 100 MB in bytes

record* allocate(int size) {
    pthread_mutex_lock(&mutex);
    if (allocated + size > limit) {
        printf("Error: Exceeding memory limit.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    record* data = malloc(size * sizeof(record));
    if (data == NULL) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    allocated += size;

    for (int i = 0; i < size; ++i) {
        struct timeval tv;
        gettimeofday(&tv,NULL);

        data[i].offset = rand(); // Replace with your own logic for offset generation.
        data[i].key = rand(); // Replace with your own logic for key generation.
        data[i].timestamp = tv.tv_sec + (double)tv.tv_usec / 1000000; // Current time in seconds since the epoch.
    }

    pthread_mutex_unlock(&mutex);
    return data;
}

void deallocate(record* data, int size) {
    pthread_mutex_lock(&mutex);
    free(data);
    allocated -= size;
    pthread_mutex_unlock(&mutex);
}

double memoryUsage() {
    return ((double)allocated / limit) * 100;
