typedef struct {
    record* array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordArray;

RecordArray* createArray(size_t initialCapacity) {
    RecordArray* arr = malloc(sizeof(RecordArray));
    if (arr == NULL) {
        // Handle error: Memory allocation failed
    }

    arr->array = calloc(initialCapacity, sizeof(record));
    if (arr->array == NULL) {
        // Handle error: Memory allocation failed
    }

    arr->capacity = initialCapacity;
    arr->count = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void resizeArray(RecordArray* arr, size_t newCapacity) {
    record* newArray = realloc(arr->array, newCapacity * sizeof(record));
    if (newArray == NULL && newCapacity != 0) {
        // Handle error: Memory allocation failed
    }

    arr->array = newArray;
    arr->capacity = newCapacity;
}

void addRecord(RecordArray* arr, int key, int value, bool allowDuplicates) {
    pthread_mutex_lock(&arr->lock);

    if (!allowDuplicates && findKey(arr, key) != -1) {
        // Handle error: Duplicate key is not allowed
    } else {
        if (arr->count == arr->capacity) {
            resizeArray(arr, arr->capacity * 2);
        }

        arr->array[arr->count].offset = arr->count;
        arr->array[arr->count].key = key;
        arr->array[arr->count].value = value;
        arr->count++;
    }

    pthread_mutex_unlock(&arr->lock);
}

int findKey(RecordArray* arr, int key) {
    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->array[i].key == key) {
            return i;
        }
    }

    return -1;  // Key not found
}
