        pthread_mutex_lock(&allocate_mutex);
        allocated_memory -= malloc_usable_size(ptr);
        pthread_mutex_unlock(&allocate_mutex);
    }
}

void* safe_malloc(size_t size) {
    void* ptr = NULL;
    pthread_mutex_lock(&allocate_mutex);
    if (allocated_memory + size < MAX_MEMORY_MB * 1024 * 1024) {
        allocated_memory += size;
        ptr = malloc(size);
    } else {
        fprintf(stderr, "Memory allocation failed: Maximum memory limit reached.\n");
    }
    pthread_mutex_unlock(&allocate_mutex);
    return ptr;
}

void manage_memory() {
    size_t mem_limit = MAX_MEMORY_MB * 1024 * 1024;
    while (allocated_memory >= mem_limit) {
        // sleep for a short period before trying again
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 5e8 };
        nanosleep(&ts, NULL);
    }
}

log_entry_t* create_log_entry(int status) {
    log_entry_t* entry = safe_malloc(sizeof(log_entry_t));
    if (entry != NULL) {
        time_t now;
        time(&now);
        atomic_store_explicit(&entry->timestamp, (unsigned long long) now, memory_order_relaxed);
        entry->status = status;
        size_t message_size = 100; // randomly generated string length
        entry->message = safe_malloc(message_size * sizeof(char));
    }
    return entry;
}
```
This code provides a basic memory manager that ensures the allocated total doesn't exceed a predefined limit. It uses mutexes to prevent race conditions when modifying the total allocation count, and includes error handling for failed allocations. Note this is just a simple example. A production-grade solution would likely involve more complex data structures, better memory management strategies, and thorough testing.
']

['Here's a simple implementation of what you asked for in C. It includes a custom allocation error handling mechanism using errno to check if malloc failed due to insufficient memory or any other issue. It also includes two different allocation strategies (speed-optimized and space-optimized) which can be selected by setting the 'strategy' parameter:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    long offset;
    int key;
    double timestamp;
} record_t;

record_t *allocate_records(size_t count, int strategy) {
    if (count == 0) return NULL;

    size_t blockSize = sizeof(record_t);

    // Optimize for speed or space based on strategy parameter
    switch (strategy) {
        case 1: // Speed optimization - Allocate all at once
            errno = 0;
            record_t *records = malloc(blockSize * count);
            if (errno == ENOMEM || records == NULL) {
                perror("Memory allocation failed");
                return NULL;
            }

            // Initialize keys and timestamps
            srand(time(NULL));
            for (size_t i = 0; i < count; ++i) {
                records[i].offset = i * sizeof(record_t);
                records[i].key = rand() % INT_MAX; // Specify your range here
                records[i].timestamp = time(NULL);
            }

            return records;
        case 2: { // Space optimization - Allocate one at a time
            record_t *records = malloc(blockSize);
            if (errno == ENOMEM || records == NULL) {
                perror("Memory allocation failed");
                return NULL;
            }

            for (size_t i = 1; i < count; ++i) {
                errno = 0;
                record_t *temp = realloc(records, blockSize * (i + 1));

                if (errno == ENOMEM || temp == NULL) {
                    perror("Memory allocation failed");
                    free(records);
                    return NULL;
                } else {
                    records = temp;
                }
            }

            // Initialize keys and timestamps
            srand(time(NULL));
            for (size_t i = 0; i < count; ++i) {
                records[i].offset = i * sizeof(record_t);
                records[i].key = rand() % INT_MAX; // Specify your range here
                records[i].timestamp = time(NULL);
            }

            return records;
        }
    }

    fprintf(stderr, "Invalid strategy. Choose 1 for speed optimization or 2 for space optimization.\n");
    return NULL;
}
```

