```c
List* DataProcessor(int numRecords, int minOffset, int maxOffset, long timestampMin, long timestampMax, int* keys) {
    srand(time(NULL));  // Seed the random number generator.
    List *list = (List*)malloc(sizeof(List));
    if (!list) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);  // Initialize the lock.

    for (int i = 0; i < numRecords; ++i) {
        Node *newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed.\n");
            continue;
        }

        newNode->key = keys ? keys[i % sizeof(keys)] : rand() % (maxOffset - minOffset + 1) + minOffset;
        newNode->next = NULL;

        pthread_mutex_lock(&list->lock);  // Lock for thread safety.
        if (!list->head) {
            list->head = newNode;
        } else {
            Node *current = list->head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newNode;
        }
        pthread_mutex_unlock(&list->lock);  // Unlock.
    }

    return list;
}
