#include <boost/filesystem.hpp>
#include <boost/iostreams/device/mapped_file.hpp>
#include <boost/asio.hpp>
#include <openssl/sha.h>
#include <fstream>
#include <string>

const int CHUNK_SIZE = 1024 * 1024; // 1MB chunk size

std::string computeSha256(const std::string& filePath) {
    boost::iostreams::mapped_file mmap(filePath, boost::iostreams::mapped_file::readonly);

    SHA256_CTX ctx;
    SHA256_Init(&ctx);

    unsigned char hash[SHA256_DIGEST_LENGTH];
    for (size_t i = 0; i < mmap.size(); i += CHUNK_SIZE) {
        size_t chunkSize = std::min<size_t>(CHUNK_SIZE, mmap.size() - i);
        SHA256_Update(&ctx, (unsigned char*)mmap.const_data() + i, chunkSize);
    }

    SHA256_Final(hash, &ctx);

    std::stringstream ss;
    for(int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
    } 

    return ss.str();
}

