```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct event {
    long offset;
    int key;
    double timestamp;
} Event;

void* create_event(void *arg) {
    int range = *(int*)arg;
    int key = rand() % (range + 1);
    Event* new_event = malloc(sizeof(Event));

    if (!new_event) {
        printf("Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    new_event->offset = 0;
    new_event->key = key;
    new_event->timestamp = time(NULL);

    return new_event;
}

void* process_events(void *arg) {
    Event** events = (Event**)arg;
    int i = 0, max_i = -1;
    for (; events[i] != NULL; ++i) {}

    qsort(events, i, sizeof(Event*), compare);

    // Find the event with largest integer key. Handle duplicates by checking next event.
    while (++max_i < i - 1 && events[max_i]->key == events[max_i + 1]->key) {}

    printf("Largest key: %d\n", events[max_i]->key);
}

int compare(const void *a, const void *b) {
    Event* eventA = *(Event**)a;
    Event* eventB = *(Event**)b;

    return (eventA->key > eventB->key) - (eventA->key < eventB->key);
}

int main() {
    srand(time(NULL));
    int max_events = 100, key_range = 10;

    Event** events = malloc(sizeof(Event*) * (max_events + 1));
    pthread_t threads[max_events];

    for (int i = 0; i < max_events; ++i) {
        if (pthread_create(&threads[i], NULL, create_event, &key_range)) {
            printf("Failed to create thread\n");
            return 1;
        }
    }

    for (int i = 0; i < max_events; ++i) {
        if (pthread_join(threads[i], NULL)) {
            printf("Failed to join thread\n");
            return 1;
        }

        events[i] = create_event(&key_range);
    }

    pthread_t process_thread;
    if (pthread_create(&process_thread, NULL, process_events, &events)) {
        printf("Failed to create thread\n");
        return 1;
    }

    if (pthread_join(process_thread, NULL)) {
        printf("Failed to join thread\n");
        return 1;
    }

    for (int i = 0; i < max_events; ++i) {
        free(events[i]);
    }

    free(events);
    return 0;
}
```

Please note, this is just a basic implementation. There are still many things to improve or consider such as:
