        double seconds_since_epoch = (double)ts.tv_sec + ((double)ts.tv_nsec / 1e9);
        records[i].timestamp = seconds_since_epoch + ((rand() % 1000 - 500) / 1e3);

        sprintf(records[i].identifier, "Record%d", i + 1);  // example identifier
