Record_t* allocateAndInitializeRecords(size_t count, int maxValue) {
    // Allocate memory for the records array with a single allocation
    Record_t *records = (Record_t*) malloc(count * sizeof(Record_t));

    if (records == NULL) {
        return NULL;  // Failed to allocate memory
    }

    // Lock the mutex before accessing the records array for thread safety
    pthread_mutex_lock(&mutex);

    // Initialize each record with a random value within specified range
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % maxValue + 1;  // Add 1 to avoid zero
    }

    // Unlock the mutex after accessing the records array
    pthread_mutex_unlock(&mutex);

    return records;
}

void deallocateRecords(Record_t* records) {
    // Lock the mutex before freeing memory to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Free the allocated memory for the records array
    free(records);

    // Unlock the mutex after freeing memory
    pthread_mutex_unlock(&mutex);
}
