```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#define MAX_SIZE 100
#define MAX_RECORDS 50

typedef struct {
    int value;
    char* str;
} Record;

// Custom memory pool
Record* records[MAX_RECORDS];
long offsets[MAX_SIZE];
int keys[MAX_SIZE];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initMemory(size_t size) {
    if (size > MAX_SIZE || size <= 0) {
        // Handle error
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < size; ++i) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 1000;
    }

    // Reuse memory from the pool if available
    for (int i = 0; i < size && i < MAX_RECORDS; ++i) {
        Record* rec = records[i];
        if (!rec) {
            rec = malloc(sizeof(Record));
            records[i] = rec;
        }

        int value;
        do {
            value = rand() % 1000 + 1;
            for (int j = 0; j < i; ++j) {
                if (records[j]->value == value) {
                    // Handle duplicate values
                    break;
                }
            }
        } while (/*duplicate*/);

        rec->value = value;
        size_t strLen = value + 1; // +1 for null terminator
        rec->str = malloc(strLen);
        memset(rec->str, value, strLen - 1); // ASCII representation of the character corresponding to the integer value
        rec->str[strLen - 1] = '\0';
    }
    pthread_mutex_unlock(&mutex);
