    }

    // allocate memory for 'double' precision floats and unsigned long timestamps
    double *precisionFloats = malloc(sizeof(double) * 1024);
    unsigned long *timestamps = malloc(sizeof(unsigned long) * 1024);

    if (precisionFloats == NULL || timestamps == NULL) {
