                free(logEntries[j].message);
            }

            free(offsetValues);
            free(keys);
            free(precisionFloats);
            free(timestamps);
            free(logEntries);
            return;
        }

        // generate a random string of fixed length for the message content
        for (int j = 0; j < messageLength; j++) {
            logEntries[i].message[j] = 'a' + rand() % 26;  // random lowercase letter
        }

        logEntries[i].message[messageLength] = '\0';  // null-terminate the string
