#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* fileName;
    off_t offset;
    int refCount;
    char* buffer;
} Inode;

Inode* inodes = NULL;
char** fileNames = NULL;
off_t* offsets = NULL;
int numFiles = 0, sizeFileArray = 100;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* logFile;

void allocateArrays() {
    inodes = calloc(sizeFileArray, sizeof(Inode));
    fileNames = calloc(sizeFileArray, sizeof(char*));
    offsets = calloc(sizeFileArray, sizeof(off_t));
}

int createInode(const char* name) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < numFiles; ++i) 
        if (strcmp(fileNames[i], name) == 0) // Check if file already exists
            return -1;

    if (numFiles == sizeFileArray) { // If array is full, reallocate with double the size
        inodes = realloc(inodes, 2 * sizeFileArray * sizeof(Inode));
        fileNames = realloc(fileNames, 2 * sizeFileArray * sizeof(char*));
        offsets = realloc(offsets, 2 * sizeFileArray * sizeof(off_t));

        sizeFileArray *= 2;
    }

    inodes[numFiles].fileName = strdup(name); // Allocate memory for file name and copy string
    offsets[numFiles] = rand() % 10000; // Assign random offset

    pthread_mutex_unlock(&mutex);
    return numFiles++; // Return index of newly created inode
}

void writeToFile(int fileIndex, int numChars) {
    if (fileIndex >= numFiles || fileIndex < 0) {
        fprintf(logFile, "Invalid file index\n");
        return;
    }

    // Lock and unlock the mutex before and after writing to prevent concurrent writes
    pthread_mutex_lock(&mutex);

    char* buffer = inodes[fileIndex].buffer;
    if (numChars > 0) {
        for(int i=0; i<numChars; ++i) {
            size_t len = strlen(buffer);

            // Reallocate memory to accommodate new character and a null terminator
            buffer = realloc(buffer, (len+2)*sizeof(*buffer));

            buffer[len] = 'a' + rand() % 26; // Append a random character to buffer
            buffer[len+1] = '\0'; // Null-terminate the string
        }
    }

    inodes[fileIndex].buffer = buffer;
    pthread_mutex_unlock(&mutex);
}

void clearFile(int fileIndex) {
    if (fileIndex >= numFiles || fileIndex < 0) {
        fprintf(logFile, "Invalid file index\n");
        return;
    }

    // Free memory allocated to buffer and reset pointer
    free(inodes[fileIndex].buffer); 
    inodes[fileIndex].buffer = NULL;
}

void destroy() {
    for (int i = 0; i < numFiles; ++i) {
        free(fileNames[i]); // Free memory allocated to file names

        if (inodes[i].buffer != NULL) 
            free(inodes[i].buffer); // Free memory allocated to buffer if not already freed
    }

    // Free arrays of structures and buffers
    free(inodes); inodes = NULL;
    free(fileNames); fileNames = NULL;
    free(offsets); offsets = NULL;

    fclose(logFile);
}
```
Please note that, this is a simplified version of the code and does not include all requirements such as dynamic memory reallocation strategy, cache eviction policy, thread safety, error handling, logging mechanism etc.
