} Record;

AES_KEY aesKey;
int initialized = 0;

void initializeAES(const char *password) {
    unsigned char key[SHA_DIGEST_LENGTH];

    SHA1((unsigned char*) password, strlen(password), key);
    AES_set_encrypt_key(key, 256, &aesKey);
    initialized = 1;
}

void cleanupAES() {
    memset(&aesKey, 0, sizeof(aesKey));
    initialized = 0;
}

int randomValue[MAX_RECORDS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
long offsetArray[MAX_SIZE];
int keyArray[MAX_SIZE];
Record recordArray[MAX_RECORDS];
char *buffer[MAX_RECORDS];

void initialize(size_t offsetSize, size_t keySize, size_t recordSize) {
    if (offsetSize > MAX_SIZE || keySize > MAX_SIZE || 
        recordSize > MAX_RECORDS) return; // Error: invalid input size

    for (int i = 0; i < recordSize; ++i) randomValue[i] = -1;
    memset(offsetArray, 0, offsetSize * sizeof(long));
    memset(keyArray, 0, keySize * sizeof(int));
    memset(recordArray, 0, recordSize * sizeof(Record));
    for (int i = 0; i < recordSize; ++i) {
        buffer[i] = (char*) malloc(256); // Allocate a buffer of sufficient size for 'char' string
        if (!buffer[i]) return; // Error: memory allocation failed
    }
}

void populateRecords(size_t recordSize) {
    int value;

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < recordSize; ++i) {
        do {
            value = rand() % 1000 + 1; // Generate a random integer between 1 and 1000
        } while (randomValue[value] != -1); // Ensure no duplicates

        sprintf(buffer[i], "String%d", value);
        recordArray[i].string = buffer[i];
        randomValue[value] = i;
    }
    pthread_mutex_unlock(&mutex);
}

void printRecords(size_t recordSize) {
    for (int i = 0; i < recordSize; ++i) {
        printf("Record: %d, String: %s\n", recordArray[i].value, recordArray[i].string);
    }
}

void cleanup(size_t recordSize) {
    for (int i = 0; i < recordSize; ++i) free(buffer[i]); // Free the memory of 'char' string

    memset(offsetArray, 0, MAX_SIZE * sizeof(long));
    memset(keyArray, 0, MAX_SIZE * sizeof(int));
    memset(recordArray, 0, MAX_RECORDS * sizeof(Record));
    for (int i = 0; i < recordSize; ++i) randomValue[i] = -1;
}

