Protocol* load_protocol(const char* libpath, const char* entrypoint) {
    void *handle = dlopen(libpath, RTLD_LAZY);
    if (!handle) return NULL; // Handle error here...

    Protocol* (*create)() = dlsym(handle, entrypoint);
    if (dlerror()) return NULL; // Handle error here...

    return create();
}

// Maintain a list of loaded protocols
typedef struct {
    pthread_mutex_t lock;
    Protocol** protocols;
    int count;
} Protocols;

Protocols protocols = {PTHREAD_MUTEX_INITIALIZER, NULL, 0};

// Add a protocol to the list
void add_protocol(Protocol* proto) {
    pthread_mutex_lock(&protocols.lock);

    protocols.count++;
    protocols.protocols = realloc(protocols.protocols, protocols.count * sizeof(Protocol*));
    protocols.protocols[protocols.count - 1] = proto;

    pthread_mutex_unlock(&protocols.lock);
}
