["Here is a high level overview of how you could implement these requirements in C using pthreads for threading, glib's GHashTable to manage our cache, and POSIX threads for managing memory allocation failures. This code doesn't cover all the details required for this task (such as parsing standard input), but it should give a good starting point:

```C
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <glib.h>
#include <assert.h>

// Structure to hold our records
typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

// Function to create a new record with random values within specified ranges
Record* new_record(int key) {
    Record* rec = malloc(sizeof(Record));
    assert(rec != NULL); // Check memory allocation failure

    rec->offset = rand(); // Fill in fields with random values
    rec->key = key;
    rec->timestamp = time(NULL); 
    return rec;
}

// Global hash table to store our cache
GHashTable* cache;
pthread_mutex_t lock; // Lock for thread safety

void init_cache() {
    cache = g_hash_table_new(g_direct_hash, g_direct_equal);
    assert(cache != NULL);  // Check memory allocation failure

    pthread_mutex_init(&lock, NULL); // Initialize lock for thread safety
}

// Function to add a record to the cache
void add_to_cache(int key, Record* rec) {
    if (g_hash_table_size(cache) >= 10000) {
        gpointer oldKey = g_hash_table_lookup(cache, NULL); // Get oldest entry
        assert(oldKey != NULL); // Should always be true

        gpointer removedVal = g_hash_table_remove(cache, oldKey); 
        free(removedVal); // Evict least recently used record
    }

    pthread_mutex_lock(&lock); // Lock for thread safety
    g_hash_table_insert(cache, &key, rec); // Add to cache
    pthread_mutex_unlock(&lock); // Unlock
}

// Function to fetch a record from the cache
Record* get_from_cache(int key) {
    Record* rec = g_hash_table_lookup(cache, &key); 

    if (rec != NULL) {
        add_to_cache(key, rec); // Move to end of LRU list if in cache
    }

    return rec;
}
```
This code assumes that the external data source will notify when it updates key-value pairs. When this happens, you can refresh your cache with new or updated records as needed:

```C
// Function to handle updates from external data source
void handle_external_update(int key, Record* rec) {
    pthread_mutex_lock(&lock); // Lock for thread safety

    gpointer oldRec = g_hash_table_lookup(cache, &key);
    if (oldRec != NULL) {
        free(oldRec); 
    }

    add_to_cache(key, rec);

    pthread_mutex_unlock(&lock); // Unlock
}
```

Remember to free the cache and destroy the mutex when you're done with it:

```C
g_hash_table_destroy(cache);
pthread_mutex_destroy(&lock);
``` 

