using System;
using System.Collections.Generic;
using System.Threading;
using System.Linq;
using System.IO;

public class DynamicValueGenerator
{
    private static readonly object _lock = new object(); // for synchronization 
    private List<dynamic> ranges; // dynamic type to support float and int values

    public DynamicValueGenerator()
    {
        this.ranges = new List<dynamic>();
    }

    public void AddRange(dynamic start, dynamic end)
    {
        lock (_lock) 
        {
            ValidateAndAddRange(start, end);
        }
    }

    private void ValidateAndAddRange(dynamic start, dynamic end)
    {
        if (start > end) throw new ArgumentException("Start value cannot be greater than the End value");

        for (int i = 0; i < ranges.Count; i++)
        {
            if ((start >= ranges[i].start && start <= ranges[i].end) || (end >= ranges[i].start && end <= ranges[i].end))
            {
                throw new ArgumentException("New range overlaps with an existing one"); 
            }
        }

        ranges.Add(new { start = start, end = end });
    }

    public dynamic GenerateRandomValue()
    {
        lock (_lock)
        {
            if (ranges.Count == 0) throw new InvalidOperationException("No valid ranges found to generate value");

            Random rnd = new Random(); 
            int index = rnd.Next(ranges.Count);
            dynamic range = ranges[index];

            Type rangeType = range.start.GetType();
            if (rangeType == typeof(int)) return rnd.Next((int)range.start, (int)range.end + 1); 
            else if (rangeType == typeof(float)) return ((float)(rnd.NextDouble() * (double)((decimal)range.end - range.start) + range.start));

            throw new NotSupportedException("Unsupported type");
        }
    }

    public void LoadRangesFromConfigFile(string filePath)
    {
        // TODO: Implement a configuration service that can dynamically load and save ranges
    }
}
