    memset(offsets, 0xff, n * sizeof(long));

    keys = calloc(n, sizeof(int));

    // Check if memory limit is exceeded.
    allocated_memory += n * sizeof(long) + n * sizeof(int);
    if (allocated_memory > max_memory_kb) {
