typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
} ArraysContainer;

ArraysContainer* create_arrays(long userInput1, int userInput2, int maxUniqueValues, bool logEnabled) {
    // Validate input
    if (userInput1 < 0 || userInput2 < 0 || userInput1 + userInput2 > LONG_MAX / sizeof(Record)) {
        return NULL;
    }

    // Initialize arrays
    long* offsets = calloc(userInput1, sizeof(long));
    if (offsets == NULL) {
        return NULL;
    }

    int* keys = calloc(userInput2, sizeof(int));
    if (keys == NULL) {
        free(offsets);
        return NULL;
    }

    Record* records = malloc(sizeof(Record) * maxUniqueValues);
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Fill records with unique random values 0-1000
    srand(time(NULL));
    for (int i = 0; i < maxUniqueValues; ++i) {
        records[i].value = rand() % 1001;

        if (logEnabled) {
            printf("Generated value: %d\n", records[i].value);
        }
    }

    // Create and return ArraysContainer struct
    ArraysContainer* result = malloc(sizeof(ArraysContainer));
    if (result == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    result->offsets = offsets;
    result->keys = keys;
    result->records = records;
    return result;
}

void destroy_arrays(ArraysContainer* arrays) {
    free(arrays->offsets);
    free(arrays->keys);
    free(arrays->records);
    free(arrays);
}
