```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} Event;

struct EventArray {
    Event *events;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
};

const size_t MAX_MEMORY = 1024 * 1024 * 1024; // 1GB
pthread_cond_t memoryCond = PTHREAD_COND_INITIALIZER;
pthread_mutex_t memoryMutex = PTHREAD_MUTEX_INITIALIZER;
size_t currentMemory = 0;

void *allocate(size_t size) {
    void *ptr;
    while ((ptr = malloc(size)) == NULL) {
        if (currentMemory + size > MAX_MEMORY) {
            pthread_mutex_lock(&memoryMutex);
            // Wait until there is memory available.
            while (currentMemory + size > MAX_MEMORY) {
                pthread_cond_wait(&memoryCond, &memoryMutex);
            }
            currentMemory += size;
            pthread_mutex_unlock(&memoryMutex);
        } else {
            return NULL;
        }
    }
    return ptr;
}

void deallocate(void *ptr, size_t size) {
    free(ptr);
    pthread_mutex_lock(&memoryMutex);
    currentMemory -= size;
    if (currentMemory + size > MAX_MEMORY) {
        pthread_cond_signal(&memoryCond);
    }
    pthread_mutex_unlock(&memoryMutex);
}

int initializeEventArray(struct EventArray *array, size_t initialSize) {
    if (initialSize + currentMemory > MAX_MEMORY) {
        return -1; // Not enough memory
    }

    array->events = allocate(sizeof(Event) * initialSize);
    if (array->events == NULL) {
        return -1; // Allocation failed
    }
    array->capacity = initialSize;
    array->size = 0;

    pthread_mutex_init(&array->lock, NULL);

    return 0; // Success
}

void destroyEventArray(struct EventArray *array) {
    deallocate(array->events, sizeof(Event) * array->capacity);
    pthread_mutex_destroy(&array->lock);
}
```
