["Here's a simple implementation of the problem:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Cache line size assumed to be 64 bytes
#define CACHE_LINE_SIZE 64

typedef struct {
    long offset;
    int key;
    double value;
    char *label;
} Record;

static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t memory_usage = 0;
static const size_t MAX_MEMORY_USAGE = 1024 * 1024; // 1 MB

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    posix_memalign(&ptr, alignment, size);
    return ptr;
}

int align_to_cache_line(Record *record) {
    if (pthread_mutex_lock(&memory_lock)) return -1; // Handle error
    memory_usage += sizeof(*record);
    Record* new_rec = aligned_alloc(CACHE_LINE_SIZE, sizeof(*new_rec));

    if (!new_rec) {
        pthread_mutex_unlock(&memory_lock);
        return -1; // Handle error
    }

    memcpy(new_rec, record, sizeof(*record));
    *record = *new_rec;

    free(new_rec);
    pthread_mutex_unlock(&memory_lock);
    return 0; // Success
}

Record* create_records(size_t num_records, long offset_min, long offset_max, int key_min, int key_max, double value_min, double value_max) {
    if (num_records <= 0 || offset_min > offset_max || key_min > key_max || value_min > value_max || pthread_mutex_lock(&memory_lock)) return NULL; // Handle error

    size_t total_size = sizeof(Record) * num_records;
    if (total_size + memory_usage > MAX_MEMORY_USAGE) {
        pthread_mutex_unlock(&memory_lock);
        return NULL; // Handle error, not enough space
    }

    Record* records = aligned_alloc(CACHE_LINE_SIZE, total_size);
    if (!records) {
        pthread_mutex_unlock(&memory_lock);
        return NULL; // Handle error
    }

    memory_usage += total_size;
    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = offset_min + rand() % ((offset_max - offset_min) + 1);
        records[i].key = key_min + rand() % ((key_max - key_min) + 1);
        records[i].value = value_min + (((double)rand() / (double)RAND_MAX) * (value_max - value_min));
        align_to_cache_line(&records[i]);
    }

    pthread_mutex_unlock(&memory_lock);
    return records;
}
```
