@RestController
public class AsyncApiService {
    private final WebClient webClient;

    public AsyncApiService(@Value("${remote.api.base.url}") String baseUrl) {
        HttpClient httpClient = HttpClient.create()
                .tcpConfiguration(client -> client.option(ChannelOption.CONNECT_TIMEOUT_MILLIS, 10000));

        this.webClient = WebClient.builder().baseUrl(baseUrl)
                .defaultHeader(HttpHeaders.CONTENT_TYPE, MediaType.APPLICATION_JSON_VALUE)
                .clientConnector(new ReactorClientHttpConnector(httpClient))
                .build();
    }

    @GetMapping("/api/{id}")
    public Mono<String> get(@PathVariable String id) {
        return this.webClient.get().uri("/resource/" + id).retrieve().bodyToMono(String.class);
    }

    @PostMapping("/api")
    public Mono<String> post(@RequestBody String body) {
        return this.webClient.post().uri("/resource").body(BodyInserters.fromValue(body)).retrieve().bodyToMono(String.class);
    }
}
