['This problem is quite complex and would take several hundred lines of code to fully implement. Here's a simplified example of how the function might be structured using PHP, Guzzle HTTP client for API calls, Symfony Cache for caching responses, and a custom rate limiter class for handling rate limits.

```php
<?php
use Symfony\Component\Cache\Adapter\FilesystemAdapter;
use Symfony\Contracts\Cache\ItemInterface;

class RateLimiter {
    private $cachePool;

    public function __construct() {
        $this->cachePool = new FilesystemAdapter();
    }

    public function limit($key, $maxCalls, $period) {
        return $this->cachePool->get('rate_limit' . $key, function (ItemInterface $item) use ($maxCalls, $period) {
            $current = $item->get() ?: [ 'count' => 0, 'start' => time() ];
            if ((time() - $current['start']) > $period) {
                $current = ['count' => 1, 'start' => time()];
            } elseif ($current['count'] < $maxCalls) {
                $current['count']++;
            } else {
                return false;
            }
            $item->set($current);
        });
    }
}

function fetchUserActivity($userId, RateLimiter $rateLimiter) {
    $client = new \GuzzleHttp\Client();

    // Limit to 10 calls per second (for demonstration purposes only)
    if (!$rateLimiter->limit('fetchUserActivity', 10, 1)) {
        throw new Exception("Rate limit exceeded");
    }

    $cachePool = new FilesystemAdapter();

    $activity1 = $cachePool->get(sprintf('api1_%s', $userId), function (ItemInterface $item) use ($client, $userId){
        $response = $client->request('GET', 'http://api1.com/' . $userId);
        return json_decode((string) $response->getBody(), true);
    });

    $activity2 = $cachePool->get(sprintf('api2_%s', $userId), function (ItemInterface $item) use ($client, $userId){
        $response = $client->request('GET', 'http://api2.com/' . $userId);
        return json_decode((string) $response->getBody(), true);
    });

    // Aggregate activities from different APIs and return
    $aggregatedActivity = array_merge($activity1, $activity2);

    return $aggregatedActivity;
}
