['```c
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>
#include <unistd.h>
#include <limits.h>
#include <math.h>
#include <stdlib.h>

#define MAX_RECORDS 1024
#define MAX_SETS 64
#define IDENTIFIER_LEN 32

typedef struct {
    long offset;
    int key;
    double timestamp;
    char identifier[IDENTIFIER_LEN];
} Record;

typedef struct {
    pthread_mutex_t lock;
    Record records[MAX_RECORDS][MAX_SETS];
    int recordCounts[MAX_SETS];
} RecordsManager;

int getrss() {
    FILE* fp = NULL;
    long rss = 0L;
    if ((fp = fopen("/proc/self/statm", "r")) == NULL)
        return (0); /* Can't open? */
    if (fscanf(fp, "%*s%ld", &rss) != 1) {
        fclose(fp);
        return (0); /* Can't read? */
    }
    fclose(fp);
    return ((int) rss * (long) sysconf(_SC_PAGESIZE));
}

void initRecordManager(RecordsManager* rm, int sets){
    if(sets > MAX_SETS || sets < 1){
        printf("Invalid number of sets. Must be between 1 and %d\n", MAX_SETS);
        exit(-1);
    }

    for(int i = 0; i < sets; i++){
        rm->recordCounts[i] = 0;
    }
}

void addRecord(RecordsManager* rm, int set, Record record){
    if(set >= MAX_SETS || set < 0){
        printf("Invalid set number. Must be between 0 and %d\n", MAX_SETS-1);
        return;
    }

    pthread_mutex_lock(&rm->lock);
    if(rm->recordCounts[set] >= MAX_RECORDS){
        for(int i = 0; i < MAX_RECORDS - 1; i++)
            rm->records[i][set] = rm->records[i+1][set];
        rm->recordCounts[set]--;
    }

    rm->records[rm->recordCounts[set]++][set] = record;
    pthread_mutex_unlock(&rm->lock);
}

void processSensorData(RecordsManager* rm, Record record){
    static int set = 0;

    if(set >= MAX_SETS)
        set = 0;

    addRecord(rm, set++, record);
}
```
