public class FileProcessor {
    private static final String CHARSET = "UTF-8";
    private static final String DATE_FORMAT = "yyyyMMddHHmmssSSS";

    public void processFiles(String directoryPath) throws IOException, NoSuchAlgorithmException, InterruptedException {
        Path dirPath = Paths.get(directoryPath);

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dirPath)) {
            List<File> files = new ArrayList<>();

            for (Path path : stream) {
                if (!Files.isDirectory(path)) {
                    File file = path.toFile();
                    String hashName = getContentHash(file);
                    file.renameTo(new File(dirPath + "/" + hashName));

                    files.add(file);
                }
            }

            Collections.sort(files, Comparator.comparingLong(File::lastModified));

            for (File file : files) {
                String metadata = getMetadata(file);
                enhanceFile(file, metadata);

                if (archiveFiles(dirPath + "/" + file.getName())) {
                    System.out.println("Successfully archived: " + file.getName());
                } else {
                    System.err.println("Failed to archive: " + file.getName());
                }
            }
        }
    }

    private String getContentHash(File file) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");

        try (InputStream is = new FileInputStream(file)) {
            byte[] buffer = new byte[8192];
            int bytesRead;

            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }

        return new String(Hex.encodeHex(md.digest()));
    }

    private String getMetadata(File file) throws IOException, InterruptedException {
        Process process = Runtime.getRuntime().exec("commandLineUtil " + file.getAbsolutePath());
        int exitCode = process.waitFor();

        if (exitCode == 0) {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream(), CHARSET))) {
                StringBuilder metadata = new StringBuilder();
                String line;

                while ((line = reader.readLine()) != null) {
                    metadata.append(line);
                }

                return metadata.toString();
            }
        } else {
            throw new IOException("Error executing commandLineUtil");
        }
    }

    private void enhanceFile(File file, String metadata) throws IOException {
        // Implement enhancement logic here...
    }

    private boolean archiveFiles(String path) throws IOException {
        FileOutputStream fos = new FileOutputStream(path + ".zip");
        ZipOutputStream zipOut = new ZipOutputStream(fos);

        try (FileInputStream fis = new FileInputStream(path)) {
            ZipEntry zipEntry = new ZipEntry(new File(path).getName());
            zipOut.putNextEntry(zipEntry);

            byte[] bytes = new byte[1024];
            int length;

            while ((length = fis.read(bytes)) >= 0) {
                zipOut.write(bytes, 0, length);
            }
        }

        return true;
    }

