public interface ICustomDataStructure { /* Define your data structure interfaces here */ }

public class CustomDataIntegrationService 
{
    private readonly byte[] _key; // Your encryption key goes here
    private const int BufferSize = 4096;

    public CustomDataIntegrationService(byte[] key) => _key = key ?? throw new ArgumentNullException(nameof(key));

    public async Task<ICustomDataStructure> IntegrateFilesAsync(string[] filePaths, Type[] allowedTypes) 
    {
        var dataStructures = new List<Task<ICustomDataStructure>>();

        foreach (var path in filePaths)
        {
            using (var stream = File.OpenRead(path))
            {
                // Delegate the decryption and deserialization to another thread
                dataStructures.Add(Task.Run(() => DecryptAndDeserialize(stream, allowedTypes)));
            }
        }

        await Task.WhenAll(dataStructures); // Wait for all tasks to complete

        var mergedData = new CustomMergedDataStructure(); // Implement your own merging logic here
        foreach (var data in dataStructures) 
        {
            // Add each decrypted and deserialized object to the merged data structure
            if(data.Result != null) mergedData.Add(data.Result);
        }

        return mergedData;
    }

    private ICustomDataStructure DecryptAndDeserialize(Stream stream, Type[] allowedTypes) 
    {
        using var aes = Aes.Create(); // Or whatever encryption method you're using
        aes.Key = _key;

        byte[] decryptedData = PerformDecryption(aes, stream);

        return (ICustomDataStructure)JsonConvert.DeserializeObject(Encoding.UTF8.GetString(decryptedData), allowedTypes);
    }

    private static byte[] PerformDecryption(SymmetricAlgorithm aes, Stream inputStream) 
    {
        using var decryptor = aes.CreateDecryptor();
        using var cryptoStream = new CryptoStream(inputStream, decryptor, CryptoStreamMode.Read);

        var outputBytes = new MemoryStream();
        var buffer = new byte[BufferSize];
        int read;
        while ((read = cryptoStream.Read(buffer, 0, BufferSize)) > 0) 
        {
            outputBytes.Write(buffer, 0, read);
        }

        return outputBytes.ToArray();
    }
}
