```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static size_t current_size = 0, max_records = 1024;  // initial and maximum sizes
static record *records = NULL;

void *init_record(int key) {
    static size_t next_offset = 0;
    if (current_size == max_records) {
        pthread_mutex_lock(&lock);  // lock for thread safety
        records = realloc(records, sizeof(record) * max_records * 2);  // double the size of record array
        if (!records) exit(-1);  // handle allocation failure
        max_records *= 2;
        pthread_mutex_unlock(&lock);  // unlock after resizing array
    }

    records[current_size].offset = next_offset++;
    records[current_size].key = key;
    records[current_size].timestamp = time(NULL);
    return &records[current_size++];
}

void *allocate_record() {
    srand(time(0));  // seed the random number generator with current time
    int min = 1, max = 10;  // default key range

    char *env = getenv("CONFIG");  // check environment variable for configuration file path
    if (env) {
        FILE *file = fopen(env, "r");  // try to open the configuration file and read the key range
        if (file && fscanf(file, "%d-%d", &min, &max) == 2) fclose(file);  // close the file when done reading
    }

    return init_record(rand() % (max - min + 1) + min);  // initialize a new record with random key within the given range
}
```
This function can be used to manage dynamic array of `record` structures. The size of the array is initially set to 1024, and it doubles in size each time when the current size equals to the maximum size. The timestamp for every record is set to the current time using `time(NULL)` function from `time.h` library. Thread safety is ensured by a mutex lock which prevents race conditions during array resizing.
