    mgr->capacity = initialCapacity;
    mgr->size = 0;

    mgr->data = (sensor_data*)calloc(initialCapacity, sizeof(sensor_data)); // initialize memory to 0
    if(!mgr->data) {
        free(mgr);
        return NULL;
    }

    mgr->db = fopen(filename, "r"); // open file for reading
    if(!mgr->db) {
        free(mgr->data);
        free(mgr);
        return NULL;
    }

    // initialize caching mechanism
    mgr->cache = (sensor_data**)calloc(initialCapacity, sizeof(sensor_data*));
    if(!mgr->cache) {
        fclose(mgr->db);
        free(mgr->data);
        free(mgr);
