    FILE *fp = fopen(fileName, "r");
    if (fp == NULL) {
        printf("Could not open file %s", fileName);
        return NULL;
    }

    char line[256]; 
    int lines = 0;
    while (fgets(line, sizeof(line), fp)) lines++;
