    char* segment;
} record_t;

typedef struct {
    size_t size;
    record_t* records;
} file_chunk_t;

file_chunk_t** allocate(size_t num, size_t max_size) {
    // Ensure the number of chunks is valid.
    assert(num > 0 && num <= SIZE_MAX);

    // Allocate memory for the array of chunk pointers.
    file_chunk_t** chunks = (file_chunk_t**) malloc(sizeof(file_chunk_t*) * num);
    if (!chunks) {
        return NULL;
    }

    // Initialize each chunk pointer and allocate memory for its records.
    srand(0);  // seed the random number generator
    size_t i, j;
    for (i = 0; i < num; ++i) {
        chunks[i] = (file_chunk_t*) malloc(sizeof(file_chunk_t));
        if (!chunks[i]) {
            // Handle allocation failure.
            goto fail;
        }

        // Calculate the size for each chunk, ensuring it's a power of two.
        chunks[i]->size = pow(2, rand() % (log2(max_size) + 1));
        chunks[i]->records = (record_t*) malloc(sizeof(record_t) * chunks[i]->size);
        if (!chunks[i]->records) {
            // Handle allocation failure.
            goto fail;
        }

        // Initialize each record in the chunk with a unique string segment.
        for (j = 0; j < chunks[i]->size; ++j) {
            chunks[i]->records[j].offset = rand();  // Randomize offsets.
            size_t seg_size = rand() % 1024 + 1;  // Randomize segment sizes.
            chunks[i]->records[j].segment = (char*) malloc(seg_size);
            if (!chunks[i]->records[j].segment) {
                // Handle allocation failure.
                goto fail;
            }

            // Fill the segment with random data for simplicity.
            size_t k;
            for (k = 0; k < seg_size; ++k) {
                chunks[i]->records[j].segment[k] = rand() % 256;
            }
        }
    }

    return chunks;

fail:
    // Free all previously allocated memory.
    for (size_t k = 0; k < i; ++k) {
        if (chunks[k]) {
            free(chunks[k]->records);
            free(chunks[k]);
        }
    }

    return NULL;
}
```

