    double value;
    long * timestamp;
};

std::mt19937 seededRand(unsigned int seed) {
    if (seed == 0 || seed < 0) {
        throw std::invalid_argument("Invalid seed value");
    }
    std::random_device rd;
    std::mt19937 gen(rd());
    gen.seed(seed);
    return gen;
}

std::unique_ptr<double[]> allocateMemoryForTimeSeriesData(unsigned int size) {
    if (size == 0 || size > 10'000'000) { // arbitrary max size for this example
        throw std::invalid_argument("Invalid size value");
    }
    return std::make_unique<double[]>(size);
}

std::unordered_set<std::string> createUniqueStringSet() {
    std::unordered_set<std::string> set;
    // populate the set with unique strings here
    return set;
}

std::vector<data_point> allocateMemoryForDataPoints(unsigned int size, long* timestamp) {
    if (size == 0 || size > 10'000'000) { // arbitrary max size for this example
        throw std::invalid_argument("Invalid size value");
    }
    std::mt19937 gen = seededRand(std::random_device{}());
    std::uniform_real_distribution<double> dist(-1000, 1000);

    std::vector<data_point> dataPoints;
    for (unsigned int i = 0; i < size; ++i) {
        data_point dp;
        dp.value = dist(gen);
        dp.timestamp = timestamp;
        dataPoints.push_back(dp);
    }
    return dataPoints;
}
