    int i, j;
    srand((unsigned int)time(NULL)); // Use current time as seed for random generator
    for(i = 0; i < maxNumOfRecords; ++i){
        records[i].offset = rand(); // Random offset
        do { 
            records[i].key = (rand() % (KEY_UPPER_LIMIT - KEY_LOWER_LIMIT + 1)) + KEY_LOWER_LIMIT; // Unique key in the range
            for(j = 0; j < i; ++j){
                if(records[i].key == records[j].key) { 
                    break;
                 }
             }
        } while (j < i);
        records[i].timestamp = time(NULL); // Current timestamp
    }

    if(growthFactor > 1.0){
       maxNumOfRecords *= growthFactor;
       records = (Record *)realloc(records, maxNumOfRecords*sizeof(Record));
        if (records == NULL) { 
         return NULL; 
     }
    }
    return records;
}
```
The function `createRecords` allocates a block of memory for an array of Record structures. It then populates the records with random offsets and unique keys within a specified range, setting their timestamps to the current time. If growth factor is greater than 1, it increases the size of the record array by that factor using realloc function.
