using System;
public class DynamicValueGenerator
{
    private int lowerBound;
    private int upperBound;
    public DynamicValueGenerator(int lower = 0, int upper = Int32.MaxValue) 
    {
        if (lower > upper)
            throw new ArgumentException("Invalid range");

        this.lowerBound = lower;
        this.upperBound = upper;
    }

    public double GenerateDouble()
    {
        Random rand = new Random();
        return rand.NextDouble() * (this.upperBound - this.lowerBound) + this.lowerBound;
    }

    public int GenerateInteger()
    {
        Random rand = new Random();
        return rand.Next(this.lowerBound, this.upperBound);
    }
}
