        std::list<std::pair<key_t, record_t*>> lruList; // Doubly linked list of key-value pairs ordered by recent usage
        std::unordered_map<key_t, decltype(lruList.begin())> lruMap; // A map that points to the corresponding iterator in the list for each key

    public:
        record_t* getRecordFromCacheByKey(const key_t& key) {
            auto it = lruMap.find(key);

            if (it == lruMap.end()) 
                return nullptr; // If the key is not found in cache, return null

            lruList.splice(lruList.begin(), lruList, it->second); // Move this iterator to front of list as it's recently accessed

            return it->second->second; 
        }

        void insertIntoCache(const key_t& key, record_t* record) {
            if (lruMap.find(key) != lruMap.end()) // If the key is already in cache
                lruList.erase(lruMap[key]); 

            lruList.push_front(std::make_pair(key, record)); // Add new pair to front of list
            lruMap[key] = lruList.begin(); // And update the map with iterator to this element in list

            if (lruMap.size() > sizeLimit) { // If cache exceeds limit, remove least recently used entry from both list and map
                lruMap.erase(lruList.back().first); 
                lruList.pop_back(); 
            }
        }
};
