sqlite3* db = 0;
char* dbErrMsg = 0;
int rc;

void errorCallback(char* error) {
    printf("Error: %s\n", error);
}

sensor_event* createEvent(float reading, char tag) {
    sensor_event *new = malloc(sizeof(sensor_event));

    if (new == NULL) {
        errorCallback("Failed to allocate memory for event");
        return NULL;
    }

    new->reading = reading;
    new->tag = tag;
    time(&new->timestamp);
    new->prev = NULL;
    new->next = NULL;

    return new;
}

void insertEvent(sensor_event *event) {
    pthread_mutex_lock(&lock);
    // Insert event into doubly linked list and DB here...
    char* sqlInsert = "INSERT INTO SENSOR_EVENTS (READING, TAG, TIMESTAMP) VALUES(?, ?, ?);";

    rc = sqlite3_exec(db, sqlInsert, NULL, 0, &dbErrMsg);
    if(rc != SQLITE_OK){
        errorCallback("SQL Insert Error");
        fprintf(stderr, "SQL Insert error: %s\n", dbErrMsg);
        sqlite3_free(dbErrMsg);
    } else {
        printf("\nRecords inserted successfully!\n");
    }
    pthread_mutex_unlock(&lock);
}

void deleteEvent(sensor_event *event) {
    pthread_mutex_lock(&lock);
    // Delete event from doubly linked list and DB here...
    char* sqlDelete = "DELETE FROM SENSOR_EVENTS WHERE READING=? AND TAG=? AND TIMESTAMP=?;";

    rc = sqlite3_exec(db, sqlDelete, NULL, 0, &dbErrMsg);
    if(rc != SQLITE_OK){
        errorCallback("SQL Delete Error");
        fprintf(stderr, "SQL Delete error: %s\n", dbErrMsg);
        sqlite3_free(dbErrMsg);
    } else {
        printf("\nRecords deleted successfully!\n");
    }
    pthread_mutex_unlock(&lock);
}

// Function to handle DB setup, including opening and closing connection
