    rc = sqlite3_open("test.db", &db);

    if(rc) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        return -1;
    } else {
        printf("Opened database successfully!\n");
    }

    char* sqlCreateTable = "CREATE TABLE SENSOR_EVENTS ("  \
          "READING           REAL     NOT NULL," \
          "TAG               CHAR(50) NOT NULL," \
          "TIMESTAMP         INT      NOT NULL);";

    rc = sqlite3_exec(db, sqlCreateTable, NULL, 0, &dbErrMsg);
    if(rc != SQLITE_OK){
        errorCallback("SQL Create Table Error");
        fprintf(stderr, "Cannot create table: %s\n", dbErrMsg);
        sqlite3_free(dbErrMsg);
        return -1;
    } else {
        printf("\nTable created successfully!\n");
    }

    return 0;
}

void dbTeardown() {
    if (db) {
        sqlite3_close(db);
    }
}
