typedef struct {
    int val;
    char buffer[256];
} record;

typedef struct {
    long lval;
    record* rec;
} offset;

offset* allocate_and_init(int count, int minRange, int maxRange) {
    // Checking for valid range
    if (minRange > maxRange || count <= 0) return NULL;

    // Allocating memory for structures
    offset *data = malloc(sizeof(offset) * count);
    record* records = malloc(sizeof(record) * count);
    if (data == NULL || records == NULL) {
        free(data);
        free(records);
        return NULL;
    }

    // Initializing structure elements with random values within range
    srand((unsigned int)time(NULL)); 
    for(int i = 0; i < count; ++i){
        records[i].val = (rand() % (maxRange - minRange + 1)) + minRange;
        memcpy(records[i].buffer, "AABBCC...", sizeof("AABBCC..."));
    }

    // Copying record pointers to offset structure
    for(int i = 0; i < count; ++i) {
        data[i].lval = i;
        data[i].rec = &records[i];
    }

    return data;
}

void compute_hash(const char* str) {
    unsigned char md5Result[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, strlen(str), md5Result);

    // Printing the hash
    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i)
        printf("%02x",md5Result[i]);
}
```
