SharedData shared_data = {{PTHREAD_MUTEX_INITIALIZER}, 0, NULL};

void allocate(int datasetSize, int valueRange) {
    pthread_mutex_lock(&shared_data.lock);

    if (shared_data.size != datasetSize) {
        // Free existing records
        for (int i = 0; i < shared_data.size; ++i) {
            free(shared_data.records[i].offsets);
            free(shared_data.records[i].keys);
        }
        if (shared_data.size > 0) {
            free(shared_data.records);
        }

        // Allocate new records
        shared_data.records = calloc(datasetSize, sizeof(Record));
        for (int i = 0; i < datasetSize; ++i) {
            shared_data.records[i].value = rand() % valueRange;
            shared_data.records[i].offsets = malloc(sizeof(long)*datasetSize); // Allocate memory for offsets
            shared_data.records[i].keys = malloc(sizeof(int)*datasetSize); // Allocate memory for keys
        }

        shared_data.size = datasetSize;
    }

    pthread_mutex_unlock(&shared_data.lock);
}

void updateFromFiles() {
    FILE* offsetFile = fopen("offsets.txt", "r");
    FILE* keysFile = fopen("keys.txt", "r");

