["```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <assert.h>

typedef struct {
    float value;
    double *doubleValue;
    short key;
} Record;

typedef struct Node {
    Record record;
    struct Node *next;
    pthread_rwlock_t lock;
} Node;

Node *cache = NULL;
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;

void initRecord(Record *record, float value, double *doubleValue, short key) {
    record->value = value;
    record->doubleValue = malloc(sizeof(double));
    assert(record->doubleValue != NULL);
    *(record->doubleValue) = *doubleValue;
    record->key = key;
}

void freeRecord(Record *record) {
    free(record->doubleValue);
    record->value = 0.0f;
    record->key = 0;
}

Node* findNode(short key, Node **prevPtr) {
    pthread_mutex_lock(&cacheMutex);
    Node *temp = cache;
    Node *prev = NULL;

    while (temp != NULL && temp->record.key != key) {
        prev = temp;
        temp = temp->next;
    }

    if(prevPtr != NULL){
      *prevPtr = prev;
    }

    pthread_mutex_unlock(&cacheMutex);
    return temp;
}

void insertNode(Record record) {
    Node *node = malloc(sizeof(Node));
    assert(node != NULL);
    node->record = record;
    pthread_rwlock_init(&node->lock, NULL);

    pthread_mutex_lock(&cacheMutex);
    node->next = cache;
    cache = node;
    pthread_mutex_unlock(&cacheMutex);
}

void deleteNode(short key) {
    Node *prev = NULL;
    Node *node = findNode(key, &prev);

    if (node == NULL) return;

    pthread_rwlock_wrlock(&node->lock);
    freeRecord(&node->record);

    if (prev != NULL) {
        prev->next = node->next;
    } else {
        cache = node->next;
    }

    pthread_rwlock_unlock(&node->lock);
    free(node);
}

void updateNode(short key, Record record) {
    Node *prev = NULL;
    Node *node = findNode(key, &prev);

    if (node == NULL){
      insertNode(record);
      return;
    }

    pthread_rwlock_wrlock(&node->lock);
    freeRecord(&node->record);
    node->record = record;
    pthread_rwlock_unlock(&node->lock);
}

void updateFloat(short key, double newDoubleValue) {
    Node *prev = NULL;
    Node *node = findNode(key, &prev);

    if (node == NULL) return;

    pthread_rwlock_wrlock(&node->lock);
    *(node->record.doubleValue) = newDoubleValue;
    pthread_rwlock_unlock(&node->lock);
}
```
This code creates a dynamic, in-memory cache for storing records that contain 'float' values and 'short' integer keys, using a linked list data structure. Each node has its own lock to ensure thread-safe operations. When inserting or updating nodes, the code ensures atomicity by acquiring the appropriate locks before modifying the record. The cache is protected with a mutex for efficient concurrent access and modification.
"]

