#include <atomic>
#include <vector>
#include <memory>
#include <thread>
#include <shared_mutex>
#include <fstream>
#include <json/json.h> // you need to install jsoncpp library

struct metadata {
    std::string value;
};

struct entry {
    double dblVal;
    std::unique_ptr<float[]> intervals;
    std::shared_ptr<metadata> metaData;
};

class CollectionManager{
private:
    std::vector<std::unique_ptr<entry>> collection;
    mutable std::shared_timed_mutex mtx_; // for shared lock when reading and exclusive lock when writing
    std::atomic<bool> isUpdated {false};

public:
    CollectionManager(size_t size, double valueRange) : collection(size){
        for(auto& e : collection) {
            e = std::make_unique<entry>();
            e->dblVal = rand()/(double)(RAND_MAX/valueRange); // assign a random value within the specified range to 'double' field.
        }
    }

    void updateFromJson(const char* filename, bool isMetadata) {
        std::ifstream file(filename, std::ifstream::binary);
        Json::Value root;
        file >> root;

        std::lock_guard<std::shared_timed_mutex> lock(mtx_); // exclusive lock for writing
        if(!isMetadata){
            size_t i=0;
            for (Json::Value::iterator it = root.begin(); it != root.end(); ++it) {
                collection[i]->intervals = std::make_unique<float[]>(it->size());
                for(int j=0; j < it->size(); j++){
                    (*it)[j].asFloat() = collection[i]->intervals.get()[j];
                }
                ++i;
            }
        } else {
            size_t i=0;
            for (Json::Value::iterator it = root.begin(); it != root.end(); ++it) {
                collection[i]->metaData = std::make_shared<metadata>(metadata{ (*it).asString() });
                ++i;
            }
        }

        isUpdated = true;
    }

    void asyncUpdateJson(const char* filename, bool isMetadata){
        auto t1 = std::thread(&CollectionManager::updateFromJson, this, filename, isMetadata);
        t1.detach(); // run the thread in background and forget about it.
    }
};
```
