#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct transaction {
    long id;
    double amount;
    char* description;
    time_t timestamp;
} Transaction;

Transaction** transactions = NULL;
size_t transaction_count = 0;
size_t transaction_capacity = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void resize_transactions(size_t new_capacity) {
    Transaction** new_array = realloc(transactions, new_capacity * sizeof(Transaction*));
    if (new_array == NULL && new_capacity != 0) {
        fprintf(stderr, "Failed to allocate memory for transactions\n");
        exit(EXIT_FAILURE);
    }
    transactions = new_array;
    transaction_capacity = new_capacity;
}

void add_transaction(double amount, const char* description) {
    pthread_mutex_lock(&lock);

    // Resize if necessary
    if (transaction_count == transaction_capacity)
        resize_transactions((transaction_capacity + 1) * 2);

    Transaction* new_tx = malloc(sizeof(Transaction));
    if (new_tx == NULL) {
        fprintf(stderr, "Failed to allocate memory for a transaction\n");
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }

    // Initialize the new transaction
    new_tx->id = // some unique id based on amount, description and current timestamp;
    new_tx->amount = amount;
    new_tx->description = strdup(description);  // allocate memory for the string
    if (new_tx->description == NULL) {
        fprintf(stderr, "Failed to duplicate description\n");
        free(new_tx);
        pthread_mutex_unlock(&lock);
        exit(EXIT_FAILURE);
    }

    // Add the new transaction to the array
    transactions[transaction_count] = new_tx;
    transaction_count++;

    printf("Added transaction with id %ld\n", new_tx->id);

    pthread_mutex_unlock(&lock);
}
```

This is a simple example of how you could handle dynamic memory management for transactions in C. It uses `malloc` and `realloc` to allocate memory, which are thread-safe in the POSIX library. It also uses mutexes (or locks) to ensure that only one thread can modify the transaction array at a time, protecting it from race conditions.

Please remember this is just a simple example and does not cover all your requirements. For more robust systems you would want to implement these things as well:
- A configuration file reader for default ranges, maximum transactions, memory usage limit etc. 
- An error handling mechanism that's triggered when an allocation failure occurs.
- Logging of operations (e.g., using syslog or printf)
- Implementation of hash function and handling of invalid configurations in the config file.
