["The given task is complex and requires careful design and implementation of multiple elements including dynamic memory allocation, multi-threading support, efficient logging system, and file management system. Here's a simplified overview of how the solution might look:

```c
#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    char* path;
    size_t size;
    time_t timestamp;
} file_entry;

typedef struct {
    pthread_mutex_t lock;
    file_entry* entries;
    atomic_int currentSize;
    atomic_int maxSize;
    atomic_size_t memoryUsage;
    size_t limit;
} FileArray;

FileArray* createFileArray(size_t initialSize, size_t limit) {
    // Allocate and initialize the array structure
    FileArray* fileArray = malloc(sizeof(FileArray));
    if (fileArray == NULL) return NULL;

    // Initialize mutex for thread safety
    pthread_mutex_init(&fileArray->lock, NULL);

    // Allocate initial array of file entries
    fileArray->entries = malloc(initialSize * sizeof(file_entry));
    if (fileArray->entries == NULL) {
        free(fileArray);
        return NULL;
    }

    // Initialize the current and max sizes of the array
    fileArray->currentSize = 0;
    fileArray->maxSize = initialSize;
    fileArray->memoryUsage = 0;
    fileArray->limit = limit;

    return fileArray;
}

void resizeFileArray(FileArray* fileArray, size_t newMaxSize) {
    // Acquire the lock before modifying shared state
    pthread_mutex_lock(&fileArray->lock);

    // Reallocate array with larger size
    fileArray->entries = realloc(fileArray->entries, newMaxSize * sizeof(file_entry));
    if (fileArray->entries != NULL) {
        fileArray->maxSize = newMaxSize;
    } else {
        // Rollback to the old size in case of failure
        fileArray->entries = realloc(fileArray->entries, fileArray->currentSize * sizeof(file_entry));
    }

    pthread_mutex_unlock(&fileArray->lock);
}

void addFileEntry(FileArray* fileArray, const char* path, size_t size) {
    // Acquire the lock before modifying shared state
    pthread_mutex_lock(&fileArray->lock);

    // If array is full, resize it
    if (fileArray->currentSize == fileArray->maxSize) {
        resizeFileArray(fileArray, 2 * fileArray->maxSize);
    }

    // Add new entry to the array
    size_t index = atomic_fetch_add(&fileArray->currentSize, 1);
    fileArray->entries[index].path = strdup(path);
    fileArray->entries[index].size = size;
    fileArray->entries[index].timestamp = time(NULL);

    // Update memory usage
    atomic_fetch_add(&fileArray->memoryUsage, sizeof(file_entry));

    pthread_mutex_unlock(&fileArray->lock);
}
```
The above code demonstrates how to handle dynamic allocation and resizing of an array of `file_entry` structures. For logging, error handling, configuration parsing, multi-threading and more, you would need to add additional functionality. This also doesn't cover the whole specification due to complexity but it gives a broad idea of how such system might look like in C.
"]

