```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <netinet/in.h>
#include <sys/time.h>

typedef struct {
    int sock;
    struct sockaddr_in addr;
    time_t start_timestamp;
} network_connection;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    network_connection *data;
} dynamic_array;

dynamic_array* create(size_t initial_capacity) {
    dynamic_array *arr = malloc(sizeof(*arr));
    if (arr == NULL) {
        perror("Failed to allocate memory for the array");
        return NULL;
    }

    arr->lock = PTHREAD_MUTEX_INITIALIZER;
    arr->capacity = initial_capacity;
    arr->size = 0;
    arr->data = malloc(initial_capacity * sizeof(*arr->data));

    if (arr->data == NULL) {
        perror("Failed to allocate memory for the array data");
        free(arr);
        return NULL;
    }

    return arr;
}

void push_back(dynamic_array *arr, network_connection item) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        // Allocate a new array with double the capacity and copy over the old data
        size_t new_capacity = arr->capacity * 2;
        network_connection *new_data = realloc(arr->data, new_capacity * sizeof(*arr->data));

        if (new_data == NULL) {
            perror("Failed to resize the array");
        } else {
            arr->data = new_data;
            arr->capacity = new_capacity;
        }
    }

    // Add the item at the end of the data array
    if (arr->size < arr->capacity) {
        arr->data[arr->size++] = item;
    } else {
        perror("Failed to push back to the array");
    }

    pthread_mutex_unlock(&arr->lock);
}

// similar functions for reading from and writing to the dynamic array, including error handling and synchronization mechanisms.
```
