["Here is a sample implementation of the task in C language. It uses linear probing for collision resolution and simple modulo operation as hash function. The load factor is checked after each insertion to determine whether resizing is necessary, which might lead to poor performance during high-intensity workloads but ensures efficient use of memory resources:

```c
#include <stdlib.h>

typedef struct node {
    long timestamp;
    int key;
    struct node *next;
} Node;

typedef struct hashTable {
    Node **table;
    size_t tableSize;
    size_t numElements;
} HashTable;

HashTable* createHashTable(size_t initialSize) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->tableSize = initialSize;
    ht->numElements = 0;
    ht->table = (Node**)calloc(initialSize, sizeof(Node*));
    return ht;
}

void resizeTable(HashTable *ht) {
    size_t oldSize = ht->tableSize;
    Node **oldTable = ht->table;

    ht->tableSize *= 2;
    ht->numElements = 0;
    ht->table = (Node**)calloc(ht->tableSize, sizeof(Node*));

    for(size_t i=0; i<oldSize; ++i){
        Node *node = oldTable[i];
        while(node != NULL){
            insertNode(ht, node->timestamp, node->key);
            Node *temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(oldTable);
}

size_t hashFunction(long timestamp, size_t tableSize){
    return (timestamp % tableSize + tableSize) % tableSize;  // handle negative values
}

void insertNode(HashTable *ht, long timestamp, int key) {
    if ((double) ht->numElements / ht->tableSize > 0.75){
        resizeTable(ht);
    }

    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->timestamp = timestamp;
    newNode->key = key;
    newNode->next = NULL;

    size_t index = hashFunction(timestamp, ht->tableSize);

    while (ht->table[index] != NULL){
        index = (index + 1) % ht->tableSize;
    }

    ht->table[index] = newNode;
    ht->numElements++;
}
```

