["Your request is quite complex and involves multiple aspects of programming, such as dynamic loading, concurrency control, memory management, error handling, and performance considerations. Here's a high-level example of how you might implement this in C with POSIX threads for managing concurrent users and dynamically loading libraries with dlopen/dlsym.

```c
#include <stdio.h>
#include <pthread.h>
#include <dlfcn.h>
#include <assert.h>

typedef struct {
    void* handle;  // Dynamic library handle
    char* (*get_name)();  // Getter function for protocol name
    void (*process)(void*);  // Message processing function
} Protocol;

Protocol* load_protocol(const char *libpath, const char* get_name_symbol, const char* process_symbol) {
    Protocol* p = malloc(sizeof(Protocol));
    assert(p != NULL);

    // Load the library and resolve symbols
    p->handle = dlopen(libpath, RTLD_LAZY);
    if (!p->handle) {
        free(p);
        return NULL;
    }
    p->get_name = (char*(*)())dlsym(p->handle, get_name_symbol);
    assert(p->get_name != NULL);
    p->process = dlsym(p->handle, process_symbol);
    assert(p->process != NULL);

    return p;
}

void unload_protocol(Protocol *protocol) {
    if (protocol == NULL) 
        return;

    dlclose(protocol->handle); // Close the library
    free(protocol); // Free the structure
}

typedef struct {
    pthread_mutex_t lock; // Mutex for concurrency control
    int num_protocols;  // Number of loaded protocols
    Protocol** protocols; // Array of protocol structures
} Framework;

Framework* create_framework(int max_protocols) {
    Framework* f = malloc(sizeof(Framework));
    assert(f != NULL);

    pthread_mutex_init(&f->lock, NULL); // Initialize the mutex
    f->num_protocols = 0; 
    f->protocols = calloc(max_protocols, sizeof(Protocol*)); // Allocate protocol array
    assert(f->protocols != NULL);

    return f;
}

void destroy_framework(Framework *framework) {
    for (int i = 0; i < framework->num_protocols; ++i) 
        unload_protocol(framework->protocols[i]); // Unload all protocols

    free(framework->protocols); // Free protocol array
    pthread_mutex_destroy(&framework->lock); // Destroy the mutex
    free(framework); // Free the structure
}

void process_message(Framework *fw, int index) {
    if (index >= fw->num_protocols) 
        return;

    pthread_mutex_lock(&fw->lock); // Lock mutex for concurrency control

    Protocol* protocol = fw->protocols[index];
    if (protocol != NULL) 
        protocol->process(NULL); // Process message with specific protocol

    pthread_mutex_unlock(&fw->lock); // Unlock the mutex
}
```
Please note that this is just a high-level example and does not cover all aspects of your request. You would need to expand on it significantly to meet your requirements, including error handling, memory management for `long` offsets, `int` keys, and `record` structures, flexible logging, and user preferences and system load considerations.
"]

