    assert(count <= 10e6); // Assuming 1 million is the upper limit.
    pthread_mutex_lock(&mutex);

    for(size_t i = 0; i < count; ++i) {
        records[i].offset = rand() % (conf.m - conf.a) + conf.a; // Random offset value
        records[i].key = rand(); // Generate random key
        records[i].value = rand(); // Generate random value
    }

    pthread_mutex_unlock(&mutex);

    return count;
}
```

