class JSONParser:
    factories = {}

    def __init__(self):
        self.data = {}

    @classmethod
    def register_factory(cls, name: str, factory: Callable) -> None:
        cls.factories[name] = factory

    @classmethod
    def create_from_json(cls, json_str: str):
        data = json.loads(json_str)
        return cls.factories[data['type']](**data)

    @staticmethod
    def to_json(obj):
        if hasattr(obj, 'to_dict'):
            data = obj.to_dict()
            data['type'] = type(obj).__name__
        else:
