typedef struct record {
    int value;
} record_t;

int function(long* offsets, size_t num_offsets, int* keys, size_t num_keys, 
            record_t* records, size_t num_records) {

    // Error checking and fallback mechanisms
    if (num_offsets > 65536 || num_keys > 32768 || num_records > 1024) return -1;  // Too many elements, exit
    if (!(offsets = malloc(sizeof(long) * num_offsets))) return -2;  // Memory allocation failure for offset array
    if (!(keys = calloc(num_keys, sizeof(int)))) return -3;  // Memory allocation failure for keys array
    if (!(records = malloc(sizeof(record_t) * num_records))) return -4;  // Memory allocation failure for records array

    srand((unsigned int)time(NULL));  // Initialize random number generator

    // Initialization of offsets and keys
    long lastOffset = rand();
    for (size_t i = 0; i < num_offsets; ++i) {
        do {
            lastOffset = rand();
        } while (lastOffset == *(offsets + i - 1));  // Ensure unique and non-adjacent values
        *(offsets + i) = lastOffset;
    }

    for (size_t i = 0; i < num_keys; ++i) {
        int key;
        do {
            key = rand();
        } while ((key == *(keys + i - 1)) || contains(keys, i, key)); // Ensure unique keys
        *(keys + i) = key;
    }

    // Initialization of records with random integers
    int lastValue = rand();
    for (size_t i = 0; i < num_records; ++i) {
        do {
            lastValue = rand() % RAND_MAX + 1;  // Random value within a specified range
        } while (lastValue == records[i - 1].value);  // Ensure non-consecutive values

        record_t newRecord;
        newRecord.value = lastValue;
        *(records + i) = newRecord;
    }

    return 0;  // Successful execution
}

// Helper function to check if an integer exists in a given array
