```C
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Data structure for a record
typedef struct {
    long offset;
    int key;
    double timestamp;
    float value;
} Record;

// Buffer to store records
Record* buffer[BUFFER_SIZE];
int head = 0, tail = 0, count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t notFull = PTHREAD_COND_INITIALIZER;
pthread_cond_t notEmpty = PTHREAD_COND_INITIALIZER;
int BUFFER_SIZE = 1024; // You may need to adjust this size depending on your needs.

// Producer function for standard input or remote data feeds
void* produce(void* arg) {
    while (1) {
        Record* record = malloc(sizeof(Record));

        // Produce a record here...

        pthread_mutex_lock(&mutex);
        while (count == BUFFER_SIZE)
            pthread_cond_wait(&notFull, &mutex);

        buffer[tail] = record;
        tail = (tail + 1) % BUFFER_SIZE;
        ++count;
        pthread_cond_signal(&notEmpty);
        pthread_mutex_unlock(&mutex);
    }
}

// Consumer function for processing the records
void* consume(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        while (count == 0)
            pthread_cond_wait(&notEmpty, &mutex);

        Record* record = buffer[head];
        head = (head + 1) % BUFFER_SIZE;
        --count;
        pthread_cond_signal(&notFull);
        pthread_mutex_unlock(&mutex);

        // Process the record here...
    }
}
``` 
This code implements a producer-consumer model using POSIX threads. The `produce` function is a thread that reads from an input source and writes to the buffer, while the `consume` function is a separate thread that processes the records in the buffer. It uses mutexes for synchronization and condition variables to control access to the shared buffer. This code does not include any actual data production or processing as these parts will depend on the specifics of your use case and should be implemented accordingly. Also, it's important to note that this is a simplified version and might require more advanced handling and optimization for real-world applications.
