For the hash table, I use glib's GHashTable which is a highly efficient hash table data structure. For the priority queue, we use glib's GQueue with some modifications to make it behave as a priority queue (highest value has highest priority). 

This example assumes that you have already defined all required structs and enums in your codebase. Also note that you need to install glib and link against glib-2.0 for this to work.

```c
#include <glib.h>
#include <time.h>
#include <stdbool.h>

typedef struct user_profile {
    enum UserStatus { ONLINE, OFFLINE } status;
    int accountAge;
    time_t lastLoginTimestamp;
} UserProfile;

typedef struct session_data {
    char* sessionId; // Assume UUID is represented as a string for simplicity 
    bool activeStatus;
    time_t lastActivityTime;
} SessionData;

typedef struct user_session_map {
    int userId;
    SessionData *sessionData;
} UserSessionMap;

typedef struct message_queue_entry {
    char* messageText;
    time_t timestamp;
    int priorityLevel;
} MessageQueueEntry;

void manageMemoryForSystem(void) {
    int userIds[5]; // Array of user IDs
    UserProfile *userProfiles[5] = {NULL, NULL, NULL, NULL, NULL}; // Array of pointers to struct user_profile
    SessionData *sessionDatas[5] = {NULL, NULL, NULL, NULL, NULL}; // Array of pointers to struct session_data

    GHashTable* userSessionMap = g_hash_table_new(g_int_hash, g_int_equal);  // Hash table for user_session_map
    GQueue *messageQueue = g_queue_new(); // Priority queue for struct message_queue_entry

    /* Allocate and populate memory for each data structure */
    for (int i = 0; i < 5; ++i) {
        userIds[i] = i + 1; // Set some sample user IDs

        userProfiles[i] = g_new(UserProfile, 1);
        if (!userProfiles[i]) goto error;
        userProfiles[i]->status = ONLINE;
        userProfiles[i]->accountAge = 0;
        userProfiles[i]->lastLoginTimestamp = time(NULL);

        sessionDatas[i] = g_new(SessionData, 1);
        if (!sessionDatas[i]) goto error;
        sessionDatas[i]->sessionId = "some_uuid"; // Replace with actual UUID generation logic.
        sessionDatas[i]->activeStatus = true;
        sessionDatas[i]->lastActivityTime = time(NULL);

        UserSessionMap mapEntry = {userIds[i], sessionDatas[i]};
        g_hash_table_insert(userSessionMap, &mapEntry.userId, mapEntry.sessionData); // Insert into hash table
    }

    /* Populate message queue with some entries */
    for (int i = 0; i < 5; ++i) {
        MessageQueueEntry entry = {"message_text", time(NULL), 1}; // Replace with actual values.
        g_queue_push_head(messageQueue, &entry); // Add to the front of the queue to emulate priority.
    }

    /* Cleanup */
    for (int i = 0; i < 5; ++i) {
        g_free(userProfiles[i]);
        g_free(sessionDatas[i]);
    }
    g_hash_table_destroy(userSessionMap);
    g_queue_free(messageQueue);

    return; // Memory allocation was successful.

error: 
    /* Handle error during memory allocation */
    perror("Memory allocation failed.");
}
```
