    if (count <= 0 || minKey > maxKey) return NULL; // Invalid input

    srand(time(NULL));

    record *recs = malloc(sizeof(record)*count); // Allocate memory for records
    if (!recs) { 
        fprintf(stderr, "Failed to allocate memory.\n");
        return NULL; 
    }

    long sum_offset = 0;
    int max_key = minKey-1; // Initialize maximum key value as minKey - 1

    for (int i = 0; i < count; ++i) {
        recs[i].offset = rand(); // Random offset
        sum_offset += recs[i].offset;

        recs[i].key = (rand() % (maxKey - minKey + 1)) + minKey;  // Random key between minKey and maxKey inclusive
        if(recs[i].key > max_key) {
            max_key = recs[i].key;
        }

        time_t rawtime;
        struct tm * timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        recs[i].timestamp = mktime(timeinfo); // Current timestamp 
    }

    printf("Sum of offset: %ld\n", sum_offset);
    printf("Max key value: %d\n", max_key);

    return recs;
}
