Module **modules = NULL;
size_t moduleCount = 0, moduleCapacity = 0;

void addModule(char *name, void (*function)()) {
    sem_wait(&moduleSem); // lock before adding a new module
    if (moduleCount >= moduleCapacity) {
        moduleCapacity = moduleCapacity ? moduleCapacity * 2 : 1;
        modules = realloc(modules, sizeof(*modules) * moduleCapacity);
    }
    modules[moduleCount] = malloc(sizeof(**modules));
    modules[moduleCount]->name = strdup(name);
    modules[moduleCount]->function = function;
    ++moduleCount;
    sem_post(&moduleSem); // unlock after adding a module
}

void callModuleFunction(int index) {
    if (index < 0 || index >= moduleCount) return;
    pthread_mutex_lock(&moduleMutex); // lock before calling a function
    modules[index]->function();
    pthread_mutex_unlock(&moduleMutex); // unlock after calling a function
}
