['Here is a simplified example of how this could be implemented in Java using Apache HttpClient for async requests and Gson for JSON parsing:
```java
import com.google.gson.*;
import org.apache.http.HttpResponse;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.nio.client.CloseableHttpAsyncClient;
import org.apache.http.impl.nio.client.HttpAsyncClients;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.*;

public class AsyncHttpRequestor {
    private static final Logger LOG = LoggerFactory.getLogger(AsyncHttpRequestor.class);

    // Configuration properties
    private Properties props;

    // Load the configuration from a properties file
    public void loadProperties() {
        props = new Properties();
        try (InputStream input = getClass().getResourceAsStream("/config.properties")) {
            props.load(input);
        } catch (IOException ex) {
            LOG.error("Failed to load configuration", ex);
        }
    }

    // Initialize the HttpClient
    private CloseableHttpAsyncClient httpclient = HttpAsyncClients.createDefault();

    public void sendRequest(String url, String jsonPayload) {
        HttpPost postRequest = new HttpPost(url);
        try {
            Gson gson = new GsonBuilder().disableHtmlEscaping().create();
            JsonObject json = new JsonParser().parse(jsonPayload).getAsJsonObject();

            // Add the headers
            for (Map.Entry<String, String> entry : props.entrySet()) {
                postRequest.addHeader(entry.getKey(), entry.getValue());
            }

            // Set the body
            StringEntity entity = new StringEntity(gson.toJson(json), "UTF-8");
            entity.setContentType("application/json");
            postRequest.setEntity(entity);

            httpclient.start();

            LOG.info("Executing request: {}", postRequest.getRequestLine());

            // Send the POST request and handle the response asynchronously
            httpclient.execute(postRequest, (final HttpResponse response) -> {
                int status = response.getStatusLine().getStatusCode();

                if (status >= 200 && status < 300) {
                    LOG.info("{}: {}", postRequest.getRequestLine(), status);
                    // Handle success here
                } else {
                    LOG.error("{}: {}", postRequest.getRequestLine(), status);
                    // Handle error here
                }
            });

        } catch (Exception ex) {
            LOG.error("Error executing request", ex);
        }
    }
}
```
Please note that this is a basic skeleton and does not cover everything you asked for, such as detailed logging or rate limiting. Also, it's important to remember that performance depends on many factors - from your hardware setup to the specific library you choose to use, among others. Therefore, optimizing the program requires careful consideration of all these factors.
']

