            Log *newLogs = realloc(logs, capacity * 2 * sizeof(Log));
            if (newLogs == NULL) {
                printf("Error allocating memory.\n");
                return -1;
            } else logs = newLogs;
        }

        // Parse log from line and add it to the array
        Log log;
        log.id = generateId(line);
        log.message = strdup(line);  // Copy string as we are responsible for freeing it later
        log.timestamp = time(NULL);

        logs[size] = log;
        size++;
    }

    fclose(file);

    printSeverity(logs, size, threshold);

    // Free allocated memory
    for (int i = 0; i < size; i++) free(logs[i].message);
    free(logs);

    return size;
}
