['Here's a basic C implementation using a pool allocator to reduce memory allocation overhead:

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    char* buffer;
} record;

// Node for the pool allocator
typedef struct node_t {
    record rec;
    struct node_t *next;
} node_t;

node_t *pool = NULL; // The memory pool
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // For thread safety
int bufSize = 0; // Size of the char buffer for each record

void* allocateMemory(size_t size) {
    void *mem = malloc(size);
    if (mem == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    return mem;
}

void initializeRecords(long* offsets, int nOffsets, int* keys, int nKeys, record** records, int bufSize) {
    // Lock to ensure thread safety
    pthread_mutex_lock(&lock);

    *records = allocateMemory(nKeys * sizeof(record));
    for (int i = 0; i < nKeys; i++) {
        (*records)[i].value = rand() % 100; // Initialize with a random value within range [0,99]

        // Allocate memory for the char buffer in the pool if available, else from OS.
        node_t *node = (pool != NULL) ? pool : NULL;
        if (node != NULL) {
            pool = node->next; 
            (*records)[i].buffer = node->rec.buffer;
        } else {
            (*records)[i].buffer = allocateMemory(bufSize * sizeof(char));
        }        
    }    

    // Unlock after critical section is done
    pthread_mutex_unlock(&lock); 
}

void freeRecords(record* records, int nKeys) {
    for (int i = 0; i < nKeys; i++) {
        // Free each char buffer back into the pool, if not full
        node_t *node = allocateMemory(sizeof(node_t));
        node->rec.buffer = records[i].buffer;
        node->next = pool; 
        pool = node;      
    }  

    free(records); // Free the records array
}
```
