["C does not have direct support for multithreading and concurrency control, but we can still follow some best practices to ensure thread safety and avoid data corruption. Here's a basic implementation of the linked list with a comparison function that minimizes fragmentation while maintaining efficient memory usage. 

```c
#include <stdlib.h>
#include <string.h>

typedef struct node {
    char* key;
    int value;
    struct node *next;
} Node;

Node* create_node(char* key, int value) {
    Node *new_node = (Node*)malloc(sizeof(Node));

    if (new_node == NULL) return NULL;

    new_node->key = malloc(strlen(key) + 1);

    if (new_node->key == NULL) {
        free(new_node);
        return NULL;
    }

    strcpy(new_node->key, key);
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

Node* insert_sorted(Node **head, char* key, int value) {
    Node *new_node = create_node(key, value);

    if (new_node == NULL) return NULL;

    // Insert at the head of the list.
    if (*head == NULL || strcmp((*head)->key, key) > 0) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node *current = *head;

        while (current->next != NULL && strcmp(current->next->key, key) < 0) {
            current = current->next;
        }

        new_node->next = current->next;
        current->next = new_node;
    }

    return new_node;
}
```
This example uses global variables for simplicity, but in a multithreaded environment you would need to use some sort of locking mechanism such as mutexes or atomic operations. Also, this code doesn't handle the deletion and doesn't free allocated memory. You should always consider these aspects when designing your own data structures and algorithms in C. 

