["The task you're asking for involves quite a bit of code and requires extensive experience in concurrent programming and efficient memory management. Here's a simple example of how you could begin implementing such a function using pthread mutexes and realloc. This is not an exhaustive solution, but it gives you an idea of the approach to take:

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <assert.h>

typedef struct record {
    long offset;
    int key;
    double timestamp; 
} Record;

typedef struct records_array {
    pthread_mutex_t lock;
    Record *records;
    size_t current_size;
    size_t max_size;
} RecordsArray;

RecordsArray* create_array(size_t initial_size, size_t max_size) {
    assert(initial_size <= max_size);

    RecordsArray *array = malloc(sizeof(*array));
    if (!array) return NULL;

    array->records = calloc(max_size, sizeof(Record));
    if (!array->records) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    array->current_size = 0;
    array->max_size = max_size;

    // initialize records with current time
    for (size_t i = 0; i < initial_size; ++i) {
        array->records[i].timestamp = (double)time(NULL); 
    }

    return array;
}

void resize_array(RecordsArray *array, size_t new_max_size) {
    assert(new_max_size > array->current_size);

    pthread_mutex_lock(&array->lock);

    Record* new_records = realloc(array->records, sizeof(Record) * new_max_size);
    if (new_records) { 
        array->records = new_records;
        array->max_size = new_max_size;
    }

    pthread_mutex_unlock(&array->lock);
}

void add_record(RecordsArray *array, Record record) {
    pthread_mutex_lock(&array->lock);

    if (array->current_size >= array->max_size) {
        resize_array(array, array->max_size*2);  // double the size when resizing
    }

    array->records[array->current_size++] = record; 

    pthread_mutex_unlock(&array->lock);
}
```
Note: This code is a simplification and does not fully address all the requirements you mentioned. It doesn't include logging, error handling, backward compatibility with existing memory management practices or garbage collection process. Moreover, it is important to understand that the choice of thread synchronization mechanisms (mutexes vs lock-free) depends on the specifics of your application and its concurrency needs.
"]

