    srand((unsigned int)time(NULL));

    // Allocate memory for the records array.
    Record* records = malloc(num * sizeof(Record));
    if (records == NULL) {
        return NULL;
    }

    // Allocate memory for the input strings array.
    char** inputStrings = malloc(num * sizeof(char*));
    if (inputStrings == NULL) {
        free(records);
        return NULL;
