        // Initialize each record with random values.
        records[i].coordinate[0] = rand() % 10;
        records[i].coordinate[1] = rand() % 10;
        records[i].coordinate[2] = rand() % 10;
        records[i].tag = 'A' + (rand() % 26);
        records[i].timestamp = time(NULL) - rand() % 3600; // Random timestamp within the last hour.

        // Allocate memory for the input string and set it to the corresponding tag.
