        if (inputStrings[i] == NULL) {
            freeAllMemory(records, inputStrings, i);
            return NULL;
        }
        sprintf(inputStrings[i], "%c", records[i].tag);
        records[i].inputString = inputStrings[i];
    }

    // Deallocate memory when not needed.
    freeAllMemory(records, inputStrings, num);

    return records;
}

void freeAllMemory(Record* records, char** inputStrings, int num) {
    if (records != NULL) {
        free(records);
    }
    if (inputStrings != NULL) {
        for (int i = 0; i < num; i++) {
            if (inputStrings[i] != NULL) {
                free(inputStrings[i]);
            }
        }
        free(inputStrings);
    }
}

float calculateAverageDistance(Record* records, int num) {
    float totalDistance = 0.0f;

    for (int i = 0; i < num - 1; i++) {
        for (int j = i + 1; j < num; j++) {
            // Calculate the Euclidean distance between each pair of coordinates.
            float dx = records[i].coordinate[0] - records[j].coordinate[0];
            float dy = records[i].coordinate[1] - records[j].coordinate[1];
            float dz = records[i].coordinate[2] - records[j].coordinate[2];

            totalDistance += sqrtf(dx * dx + dy * dy + dz * dz);
        }
    }

    return totalDistance / (num * (num - 1) / 2); // Average distance.
}
```

