    if (manager == NULL) {
        printf("Allocation failed.");
        exit(1);
    }

    manager->records = malloc(initialCapacity * sizeof(Record*));
    manager->capacity = initialCapacity;
    manager->growth_factor = growthFactor;
    manager->size = 0;
    manager->maxKey = 0;

    return manager;
}

void addRecord(MemoryManager *manager, long offset) {
    if (manager->size == manager->capacity) {
        manager->capacity = manager->capacity * manager->growth_factor;
        manager->records = realloc(manager->records, manager->capacity * sizeof(Record*));

        if (manager->records == NULL) {
