#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
    long* offset_ptr;
    int* key_ptr;
} Record;

Record** allocate(long length, int range) {
    if (length <= 0) return NULL;

    // Allocate memory for arrays
    long* offsets = malloc(sizeof(long)*length);
    int* keys = calloc(length, sizeof(int));  // initialize to zero

    // Check allocation successful
    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Allocate memory for records and initialize
    Record** records = malloc(sizeof(Record*)*length);
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // for thread safety
    for (long i = 0; i < length; ++i) {
        records[i] = malloc(sizeof(Record));

        if (!records[i]) {
            pthread_mutex_lock(&lock);  // lock before modifying structure
            for (long j = 0; j < i; ++j) free(records[j]);  // free previously allocated memory
            pthread_mutex_unlock(&lock);

            free(offsets);
            free(keys);
            return NULL;
        }

        records[i]->value = rand() % range;  // initialize to random number within range
        records[i]->offset_ptr = &offsets[i];  // reference specific index in offset array
        records[i]->key_ptr = &keys[i];  // reference specific index in key array
    }

    return records;
}

void deallocate(Record** records, long length) {
    if (!records) return;

    for (long i = 0; i < length; ++i) free(records[i]);  // free each record
    free(records);  // free array of pointers
}
```

This implementation uses a mutex to ensure thread safety during the allocation and deallocation of memory. However, this does add some overhead as multiple threads will be blocked while the mutex is held. A more efficient approach might involve using a lock-free data structure, such as a lock-free list or queue, depending on your specific needs and constraints.

Please remember to compile with `-pthread` flag for POSIX threading support if you are working in Linux or Unix-based systems.
