["Here's an example of how you could approach this problem using C++. This code makes use of C++14 features such as `std::shared_timed_mutex` and `std::chrono` for thread-safe operations, `std::unordered_map` to store the cache data, and a `while` loop in combination with `std::condition_variable` for the cache eviction strategy:

```cpp
#include <shared_mutex>
#include <thread>
#include <chrono>
#include <unordered_map>
#include <condition_variable>
#include <string>

struct CacheEntry {
    std::string page_id;
    std::chrono::system_clock::time_point request_timestamp;
    std::string response_data;
    int status_code;
    std::chrono::duration<int> cache_expiry_time;
};

class Cache {
private:
    std::shared_timed_mutex mutex_;
    std::unordered_map<std::string, CacheEntry> cacheMap_;
    bool exitThread_{false};
    std::thread evictionThread_;
    std::condition_variable cv_;

public:
    Cache() {
        evictionThread_ = std::thread([this] { EvictLoop(); });
    }

    ~Cache() {
        exitThread_ = true;
        evictionThread_.join();
    }

    void Put(const std::string& key, const CacheEntry& value) {
        std::unique_lock<std::shared_timed_mutex> lock(mutex_);
        cacheMap_[key] = value;
        cv_.notify_one();  // Notify eviction thread of new entry
    }

    bool Get(const std::string& key, CacheEntry& value) {
        std::shared_lock<std::shared_timed_mutex> lock(mutex_);
        auto it = cacheMap_.find(key);
        if (it != cacheMap_.end()) {
            value = it->second;
            return true;
        }
        return false;
    }

private:
    void EvictLoop() {
        while (!exitThread_) {
            std::unique_lock<std::shared_timed_mutex> lock(mutex_);

            // Wait until cacheMap is not empty or exit thread is requested
            cv_.wait(lock, [this] { return !cacheMap_.empty() || exitThread_; });

            auto now = std::chrono::system_clock::now();

            for (auto it = cacheMap_.begin(); it != cacheMap_.end(); /* no increment */) {
                if (now - it->second.request_timestamp >= it->second.cache_expiry_time) {
                    // Entry is expired, remove from cache
                    it = cacheMap_.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }
};
```
This class provides thread-safe methods for getting and putting values into the cache. The eviction loop runs in a separate thread, which removes expired entries from the cache whenever new entries are added or when there is nothing to do (in case of an empty map). This implementation ensures that only one thread at a time can modify the cacheMap and it also allows multiple threads to read from the cache simultaneously.
"]

