['Here is a high level approach to solve this task in C using POSIX threading and file I/O operations. The solution assumes that the data in binary files are laid out identifiers followed by doubles and each identifier has one double following it. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    char id;
    double value;
} Record;

// Global lock for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

double computeAverage(Record* records, int count, double threshold) {
    double sum = 0.0;
    int validCount = 0;

    for (int i = 0; i < count; ++i) {
        if (records[i].value > threshold) {
            sum += records[i].value;
            ++validCount;
        }
    }
    return validCount > 0 ? sum / validCount : 0.0;
}

void* processRecords(void* arg) {
    FILE* file = fopen("input.bin", "rb");

    if (file == NULL) {
        pthread_exit(NULL); // error handling
    }

    Record record;
    double average = 0.0, threshold = 10.0;  // You can change the threshold as per requirement.
    int count = 0;

    while (fread(&record, sizeof(Record), 1, file) == 1) {
        pthread_mutex_lock(&mutex);
        ++count;
        average += record.value / count;
        if (abs(average - record.value) > threshold * count) {
            // Ignore the outlier
            --count;
            average = computeAverage(records, count, threshold);
        }
        pthread_mutex_unlock(&mutex);
    }

    fclose(file);
    FILE* outputFile = fopen("output.bin", "wb");  // Create the file to store the average of doubles
    if (outputFile != NULL) {
        fwrite(&average, sizeof(double), 1, outputFile);  
        fclose(outputFile);
    }

    pthread_exit(NULL);
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, processRecords, NULL) != 0) {
        return 1; // error handling
    }

    if (pthread_join(thread, NULL) != 0) {
        return 2; // error handling
    }

    pthread_mutex_destroy(&mutex);
    return 0;
}
```
This code reads the binary file in a separate thread to avoid blocking the main thread. It uses a mutex for thread safety and calculates the running average without storing individual values. If an outlier is detected, it computes the new average excluding that value. In case of a corrupted or incomplete file, reading will terminate early. The resulting average is written to another binary file named "output.bin".
']

['Implementation of this task in C would require more than just a simple code block as it involves many complex operations like memory allocation/deallocation, multithreading synchronization, data generation, error checking etc. Below is an outline for the program structure but note that actual implementation would be much larger and more complex:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#define MAX_SIZE 10000

typedef struct {
    double d;
    int i;
    char *str;
} MyStruct;

MyStruct* memPool[MAX_SIZE];
int poolTop = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

char* generateRandomString(size_t length) {
    char *str = malloc(length + 1);
    for (size_t i = 0; i < length; i++) 
        str[i] = 'a' + rand() % ('z'-'a'); //generate random lowercase letter
    str[length] = '\0';
    return str;
}

MyStruct* allocate(size_t size, int seed) {
    if (size > MAX_SIZE || size <= 0 || seed < 1) {
        fprintf(stderr, "Invalid parameters\n");
        return NULL;
    }

    srand(seed); //set random seed

    pthread_mutex_lock(&lock); //acquire lock to protect poolTop increment and access

    if (poolTop + size > MAX_SIZE) {
        fprintf(stderr, "Not enough space in the memory pool\n");
        return NULL;
    }

    for (size_t i = 0; i < size; i++) {
        memPool[poolTop] = malloc(sizeof(MyStruct)); //allocate memory for new struct
        memPool[poolTop]->d = ((double) rand() / (RAND_MAX)); //generate random double
        memPool[poolTop]->i = rand(); //generate random int
        size_t strLength = 1 + rand() % 20; //generate string length between 1 and 20
        memPool[poolTop]->str = generateRandomString(strLength); //allocate and fill string
        poolTop++;
    }

    pthread_mutex_unlock(&lock); //release lock after allocation

    return &memPool[poolTop - size];
}

void deallocate() {
    for (int i = 0; i < poolTop; i++) {
        free(memPool[i]->str); //free string inside each struct
        free(memPool[i]); //free struct
    }
    pthread_mutex_destroy(&lock); //destroy lock to prevent memory leaks in case of a crash
}
```
This program uses a simple fixed-size memory pool, which may not be the most optimal solution for dealing with large amounts of data. Implementing different allocation strategies like first-fit, best-fit etc., could lead to better cache locality and reduce fragmentation. 

Please note that actual implementation would require more code and a thorough understanding of memory management, multithreading, error handling and logging principles. It is also recommended to perform extensive testing and profiling for optimizing performance, especially in the multithreaded environment.
']

