void *cacheMediaCodec(void *arg) {
    MediaCodec *codec = (MediaCodec *) arg;

    pthread_mutex_lock(&cacheLock);
    if (!codec->initialized) {
        // Initialize the media codec and set initialized flag to 1
        printf("Initializing codec\n");
        codec->initialized = 1;
    } else {
        // Recycle the media codec and set it to null
        printf("Recycling codec\n");
        memset(codec, 0, sizeof(MediaCodec));
