    scanf("%d %f %f", &location[i].id, &location[i].latitude, &location[i].longitude);
    char name[100];
    fgets(name, sizeof(name), stdin);
    location[i].name = strdup(name);
    pthread_mutex_unlock(&lock);
}

void read_from_file(location_t* location, int i, FILE *fp){
