["Here is a simplified version of what this might look like in C. This doesn't include the third-party logging service but provides the basic layout for handling events with timestamps, priority levels and messages dynamically allocated memory. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Structure representing an event log record
typedef struct Event {
    long offset; // Offset can be a long integer type
    int key;     // Key can be any integer type
    double timestamp;  // Timestamp will be represented as double to handle fractional seconds
    int priority;      // Priority level for the event
    char* message;     // Message for the event
} Event;

// Structure representing an event log system
typedef struct EventLogSystem {
    pthread_mutex_t lock;  // Mutual exclusion lock to control access to the shared resource
    int capacity;          // Current maximum capacity of the array
    int size;              // Current number of elements in the array
    Event** events;        // Array of event pointers
} EventLogSystem;

// Function to initialize an empty log system
EventLogSystem* init_log() {
    EventLogSystem* log = malloc(sizeof(EventLogSystem));
    if (log == NULL) return NULL;  // Handle allocation failure gracefully

    pthread_mutex_init(&log->lock, NULL);  // Initialize the mutual exclusion lock
    log->capacity = 1024;  // Initial capacity of the array
    log->size = 0;  // No elements in the array initially

    // Allocate memory for the events array
    log->events = malloc(log->capacity * sizeof(Event*));
    if (log->events == NULL) {
        free(log);
        return NULL;  // Handle allocation failure gracefully
    }

    return log;
}

// Function to add an event to the system, dynamically allocating memory for it
void add_event(EventLogSystem* log, long offset, int key, double timestamp, int priority, char* message) {
    pthread_mutex_lock(&log->lock);  // Acquire the mutual exclusion lock

    if (log->size == log->capacity) {  // If the array is full, resize it
        log->capacity *= 2;
        Event** new_events = realloc(log->events, log->capacity * sizeof(Event*));
        if (new_events == NULL) {
            pthread_mutex_unlock(&log->lock);  // Release the mutual exclusion lock
            return;  // Handle allocation failure gracefully
        } else {
            log->events = new_events;
        }
    }

    Event* event = malloc(sizeof(Event));  // Dynamically allocate memory for a new event
    if (event == NULL) {
        pthread_mutex_unlock(&log->lock);  // Release the mutual exclusion lock
        return;  // Handle allocation failure gracefully
    }

    event->offset = offset;
    event->key = key;
    event->timestamp = timestamp;
    event->priority = priority;
    event->message = message;

    log->events[log->size++] = event;  // Add the new event to the array

    pthread_mutex_unlock(&log->lock);  // Release the mutual exclusion lock
}
```
This is a simple representation of an event logging system. Real world applications would require more comprehensive error handling, possibly including checks for integer overflows and memory leaks. Also, this does not include the third-party integration which can be handled separately or in conjunction with the EventLogSystem structure. Further optimizations like read/write buffering, concurrent write optimization etc., could be implemented based on specific requirements and constraints.
