    int key;
    double timestamp;
} record;

record *records = NULL;
size_t numRecords = 0, capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *allocateMemory(size_t size) {
    void *memory = malloc(size);
    if (memory == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(1);
    }
    return memory;
}

void resizeRecords() {
    capacity = capacity ? 2 * capacity : 4;
    records = realloc(records, capacity * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(1);
    }
}

void appendRecord(int key) {
    pthread_mutex_lock(&mutex);

    if (numRecords == capacity) resizeRecords();

    records[numRecords].offset = numRecords; // or whatever the offset is supposed to be
    records[numRecords].key = key;
    records[numRecords].timestamp = time(NULL);

    numRecords++;

    pthread_mutex_unlock(&mutex);
}

int findLargestKey() {
    int largest = 0;
    for (size_t i = 0; i < numRecords; ++i) {
        if (records[i].key > largest) largest = records[i].key;
    }
    return largest;
}

void *readIntegers(void *arg) {
    int integer;

    while (scanf("%d", &integer) == 1) appendRecord(integer);

    pthread_exit(NULL);
}

// helper function to handle JSON configuration
json_object* parseConfigFile(const char* filename) {
    FILE *configFile = fopen(filename, "r");
    if (configFile == NULL) return NULL;

    // read file into a string
    fseek(configFile, 0, SEEK_END);
    long length = ftell(configFile);
    fseek(configFile, 0, SEEK_SET);

    char *buffer = malloc(length + 1);
    if (buffer == NULL) return NULL;

    fread(buffer, 1, length, configFile);
    buffer[length] = 0; // null-terminate string

    fclose(configFile);

    // parse JSON
    json_object *json = json_tokener_parse(buffer);

    free(buffer);
    return json;
}

void handleUpload() {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
        // replace these with your URL and filename
        curl_easy_setopt(curl, CURLOPT_URL, "your-url");

        FILE *file;
        file = fopen("filename", "rb");
        curl_easy_setopt(curl, CURLOPT_READDATA, file);

        res = curl_easy_perform(curl);

        if (res != CURLE_OK) fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        fclose(file);
        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
}
