['This task requires several key skills including file I/O, error handling, parallel programming, asynchronous operations, and data management. Here is a rough outline of how you might begin solving this problem in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <aio.h>
#include <time.h>
#include <sys/types.h>
#include <dirent.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

typedef struct {
    time_t eventTime;
    int severityLevel;
    char message[1024];
    int errorCode;
} LogEntry;

// Assuming the logs are stored in individual text files,
// each line representing a separate log entry.
struct dirent *de;  // directory entry for file operations
DIR *dr = opendir("path_to_logs");  // open the directory
pthread_t threads[1024];  // maximum number of threads allowed
int threadCount = 0;  // count active threads
LogEntry logEntries[1024][1024];  // assuming a max limit on logs per file
int numOfEntriesPerFile[1024] = {0};  // array to store number of entries in each file
pthread_mutex_t lock;  // used for thread safety while writing into shared resource.
clock_t start, end;
double cpu_time_used;

void* processFile(void *fileName) {
    char *name = (char*) fileName;

    int fd = openat(dirfd(dr), name, O_RDONLY);  // open the file

    if (fd == -1){
        printf("open");
        exit(0);
    }

    aiocb my_aiocb;  // initialize async IO control block
    memset(&my_aiocb, 0, sizeof(struct aiocb));  // set all bits to zero.

    my_aiocb.aio_fildes = fd;  // file descriptor of the file we're reading from.
    my_aiocb.aio_buf = logEntries[threadCount];  // pointer to buffer where read data is stored.
    my_aiocb.aio_nbytes = 1024*sizeof(LogEntry);  // number of bytes to be read from file.

    if (aio_read(&my_aiocb) < 0){
        printf("aio_read\n");
        exit(0);
    }

    while(aio_error(&my_aiocb) == EINPROGRESS){}  // loop until reading is finished.

    numOfEntriesPerFile[threadCount] = aio_return(&my_aiocb)/sizeof(LogEntry);  // store the number of entries read from file.
    pthread_mutex_lock(&lock);  // lock before writing into shared resource.
    threadCount++;  // increment count after reading each file.
    pthread_mutex_unlock(&lock);  // unlock after writing to shared resource.

    close(fd);  // close the file when done.
}

void sortAndPrintLogs() {
    LogEntry *filtered[1024];
    int count = 0;
    for (int i=0; i<threadCount; i++) {
        for (int j=0; j<numOfEntriesPerFile[i]; j++) {
            if (logEntries[i][j].severityLevel > 3) {
                filtered[count] = &logEntries[i][j];  // store logs with severity level greater than 3.
                count++;
            }
        }
    }

    qsort(filtered, count, sizeof(LogEntry*), compare);  // sort the filtered logs by event time in ascending order.

    int totalErrorCode = 0, numOfNonZeroCodes = 0;
    for (int i=0; i<count; i++) {
        if (filtered[i]->errorCode != 0){
            totalErrorCode += filtered[i]->errorCode;
            numOfNonZeroCodes++;
        }
        printf("Log: %s\n", filtered[i].message);  // print the log.
    }

    double averageErrorCode = (double)totalErrorCode/numOfNonZeroCodes;
    printf("Average Error Code Value: %f\n", averageErrorCode);  // print average error code value for all logs excluding zero.
}

int compare(const void *a, const void *b){
    LogEntry **entryA = (LogEntry**) a;
    LogEntry **entryB = (LogEntry**) b;

    if((*entryA)->eventTime > (*entryB)->eventTime) return 1;
    else if((*entryA)->eventTime < (*entryB)->eventTime) return -1;
    else return 0;
}

int main() {
    while ((de = readdir(dr)) != NULL){
        if (!strcmp (de->d_name, "..") || !strcmp (de->d_name, ".")) continue;

        pthread_create(&threads[threadCount], NULL, processFile, de->d_name);  // create a new thread to process each file.
    }

    for(int i=0;i<threadCount;++i) {
       if(pthread_join(threads[i],NULL)!=0){
           perror("Failed to join threads\n");
       }
    }
    closedir(dr);  // close the directory when done.

    start = clock();
