#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    char *name;
    int priority;
    time_t dueDate;
    enum {PENDING, INPROGRESS, COMPLETED} status;
} Task;

typedef struct {
    pthread_mutex_t lock;
    Task *tasks;
    size_t numTasks;
    size_t maxNumTasks;
} TaskManager;

void initTask(Task *task, const char *name, int priority) {
    task->name = strdup(name);
    task->priority = priority;
    task->dueDate = time(NULL) + (rand() % 604800); // Random date within next week.
    task->status = PENDING;
}

void initTaskManager(TaskManager *manager, size_t initialSize) {
    manager->maxNumTasks = initialSize;
    manager->numTasks = 0;
    manager->tasks = malloc(initialSize * sizeof(Task));
    pthread_mutex_init(&manager->lock, NULL);
}

void addTask(TaskManager *manager, const char *name, int priority) {
    pthread_mutex_lock(&manager->lock);

    if (manager->numTasks == manager->maxNumTasks) {
        manager->tasks = realloc(manager->tasks, 2*manager->maxNumTasks * sizeof(Task));
        manager->maxNumTasks *= 2;
    }

    initTask(&manager->tasks[manager->numTasks], name, priority);
    manager->numTasks++;

    pthread_mutex_unlock(&manager->lock);
}

void updateTask(TaskManager *manager, size_t index, const char *name, int priority) {
    pthread_mutex_lock(&manager->lock);

    free(manager->tasks[index].name);
    initTask(&manager->tasks[index], name, priority);

    pthread_mutex_unlock(&manager->lock);
}

void deleteTask(TaskManager *manager, size_t index) {
    pthread_mutex_lock(&manager->lock);

    free(manager->tasks[index].name);
    manager->numTasks--;
    if (index < manager->numTasks) // If not the last task.
        memmove(&manager->tasks[index], &manager->tasks[index+1], 
                (manager->numTasks - index)*sizeof(Task));

    pthread_mutex_unlock(&manager->lock);
}
```
