```java
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ConcurrentHashMap;
import javax.xml.bind.DatatypeConverter;

public class HashGenerator {
    private static final int LARGE_SIZE = 1024; // 1KB

    // A simple cache using a concurrent hash map for thread safety and high performance.
    private ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        HashGenerator generator = new HashGenerator();

        // Testing the function with a large string (greater than 1KB in this case).
        System.out.println("MD5 hash: " + generator.hashString("Large String Here..."));
    }

    public String hashString(String input) {
        if (cache.containsKey(input)) return cache.get(input); // If string is cached, return it from there.

        try {
            MessageDigest md;

            // If the string is large, we'll use SHA-256 as it's more secure but slower than MD5.
            if (input.getBytes(StandardCharsets.UTF_8).length > LARGE_SIZE) {
                md = MessageDigest.getInstance("SHA-256"); // Slow but secure algorithm for large strings.
            } else {
                md = MessageDigest.getInstance("MD5"); // Faster and less secure algorithm for smaller strings.
            }

            byte[] digest = md.digest(input.getBytes());
            String hash = DatatypeConverter.printHexBinary(digest).toLowerCase();

            cache.put(input, hash); // Store the computed hash in the cache for future use.

            return hash;
        } catch (Exception e) {
