```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct entry {
    long timestamp;
    int key;
    char* value;
} Entry;

typedef struct database {
    Entry** entries;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} Database;

Database db;
size_t MAX_SIZE = 1024 * 1024; //predefined limit of total memory usage

void* safeMalloc(size_t size) {
    void* mem = malloc(size);
    if (mem == NULL) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    return mem;
}

// Initialize the database and allocate memory for entries
void initDatabase(size_t initialSize) {
    db.entries = safeMalloc(initialSize * sizeof(Entry*));
    db.capacity = initialSize;
    db.size = 0;
    pthread_mutex_init(&db.lock, NULL);
}

// Insert a new entry into the database
void insert(long timestamp, int key, const char* value) {
    pthread_mutex_lock(&db.lock);
    if (db.size == db.capacity) {
        // If we're out of space, double our capacity
        db.entries = safeRealloc(db.entries, sizeof(Entry*) * db.capacity * 2);
        db.capacity *= 2;
    }

    for (size_t i = 0; i < db.size; ++i) {
        if (db.entries[i]->key == key) {
            fprintf(stderr, "Duplicate key: %d\n", key);
            return;
        }
    }

    Entry* entry = safeMalloc(sizeof(Entry));
    entry->timestamp = timestamp;
    entry->key = key;
    entry->value = safeMalloc(strlen(value) + 1);
    strcpy(entry->value, value);

    db.entries[db.size++] = entry;
    pthread_mutex_unlock(&db.lock);
}
```

Please note that you will need to implement `safeRealloc` and the rest of the functions based on this outline according to your own implementation strategy, which may involve a different approach or using libraries like glib or other data structures for managing memory more efficiently. Also remember that error handling is key in such scenarios and needs to be considered thoroughly.
