            fprintf(stderr, "Key out of range\n");
            continue;
        }

        int i = 0;
        for (; i < *size; ++i) {
            if (records[i].key == key) {
                break;
            }
        }

        // If no duplicate found, add the key to records.
        if (i >= *size) {
            record r = { .offset = &offsets[*size], .key = key };
            records[(*size)++] = r;

            // Resize array dynamically when needed.
            if (*size % 10 == 0) {
                long* temp_offsets = realloc(offsets, *size * sizeof(long));
                record* temp_records = realloc(records, *size * sizeof(record));

                // Handle failed allocation.
                if (temp_offsets == NULL || temp_records == NULL) {
                    perror("Memory reallocation failed");
                    free(temp_records);
                    fclose(fp);
                    return NULL;
                }

                offsets = temp_offsets;
                records = temp_records;
            }
        } else {
            printf("Duplicate key found: %d\n", key);
        }
    }

    if (!feof(fp)) {
        perror("Error while reading file");
        free(offsets);
        fclose(fp);
        return NULL;
    }

    fclose(fp);
    return records;
}
```
Please note that the code above does not cover all requirements, such as reserving keys and handling errors on key read from file. It also assumes that `INT_MAX` is defined in your environment. You may need to adjust this code according to the specifics of your project. Please consider using a more robust data structure for storing records if performance or memory usage are concerns, such as a hash table or balanced tree.
