class RandomGenerator 
{
private:
    float minVal, maxVal;

public:
    RandomGenerator(float min, float max) : minVal(min), maxVal(max) {}

    float getRandomFloat() { return minVal + static_cast <float> (rand()) /( static_cast <float> (RAND_MAX/(maxVal-minVal))); }
    int getRandomInt() { return rand() % ((int)(maxVal - minVal + 1)) + minVal; }

