} record;

record *records = NULL;
int array_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_memory(void* ptr) {
    int new_size = *((int*)ptr);

    // Resize the array and copy existing records to the new array
    record *new_records = realloc(records, new_size * sizeof(record));
    if (new_records == NULL) {
        printf("Failed to allocate memory for records\n");
        return;
    }

    // Initialize the newly allocated records
    for (int i = array_size; i < new_size; ++i) {
        new_records[i].offset = 0;
        new_records[i].key = 0;
        new_records[i].timestamp = time(NULL);
    }

    records = new_records;
    array_size = new_size;
}

void* populate_array(void* ptr) {
    int key, i = 0;

    // Acquire lock before modifying shared data
    pthread_mutex_lock(&lock);

    while (scanf("%d", &key) != EOF) {
        if (i == array_size) {
            int new_size = array_size * 2; // Double the size of the array each time it is full
            pthread_mutex_unlock(&lock); // Unlock while resizing array to allow other threads to modify data
            allocate_memory((void*)&new_size);
            pthread_mutex_lock(&lock);
        }

        records[i].key = key;
        ++i;
    }

    // Release lock after modifying shared data
    pthread_mutex_unlock(&lock);
}
```
