#include <string.h>

typedef struct {
    double value;
    char* type;
} Measurement;

Measurement* read_measurements(const char* filepath, int* count) {
    FILE *file = fopen(filepath, "r");
    if (file == NULL) {
        printf("Failed to open the file.\n");
        exit(-1);
    }

    Measurement* measurements = malloc(sizeof(*measurements));
    int capacity = 1;
    *count = 0;

    double value;
    char type[256];
    while (fscanf(file, "%lf %s", &value, type) == 2) {
        if (*count >= capacity) {
            capacity *= 2;
            measurements = realloc(measurements, sizeof(*measurements)*capacity);
        }
        Measurement* new_measur = &measurements[*count];

        // Note: we assume type is a string literal (i.e., not modified after assignment)
        new_measur->type = strdup(type); 
        new_measur->value = value;
        (*count)++;
    }

    fclose(file);
    return measurements;
}

double calculate_average(const Measurement* measur, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; ++i) {
        sum += measur[i].value;
    }

    return (count != 0) ? (sum / count) : 0.0;
}
```
