const fs = require('fs');

function readFilePortion(filePath, start, end) {
    // Check if the file exists and has necessary permissions
    try {
        fs.accessSync(filePath, fs.constants.R_OK);
    } catch (err) {
        console.error('Error: Insufficient permissions or file does not exist');
        return null;
    }

    let content = '';

    // Create a read stream from the specified portion of the file 
    const readStream = fs.createReadStream(filePath, {start: start, end: end});

    // Handle any errors while reading the file
    readStream.on('error', function(err){
        console.log("Error: ", err);
    });

    // When data is available, append it to content variable
    readStream.on('data', function(chunk) {
       content += chunk;
    });

    // When file reading ends, return the content
    readStream.on('end', function() {
        return content;
    });
}
```
