['Here's a simplified C implementation of what you asked for. Please note that actual production-level code would require much more comprehensive error checking and handling. In a real-world scenario, it is also recommended to use operating system services for memory management and error reporting instead of building them from scratch. This example uses a very basic logging mechanism with printf statements, but in a real-world application, you would want to use a logging library or integrate the logs into your existing infrastructure.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/resource.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
    double timestamp;
} Record;

// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocateMemory(int n) {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    long maxMem = usage.ru_maxrss; // Get maximum resident set size used (in kilobytes)

    if (maxMem > 1048576) { // 1 GB in kb
        printf("Memory limit reached.\n");
        return NULL;
    }

    Record* array = malloc(n * sizeof(Record));
    if (!array) {
        printf("Allocation failed.\n");
        return NULL;
    }

    time_t now;
    for (int i = 0; i < n; ++i) {
        now = time(NULL); // Get current time in seconds since the epoch.
        array[i].key = i+1;
        array[i].timestamp = now;
    }

    return array;
}

int main() {
    int n = 0;

    printf("Enter number of records: ");
    scanf("%d", &n);

    pthread_mutex_lock(&mutex); // Lock mutex to ensure thread safety
    Record* array = allocateMemory(n);
    pthread_mutex_unlock(&mutex); // Unlock mutex after allocation is done

    if (array) {
        for (int i = 0; i < n; ++i) {
            printf("Record %d: Key=%d, Timestamp=%.f\n", i+1, array[i].key, array[i].timestamp);
        }

        free(array); // Free allocated memory when done
    }

    return 0;
}
```
This code implements a custom logging mechanism to monitor system resource usage and log any allocation failures. The function `allocateMemory` is protected by a mutex for thread safety, allowing it to be safely accessed from multiple threads in a larger system. Note that this simple implementation doesn't actually handle concurrent access, but would need additional complexity to handle actual concurrency.
']

