    exit(EXIT_FAILURE);
}

void validateAmount(Transaction* transactions, int numTransactions) {
    double total = 0.0;
    for (int i = 0; i < numTransactions; ++i) {
        total += transactions[i].amount;
        if (total > AMOUNT_THRESHOLD) handleError("Transaction amount exceeds threshold");
    }
}

Transaction* allocateMemory(int numTransactions) {
    Transaction *transactions = malloc(numTransactions * sizeof(Transaction));
    if (!transactions) handleError("Failed to allocate memory for transactions.");

    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < numTransactions; ++i) {
        transactions[i].transaction_id = rand();
        transactions[i].amount = ((double)rand() / (double)(RAND_MAX)) * 1000.0; // Random amount within [0, 1000]

        int descIndex = rand() % NUM_DESCRIPTIONS;
        transactions[i].description = malloc(strlen(DESCRIPTIONS[descIndex]) + 1);
        if (!transactions[i].description) handleError("Failed to allocate memory for description.");

        strcpy(transactions[i].description, DESCRIPTIONS[descIndex]);
        transactions[i].timestamp = time(NULL);
    }

    validateAmount(transactions, numTransactions);
    return transactions;
}

void deallocateMemory(Transaction *transactions, int numTransactions) {
    for (int i = 0; i < numTransactions; ++i) {
        free(transactions[i].description);
