        total += measurements[(*size)++].value;

        // Dynamically reallocate memory as needed
        Measurement *tmp = realloc(measurements, sizeof(*measurements) * ((*size) + 1));
        if (tmp == NULL) {
            free(measurements);
            fclose(file);
            printf("Error: Failed to reallocate memory for measurements.\n");
            return NULL;
        }
        measurements = tmp;
    }

    double average = total / (*size);
    printf("The average value of all measurements is %f\n", average);

    fclose(file);
    return measurements;
}
