    record *newRecord;

    if (pool->currentSize == pool->maxSize) {
        size_t newMaxSize = pool->maxSize * 2;
        pool->records = realloc(pool->records, sizeof(record*) * newMaxSize);
        assert(pool->records != NULL);

        pool->maxSize = newMaxSize;
    }

    newRecord = malloc(sizeof(record));
