        // Check if the processed event should be cached
        pthread_mutex_lock(&cache_lock);
        cache[cache_index] = &event;  // Store a pointer to the event in the cache
        cache_index = (cache_index + 1) % CACHE_SIZE;  // Move to next slot, wrap around if necessary
        pthread_mutex_unlock(&cache_lock);
    }
}

void process_events() {
    for (int i = 0; i < num_events; i += batch_size) {
        size_t remaining = num_events - i;
        size_t current_batch_size = remaining < batch_size ? remaining : batch_size;

        Event *buffer = allocate_and_initialize(current_batch_size);
        if (buffer == NULL) {
            return;
        }

        process_batch(buffer, current_batch_size);
        free(buffer);  // Deallocate memory when done processing the batch
    }
}
