#include <vector>

class Record {
public:
    int value;
    std::size_t keyIndex, offsetIndex;
};

// Custom deleter for unique_ptr to clean up memory pool
struct Deleter {
    void operator()(void* pointer) const{
        ::operator delete(pointer);
        // Add cleanup logic here if needed
    }
};

class RecordManager {
public:
    RecordManager(std::size_t keyPoolSize, std::size_t offsetPoolSize) 
    :keyArray_(new int[keyPoolSize], Deleter()),
     offsetArray_(new long int[offsetPoolSize], Deleter()){}

    void addRecord(int value, std::size_t keyIndex, std::size_t offsetIndex) {
        // Get a write lock to ensure exclusive access for the scope of this function
        std::unique_lock<std::shared_mutex> lock(mutex_);

        Record record{value, keyIndex, offsetIndex};

        if (records_.find(record.key) == records_.end()) {
            // Allocate memory for the new record in the memory pool and add it to the map
            std::size_t index = currentIndex_;
            records_.emplace(record.value, Record{index});

            // Update current index for next allocation
            currentIndex_ += sizeof(Record);
        } else {
            std::cout << "Key already exists in the map!" << std::endl;
        }
    }

    void updateRecord(int value, std::size_t key) {
        // Get a read lock to ensure shared access for the scope of this function
        std::shared_lock<std::shared_mutex> lock(mutex_);

        auto it = records_.find(key);
        if (it != records_.end()) {
            Record& record = it->second;

            // Perform update operation with memory pool index
            *(Record*)((char*)recordPool_ + record.poolIndex) = Record{value, key};
        } else {
            std::cout << "Key not found in the map!" << std::endl;
        }
    }

    void removeRecord(std::size_t key) {
        // Get a write lock to ensure exclusive access for the scope of this function
        std::unique_lock<std::shared_mutex> lock(mutex_);

        auto it = records_.find(key);
        if (it != records_.end()) {
            // Erase record from map
            records_.erase(it);

            // Mark memory as free for future use
            // This step depends on how you implement your memory pool and can be removed if not required
        } else {
            std::cout << "Key not found in the map!" << std::endl;
        }
    }

private:
    std::unordered_map<std::size_t, Record> records_; // Map to store records based on keys
    std::shared_mutex mutex_; // Read/write lock for concurrency handling
    std::unique_ptr<int[]> keyArray_; // Integer array
    std::unique_ptr<long int[]> offsetArray_; // Long integer array

    // Pointers to the memory pool and current index for allocation
    void* recordPool_ = nullptr; 
    std::size_t currentIndex_ = 0; 
};
