#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char* file_name;
    off_t offset;
    int ref_count;
    char* buffer;
} inode;

inode** record = NULL;
int count = 0, capacity = 2;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize(size_t size) {
    if (size > 500) {
        printf("Invalid input. Size must be less than 500.\n");
        return;
    }

    record = malloc(sizeof(inode*) * capacity);
    for (int i = 0; i < size; i++) {
        char file_name[20];
        sprintf(file_name, "File%d", i + 1);
        off_t offset = rand() % 10001;

        inode* node = malloc(sizeof(inode));
        node->file_name = strdup(file_name);
        node->offset = offset;
        node->ref_count = 0;
        node->buffer = calloc(1, sizeof(char));

        record[i] = node;
    }

    count = size;
}

void resize() {
    if (count == capacity)
        capacity *= 2;
    else if (count < capacity / 4 && capacity > 2)
        capacity /= 2;
    else
        return;

    record = realloc(record, sizeof(inode*) * capacity);
}

void write_buffer(int index, char* data, size_t len) {
    pthread_mutex_lock(&lock);

    inode* node = record[index];
    node->ref_count++;
    if (node->ref_count > 1)
        printf("Warning: Multiple writers detected for file %s.\n", node->file_name);

    size_t new_len = strlen(node->buffer) + len + 1;
    node->buffer = realloc(node->buffer, sizeof(char) * new_len);
    strcat(node->buffer, data);

    pthread_mutex_unlock(&lock);
}

void read_buffer(int index) {
    pthread_mutex_lock(&lock);

    inode* node = record[index];
    printf("File: %s\nOffset: %lld\nContents:\n%s\n", node->file_name, (long long)node->offset, node->buffer);

    pthread_mutex_unlock(&lock);
}

void clear_buffer(int index) {
    pthread_mutex_lock(&lock);

    inode* node = record[index];
    free(node->buffer);
    node->buffer = calloc(1, sizeof(char));

    pthread_mutex_unlock(&lock);
}
```

