    atomic_int refcount;
} record;

record* records = NULL;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
char *statusFlags = NULL; // Assume it's a char array for simplicity, actual type depends on how you use it.
size_t numRecords = 0;
size_t recordCapacity = 0;

void reinitializeRecord(int key, long offset) {
    pthread_rwlock_wrlock(&rwlock);

    if (key >= recordCapacity || statusFlags[key] == 0) {
        // Handle error as needed.
        return;
    }

    records[key].offset = offset;
    records[key].timestamp = time(NULL);

    pthread_rwlock_unlock(&rwlock);
}

void addRecord(int key, long offset) {
    pthread_rwlock_wrlock(&rwlock);

    if (key >= recordCapacity || statusFlags[key] == 1) {
        // Handle error as needed.
        return;
    }

    records[key].offset = offset;
    records[key].timestamp = time(NULL);
    atomic_store(&records[key].refcount, 0);
    ++numRecords;
    statusFlags[key] = 1;

    pthread_rwlock_unlock(&rwlock);
}

void removeRecord(int key) {
    pthread_rwlock_wrlock(&rwlock);

    if (key >= recordCapacity || statusFlags[key] == 0) {
        // Handle error as needed.
        return;
    }

    atomic_store(&records[key].refcount, 0);
    --numRecords;
    statusFlags[key] = 0;

    pthread_rwlock_unlock(&rwlock);
}
