void resizeArray(int newSize) {
    pthread_mutex_lock(&lock);

    record *newRecords = (record *) realloc(records, newSize * sizeof(record));
    if (newRecords != NULL) {
        records = newRecords;
        arraySize = newSize;
    } else {
