        records[index].key = rand() % (maxKeyValue - minKeyValue + 1) + minKeyValue; 

        records[index].timestamp = time(NULL) + (double)(rand() % 60); 
    } else {
        printf("Index out of bounds.\n");
    }
}

void deallocateMemory() {
    pthread_mutex_lock(&lock);

    free(records);
    records = NULL;
    arraySize = 0;

    pthread_mutex_unlock(&lock);
