        if (temp == NULL) {
            printf("Memory allocation failed.\n");
            exit(1);
        }

        temp->key = rand() % 100; // Random key values from 0 to 99
        temp->string = (char*) malloc(sizeof(char) * strSize); // Allocate memory for string in each node

        if (temp->string == NULL) {
            printf("Memory allocation failed.\n");
            exit(1);
        }

        int len = 5 + rand() % 20; // Random length from 5 to 25 characters
        for (int j = 0; j < len; ++j) {
            temp->string[j] = 'a' + rand() % ('z' - 'a'); // Random char values a-z
        }

        temp->string[len] = '\0';

        if (head == NULL) {
            head = tail = temp;
        } else {
            tail->next = temp;
            temp->prev = tail;
            tail = temp;
        }
    }

    return head;
}

// Traversal and print function for doubly linked list
void traverse_and_print(struct node* head) {
    struct node *temp = head;

    while (temp != NULL) {
        printf("Key: %d, String: %s\n", temp->key, temp->string);
        temp = temp->next;
    }
}
```
This code assumes that the maximum size of each string is 256 characters. If a random generated string length exceeds this limit, it will cause overflow. You may want to adjust the `strSize` parameter when calling `init_strings()` and `init_nodes()` functions appropriately. Also, remember to free all allocated memory when they are no longer needed to prevent memory leaks.
