#define MAX_RECORDS 1024

// Function to add a record
void addRecord(int key, const char* identifier) {
    pthread_mutex_lock(&lock); // Lock mutex before accessing shared resource

    if (dbSize < MAX_RECORDS) {
        Record* newRecord = malloc(sizeof(Record));
        newRecord->timestamp = time(NULL);
        newRecord->key = key;
        newRecord->identifier = strdup(identifier);

