#[derive(Debug, Clone)]
struct CmsError {
    details: String
}

impl fmt::Display for CmsError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write![f, "CMS Error: {}", self.details]
    }
}

impl Error for CmsError {}

// Define the function to manage settings
fn manage_settings(
    mutable_vec: &mut Vec<String>, 
    num_settings: i32, 
    cms: Arc<Vec<i32>>,
    last_index: usize, 
    max_size: usize
) -> Result<Option<&Vec<String>>, CmsError> {

    // Ensure the new size will not exceed the maximum size
    if (num_settings + mutable_vec.len() as i32) > max_size as i32 {
        return Err(CmsError{details: String::from("Insufficient memory")})
    }

    // Handle null pointers
    if ptr::eq(cms, ptr::null()) || cms.len() == 0 {
        return Err(CmsError{details: String::from("Invalid CMS configuration")});
    }

    // Traverse the CMS and add settings to the list
    let mut new_settings = Vec::with_capacity(num_settings as usize);

    for i in last_index..cms.len() {
        new_settings.push(format![cms[i]]);

        if new_settings.len() >= num_settings as usize {
            break;
        }
    }

    mutable_vec.append(&mut new_settings);

    Ok(Some(mutable_vec))
}
```
