void allocateData(size_t size, long **offsets, int **keys, Node ***nodes) {
    srand((unsigned int)time(NULL)); // seed the random number generator

    // Allocate and initialize offset array
    *offsets = (long *)malloc(sizeof(long) * size);
    if (*offsets == NULL) exit(-1); 

    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = rand() % LONG_MAX; // generate a random offset
    }

    // Allocate and initialize key array
    *keys = (int *)malloc(sizeof(int) * size);
    if (*keys == NULL) exit(-1); 

    for (size_t i = 0; i < size; ++i) {
        (*keys)[i] = rand(); // generate a random key
    }

    // Allocate and initialize node array
    *nodes = (Node **)malloc(sizeof(Node *) * size);
    if (*nodes == NULL) exit(-1); 

    for (size_t i = 0; i < size; ++i) {
        Node *node = (Node *)malloc(sizeof(Node));
        if (node == NULL) exit(-1); 

        Value *value = (Value *)malloc(sizeof(Value));
        if (value == NULL) exit(-1); 

        value->data = rand(); // generate a random data for the value struct
        time(&value->timestamp); // record current timestamp

        node->value = value;
        (*nodes)[i] = node;
    }
}

void freeData(size_t size, long **offsets, int **keys, Node ***nodes) {
    for (size_t i = 0; i < size; ++i) {
        free((*nodes)[i]->value); // Free value struct first because it's referenced in node struct
        free((*nodes)[i]); // Then free the nodes
    }

    free(*keys); 
    free(*offsets); 
    free(*nodes); 
}
