    srand(time(0));
    *offsets = (long*)malloc(num * sizeof(long));
    if (*offsets == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    record* records = malloc(num * sizeof(record));
    if (records == NULL) {
        printf("Memory allocation failed\n");
        free(*offsets);
        exit(1);
    }

    *keys = calloc(RAND_MAX, sizeof(int)); // assuming keys are non-negative and less than RAND_MAX
    if (*keys == NULL) {
        printf("Memory allocation failed\n");
        free(*offsets);
        free(records);
        exit(1);
    }

    for (long i = 0; i < num; ++i) {
        int key, value;
        char* string;

        do {  // ensure unique keys
            key = rand() % RAND_MAX;
        } while ((*keys)[key]);
        (*keys)[key] = 1;

        records[i].value = rand(); // assuming values are within int range

        printf("Enter string for record %ld: ", i);
        scanf("%ms", &string);
        records[i].string = string;

        (*offsets)[i] = (long)(&records[i]) - (long)records; // calculate offset
    }

    return records;
}

int main() {
    int num_records = 0;
    printf("Enter number of records: ");
