```cpp
#include <iostream>
#include <mutex>
#include <thread>
#include <string>
#include <vector>

struct Record {
    int key;
    std::string id;
    char* buffer;
};

std::mutex mtx;  // Mutex for locking mechanism
std::vector<Record*> records;

// Function to allocate and initialize a record
void init_record(int key, const std::string& id) {
    Record* rec = new Record();

    if (rec == nullptr){
        throw std::bad_alloc();
    }

    try{
        rec->buffer = new char[256];  // Allocate buffer for record
    } catch(std::bad_alloc& e) {
        delete rec;
        throw e;
    }

    rec->key = key;
    rec->id = id;

    mtx.lock();  // Lock mutex before modifying records
    if (records.size() < records.capacity()) {
        records.push_back(rec);
    } else {
        delete[] rec->buffer;
        delete rec;
    }
    mtx.unlock();  // Unlock mutex after modifying records
}

// Function to handle concurrent access from multiple threads
void allocate_records(int limit) {
    std::vector<std::thread> threads;

    for (int i = 0; i < limit; ++i) {
        try{
            threads.push_back(std::thread(init_record, i, "id_" + std::to_string(i)));  // Start thread
        } catch(std::bad_alloc& e){
            --limit; // Decrease limit if allocation fails to avoid data corruption and future allocations
            i--;    // Retry current iteration (thread creation)
            continue;
        }
    }

    for (auto& th : threads) {
      if(th.joinable()){
          th.join();  // Wait for all threads to finish
      }
    }
}
```
Please note that this code block assumes you are working with a C++ compiler supporting modern C++ standard and threading library provided by the language. It is also simplistic in nature and doesn't implement external data storage systems or advanced logging features.
