    char* UUID = generateUniqueUUID();
    time_t timestamp = time(NULL);

    Transaction transaction = {.UUID=UUID, .description=strdup(description), .amount=amount, .timestamp=timestamp};

    Node *newNode = malloc(sizeof(Node));
