```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned long id;
    unsigned int quantity;
    double price;
} item_t;

typedef struct order_node_s {
    item_t *item;
    time_t date;
    size_t ref_count;
    struct order_node_s *next;
} order_node_t;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static item_t *items = NULL;
static size_t num_items = 0;
static order_node_t *orders = NULL;
static size_t num_orders = 0;

void add_item(unsigned long id, unsigned int quantity, double price) {
    pthread_mutex_lock(&mutex);
    ++num_items;
    items = realloc(items, num_items * sizeof(*items));
    if (!items) {
        --num_items;
        goto error_unlock;
    }
    item_t *new_item = &items[num_items - 1];
    new_item->id = id;
    new_item->quantity = quantity;
    new_item->price = price;
    pthread_mutex_unlock(&mutex);
    return;
error_unlock:
    pthread_mutex_unlock(&mutex);
}

void add_order(unsigned long item_id, time_t date) {
    pthread_mutex_lock(&mutex);
    ++num_orders;
    orders = realloc(orders, num_orders * sizeof(*orders));
    if (!orders) {
        --num_orders;
        goto error_unlock;
    }
    order_node_t *new_order = &orders[num_orders - 1];
    new_order->item = NULL;
    for (size_t i = 0; i < num_items; ++i) {
        if (items[i].id == item_id) {
            new_order->item = &items[i];
            ++new_order->ref_count;
            break;
        }
    }
    new_order->date = date;
    new_order->next = NULL;
    pthread_mutex_unlock(&mutex);
    return;
error_unlock:
    pthread_mutex_unlock(&mutex);
}

void free_all(void) {
    pthread_mutex_lock(&mutex);
    free(items);
    items = NULL;
    num_items = 0;
    order_node_t *curr_order = orders;
    while (curr_order != NULL) {
        order_node_t *next_order = curr_order->next;
        free(curr_order);
        curr_order = next_order;
    }
    orders = NULL;
    num_orders = 0;
    pthread_mutex_unlock(&mutex);
}
```
This code implements a simple inventory management system with two global data structures: an array of items and a linked list of orders. It supports adding new items and orders, and a function to free all allocated memory when done. The `add_order` function assumes that each order references an existing item. If the real-world application requires more complex behavior (e.g., creating a new item if it doesn't already exist), it would need to be implemented separately.

It uses a single mutex for all operations, which simplifies things but could become a bottleneck under high load. It also assumes that the `date` field is unique for each order and will not check this. Depending on your requirements, you might want to use a more complex data structure or algorithm (e.g., a balanced search tree) for orders if performance becomes an issue.
