    address_t shipping_address; 
} order_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

item_t * allocate_items(size_t num_items) {
   pthread_mutex_lock(&lock);
   item_t * items = (item_t *) malloc(num_items* sizeof(item_t));
   for (int i = 0; i < num_items; ++i){
       items[i].components = (component_t *) malloc(sizeof(component_t) * items[i].num_components);  // allocate memory to components array based on item's number of components.
   }
   pthread_mutex_unlock(&lock);
   return items;
}

order_t * allocate_orders(size_t num_orders) {
    pthread_mutex_lock(&lock);
    order_t * orders = (order_t *) malloc(num_orders* sizeof(order_t));
    for (int i = 0; i < num_orders; ++i){
        orders[i].item = (item_t *) malloc(sizeof(item_t));  // allocate memory to item of an order.
   }
    pthread_mutex_unlock(&lock);
    return orders;
}

void deallocate_items(item_t * items, size_t num_items) {
    for (int i = 0; i < num_items; ++i){
        free(items[i].components);  // first free memory of components array.
   }
    free(items);  // then free the memory of items array.
}

void deallocate_orders(order_t * orders, size_t num_orders) {
    for (int i = 0; i < num_orders; ++i){
        free(orders[i].item);  // first free memory of item.
   }
    free(orders);  // then free the memory of orders array.
}
```
