typedef struct event {
    long offset;
    int key;
    record_t record;
    time_t timestamp;
    pthread_mutex_t mutex;
    unsigned long access_count;
    struct event *next; // for slab allocation
} event_t;

#define SLAB_SIZE 1024
event_t **slabs = NULL;
int num_slabs = 0;
pthread_mutex_t slab_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize and allocate memory for events
void initialize(int unique_events) {
    if (unique_events < 0 || unique_events > 10000000) {
        // Handle invalid input parameters
        return;
    }

    num_slabs = unique_events / SLAB_SIZE + 1;
    slabs = malloc(num_slabs * sizeof(event_t*));

    for (int i = 0; i < num_slabs; ++i) {
        slabs[i] = calloc(SLAB_SIZE, sizeof(event_t));

        if (!slabs[i]) {
            // Handle memory allocation failure
            return;
        }
    }

    for (int i = 0; i < num_slabs - 1; ++i) {
        for (int j = 0; j < SLAB_SIZE - 1; ++j) {
            slabs[i][j].next = &slabs[i][j+1];
        }
    }
}

// Free allocated memory and clean up
void deinitialize() {
    for (int i = 0; i < num_slabs; ++i) {
        free(slabs[i]);
    }

    free(slabs);
}

event_t* get_event(long offset, int key) {
    if (offset < 0 || key <= 0) {
        // Handle invalid input parameters
        return NULL;
    }

    pthread_mutex_lock(&slab_lock);
    event_t *e = &slabs[offset / SLAB_SIZE][offset % SLAB_SIZE];
    pthread_mutex_unlock(&slab_lock);

    if (e->key != key) {
        // Event not found or accessed out of order
        return NULL;
    }

    ++e->access_count;
    e->timestamp = time(NULL);
    pthread_mutex_lock(&e->mutex);

    if (e->record.value < 0 || e->record.value > INT_MAX) {
        // Handle invalid value range
        pthread_mutex_unlock(&e->mutex);
        return NULL;
    }

    return e;
}
```
