#include <stdio.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    double timestamp;
} record_t;

record_t* cache[10]; // simple LRU cache
int cache_size = 0, cache_max = 10;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(long offset, int key) {
    pthread_mutex_lock(&lock);
    if (cache_size < cache_max) { // add to cache
        record_t* rec = malloc(sizeof(record_t));
        if (!rec) return;

        rec->offset = offset;
        rec->key = key;
        rec->timestamp = time(NULL);

        cache[cache_size++] = rec;
    } else { // replace LRU record
        record_t* rec = malloc(sizeof(record_t));
        if (!rec) return;

        free(cache[0]); // remove oldest record

        for (int i = 1; i < cache_max; ++i) {
            cache[i - 1] = cache[i]; // shift other records forward
        }
        cache[cache_max - 1] = rec;
    }
    pthread_mutex_unlock(&lock);
}
```

