```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <limits.h>
#include <time.h>
#include <pthread.h>
#include <libpq-fe.h>

typedef struct DatabaseConnection {
    PGconn *conn;
    pthread_mutex_t lock; // for thread safety
} DatabaseConnection;

DatabaseConnection* initializeDB(const char* connectionString) {
    PGconn *conn = PQconnectdb(connectionString);

    if (PQstatus(conn) == CONNECTION_BAD) {
        fprintf(stderr, "Connection to database failed: %s\n", PQerrorMessage(conn));
        exit(1); // Exit the program with error code 
    } else {
        printf("Database connection established\n");
    }

    DatabaseConnection* dbConn = malloc(sizeof(DatabaseConnection));
    dbConn->conn = conn;
    pthread_mutex_init(&dbConn->lock, NULL); // initialize mutex for thread safety

    return dbConn;
}

int executeQuery(DatabaseConnection* dbConn, const char* query) {
    clock_t start = clock();
    pthread_mutex_lock(&dbConn->lock); // lock before performing operations

    PGresult *res = PQexec(dbConn->conn, query);
    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        printf("Query failed: %s\n", PQerrorMessage(dbConn->conn));
        pthread_mutex_unlock(&dbConn->lock); // unlock before returning error
        return -1;
    }

    int rowCount = PQntuples(res);
    printf("Number of rows: %d\n", rowCount);

    clock_t end = clock();
    double timeTaken = ((double) (end - start)) / CLOCKS_PER_SEC; // in seconds
    printf("Query took %f seconds to execute \n", timeTaken);

    PQclear(res);

    pthread_mutex_unlock(&dbConn->lock); // unlock after operation is complete
    return rowCount; 
}
```

Remember that the actual implementation will depend on your specific requirements and database type. For example, you might need to use a different library or API for connecting to your database (like MySQL) depending on your case. This code also doesn't include memory optimization strategies, caching mechanisms or integration with logging frameworks which are mentioned in your constraints but could be added.
