pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(char* key, int value) {
    Node* temp_node = (Node*)malloc(sizeof(Node));
    if(!temp_node){
        printf("Memory allocation failed\n");
        return;
    }

    temp_node->string_key = malloc(strlen(key) + 1);
    strcpy(temp_node->string_key, key);
    temp_node->value = value;
    temp_node->next = NULL;

    pthread_mutex_lock(&lock);
    if(!head){
        head = tail = temp_node;
    } else {
        tail->next = temp_node;
        tail = temp_node;
    }
    pthread_mutex_unlock(&lock);
}

void delete(char* key) {
    Node *temp = head, *prev = NULL;

    while (temp != NULL && strcmp(temp->string_key, key)) {
        prev = temp;
        temp = temp->next;
    }

    if (!temp) return; // Key not found

    pthread_mutex_lock(&lock);
    if (prev != NULL)
        prev->next = temp->next;

    if (head == temp) 
        head = head->next;

    if (tail == temp) 
        tail = prev;

    free(temp->string_key);
    free(temp);
    pthread_mutex_unlock(&lock);
}

// Search function that returns -1 if not found, else returns the value of node
int search(char* key) {
    Node *current = head;  
    while (current != NULL) {
        if (strcmp(current->string_key, key) == 0) 
            return current->value;

        current = current->next;
    }

    return -1; // Key not found
}
