// define the maximum length of a filename
#define MAX_FILENAME 256

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *processFile(void *arg) {
    char *filename = (char *) arg;
    int len = strlen(filename);

    // count the number of digits in the filename
    int digitCount = 0;
    for(int i=0; i<len; i++){
        if(isdigit(filename[i])){
            digitCount++;
        }
    }

    // append this count to the current extension, ensuring the extension is unique among all filenames in the directory.
    char newFilename[MAX_FILENAME] = {0};
    strcpy(newFilename, filename);
    if (len > 0) newFilename[len - 1] = '\0';

    pthread_mutex_lock(&lock);
    sprintf(newFilename + len - 2, "%d", digitCount);
    pthread_mutex_unlock(&lock);

    // If the filename contains any special characters (other than alphanumeric and underscores), prepend a prefix "dynamic_" to the filename. Otherwise, append a suffix "_standard" to the filename before processing the extension modification.
    int i;
    for(i=0; i<len-1; i++){
        if(!isalnum(filename[i]) && filename[i] != '_'){
            sprintf(newFilename, "dynamic_%s", newFilename);
            break;
        }
    }
    if (i == len - 1) {
        strcat(newFilename, "_standard");
    }

    // handle filenames without extensions by appending a default extension after the necessary transformations.
    char *extension = strrchr(filename, '.');
    if (!extension) {
        strcat(newFilename, ".txt");  // change it to your desired default extension
    }

    printf("%s\n", newFilename);
    return NULL;
}

void processDirectory(char *dirname) {
    DIR *d;
    struct dirent *dir;
    d = opendir(dirname);
    if (d) {
        pthread_t threads[1024];  // adjust the size based on your requirements
        int threadCount = 0;

        while ((dir = readdir(d)) != NULL) {
            if (!strcmp(dir->d_name, ".") || !strcmp(dir->d_name, "..")) {
                continue;
            }

            pthread_create(&threads[threadCount], NULL, processFile, dir->d_name);
            threadCount++;
        }

        for (int i = 0; i < threadCount; ++i) {
            pthread_join(threads[i], NULL);
        }

        closedir(d);
    }
}
```
