typedef struct {
    double value;
    char* string_rep;
} dataItem;

// Function to manage memory for an array of custom `dataItem` structures
dataItem *manageMemory(int size) {
    if (size <= 0) {
        fprintf(stderr, "Error: Invalid array size.\n");
        return NULL;
    }

    dataItem* items = malloc(size * sizeof(dataItem));
    // Error handling for out-of-memory conditions
    if (items == NULL) {
        fprintf(stderr, "Error: Out of memory.\n");
        return NULL;
    }

    int i;
    for (i = 0; i < size; i++) {
        items[i].value = (double)i;

        // Allocate separate memory for string representation
        char* str_rep = malloc(12);  // Assuming a maximum length of 11 characters for the number as string, plus one for null-terminator.
        if (str_rep == NULL) {
            fprintf(stderr, "Error: Out of memory.\n");
            break;  // If allocation fails at any point, rollback previous allocations and return NULL
        }

        sprintf(str_rep, "%d", i);
        items[i].string_rep = str_rep;
    }

    if (i < size) {  // If loop broke due to out-of-memory condition
        for (; i >= 0; i--) {
            free(items[i].string_rep);  // Free all previously allocated memory to avoid leaks
        }

        free(items);
        return NULL;
    }

    return items;
}
```
In this code:
