#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <limits.h>

typedef struct dataItem {
    double value;
    char* strValue;
    long lvalue;
    int ivalue;
    double dvalue;
} dataItem;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

dataItem *allocateDataItems(size_t count) {
    if (count > INT_MAX) {
        // Out of range error
        return NULL;
    }

    pthread_mutex_lock(&lock);

    dataItem* items = malloc(sizeof(dataItem)*count);
    if (items == NULL) {
        // Memory allocation failed
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        items[i].value = i + 0.5;

        items[i].strValue = malloc(12);
        if (items[i].strValue == NULL) {
            // Memory allocation failed
            for (int j = 0; j < i; ++j) {
                free(items[j].strValue);
            }
            free(items);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        sprintf(items[i].strValue, "%d", i);
        items[i].lvalue = i;
        items[i].ivalue = i;
        items[i].dvalue = i + 0.5;
    }

    pthread_mutex_unlock(&lock);
    return items;
}

void deallocateDataItems(dataItem* items, size_t count) {
    if (items == NULL) {
        // Null pointer error
        return;
    }

    pthread_mutex_lock(&lock);

    for (int i = 0; i < count; ++i) {
        free(items[i].strValue);
    }
    free(items);

    pthread_mutex_unlock(&lock);
}
```
