    if (dot != NULL) 
        *dot = '\0';

    int new_length = strlen(basename) + length + 1; // For the additional . and the \0 termination
    char *new_filename = malloc((new_length > 255 ? 255 : new_length) + 1); // Allocate memory for the new filename

    if (dot != NULL && length > 0) {
        sprintf(new_filename, "%.*s.%0*d", length, basename, length, length);
    } else if (dot == NULL && length > 0) {
        sprintf(new_filename, "%.254s.%0*d", original, length, length);
    } else {
        strncpy(new_filename, original, 255); // If the new name is too long, just copy it as-is
    }

    free(basename); // Free memory allocated for the base name

    return new_filename;
}

char** generate_filenames(const char **files, int count, int length, const char *extension) {
    // Allocate memory for the array of filenames
    char **new_filenames = malloc(count * sizeof(char*)); 

    for (int i = 0; i < count; ++i) {
        new_filenames[i] = generate_filename(files[i], length, extension); // Generate a new filename for each file
    }

    return new_filenames;
}
