#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct sensor {
    char *timestamp;
    char *location;
    float temperature;
    float humidity;
    int status;
    struct sensor *next;
} Sensor;

Sensor* create_sensor(char *timestamp, char *location, float temp, float humid, int status) {
    Sensor *new_sensor = malloc(sizeof(Sensor));

    new_sensor->timestamp = strdup(timestamp);
    new_sensor->location = strdup(location);
    new_sensor->temperature = temp;
    new_sensor->humidity = humid;
    new_sensor->status = status;

    new_sensor->next = NULL;

    return new_sensor;
}

void add_data(Sensor **head, char *timestamp, char *location, float temp, float humid, int status) {
    Sensor *new_sensor = create_sensor(timestamp, location, temp, humid, status);

    if (*head == NULL) {
        *head = new_sensor;
        return;
    }

    Sensor *last = *head;
    while (last->next != NULL) {
        last = last->next;
    }

    last->next = new_sensor;
}
```
