['Here's an example of how such a function might look in C, including data integrity checks, efficient memory management, and logging:

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <assert.h>
#include <errno.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} record_t;

typedef struct {
    pthread_mutex_t lock;
    size_t count;
    record_t* records;
} array_manager_t;

int initialize(array_manager_t* manager, size_t numRecords) {
    if (numRecords == 0 || numRecords > SIZE_MAX / sizeof(record_t)) {
        errno = ENOMEM;
        return -1;
    }

    srand((unsigned int) time(NULL));  // Seed random number generator
    manager->records = (record_t*) malloc(numRecords * sizeof(record_t));
    if (!manager->records) {
        return -1;
    }

    manager->count = numRecords;
    pthread_mutex_init(&manager->lock, NULL);

    for (size_t i = 0; i < numRecords; ++i) {
        manager->records[i].offset = rand();
        manager->records[i].key = rand() % 1000;  // Assuming keys within [0, 999] range
        manager->records[i].timestamp = (double)rand() / RAND_MAX;  // Random timestamp in range [0, 1]
    }

    return 0;
}

void cleanup(array_manager_t* manager) {
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
}

record_t* getRecord(array_manager_t* manager, size_t index) {
    if (index >= manager->count) {
        errno = EINVAL;  // Invalid argument error
        return NULL;
    }

    pthread_mutex_lock(&manager->lock);
    record_t* record = &manager->records[index];
    assert(record->offset > 0 && "Invalid offset");
    assert(record->key >= 0 && record->key <= 999 && "Invalid key");
    assert(record->timestamp >= 0.0 && record->timestamp <= 1.0 && "Invalid timestamp");
    pthread_mutex_unlock(&manager->lock);

    return record;
}
```
This code provides an initialization function to create and initialize the array, a cleanup function to deallocate memory, and a getRecord function that allows safe concurrent access and validates data integrity. The lock ensures thread safety when accessing individual records. Assertions are used for basic checks on record integrity; more comprehensive validation would be needed in a production environment.
