        size_t newCapacity = memoryManager.capacityRecord * 2;
        if (newCapacity > MAX_THRESHOLD) {
            fprintf(stderr, "Reached maximum threshold of %zu bytes\n", MAX_THRESHOLD);
            abort();
        }
        resizeArray((_Atomic(void*) *)records, memoryManager.capacityRecord, newCapacity * sizeof(record_t));
        memoryManager.capacityRecord = newCapacity;
    }
    (*records)[(*count)++] = record;
    pthread_mutex_unlock(&memoryManager.lock);
}

