FILE *errorFile;

void logError(char* message) {
    pthread_mutex_lock(&mutex);
    fprintf(errorFile, "%s\n", message);
    pthread_mutex_unlock(&mutex);
}

int findMaxValueInArray(int array[], int size){
    if(size == 0) {
        return 0;
    }
    int max = array[0];
    for(int i = 1; i < size; ++i){
        if(array[i] > max){
            max = array[i];
        }
    }
    return max;
}

void processEvents() {
    Event *events = (Event*)malloc(sizeof(Event)*10000);
    int inputValues[1000], size = 0, temp;
    if (!errorFile) {
        errorFile = fopen("log.txt", "w");
        if(!errorFile){
            perror("Failed to open log file\n");
            return;
        }
    }

    while(size < 10000 && scanf("%d", &temp) == 1){
        inputValues[size++] = temp;
    }
    if (size >= 10000) {
        logError("Input exceeded limit. Only the first 10,000 records will be processed.");
    }

    for(int i = 0; i < size; ++i){
        events[i].offset = i + 1;
        if (inputValues[i] > 2147483647 || inputValues[i] < -2147483648) {
            logError("Integer overflow detected.");
            continue;
